function proposeCapabilityRecommendation(context, options) {
  ensureInitialized(context);
  ensureCapabilityDiscoveryDirectories(context);
  const id = normalizeId(requireOption(options, "id"));
  const profileId = normalizeId(requireOption(options, "profile"));
  const profilePath = capabilityProfilePath(context, profileId);
  if (!fs.existsSync(profilePath)) {
    fail(`Capability profile ${profileId} does not exist`);
  }
  const profile = readProjectJson(context, profilePath);
  const input = loadOptionalJsonInput(context, options, "recommendation-json", "recommendation-file", "Capability recommendation");
  const availableCapabilities = loadOptionalJsonInput(
    context,
    options,
    "available-capabilities-json",
    "available-capabilities-file",
    "Available capabilities",
  );
  const attribution = buildAttribution(context, options, "capability.recommend");
  const recommendations = normalizeCapabilityRecommendations(
    input.recommendations || buildDefaultCapabilityRecommendations(profile, availableCapabilities),
  );
  const policyPatch = mergeCapabilityPolicies(
    buildDefaultCapabilityPolicyPatch(recommendations),
    input.policy_patch || input.capability_policy || null,
  );
  const bindings = normalizeCapabilityBindings(input.bindings || input.capability_bindings || []);
  const profileProjectPath = toProjectPath(context, profilePath);
  const sourcePaths = normalizeCapabilitySourcePaths(context, normalizeListValue(input.source_paths, []));
  const recommendation = {
    id,
    schema_version: context.config.schema_version,
    status: "proposed",
    profile_id: profileId,
    profile_ref: {
      path: profileProjectPath,
      approved_content_hash: latestApprovedRecordApproval(profile)?.approved_content_hash || null,
      current_content_hash: hashApprovalSubject(profile),
    },
    recommendations,
    available_capabilities: normalizeObject(availableCapabilities),
    policy_patch: policyPatch,
    bindings,
    execution_policy_suggestions: normalizeExecutionPolicySuggestions(input.execution_policy_suggestions || {}),
    decision_matrix: Array.isArray(input.decision_matrix) ? input.decision_matrix : [],
    open_questions: Array.isArray(input.open_questions) ? input.open_questions : [],
    source_paths: sourcePaths,
    source_hashes: buildSourceHashes(context, sourcePaths),
    approvals: [],
    created_at: now(),
    updated_at: now(),
    audit: {
      proposed_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
  };
  assertRecordSchema(recommendation, "capability-recommendation.schema.json", `Capability recommendation ${id}`);
  const recommendationPath = capabilityRecommendationPath(context, id);
  const releaseLock = acquireFileLock(`${recommendationPath}.lock`);
  try {
    writeJsonFile(recommendationPath, recommendation, { force: Boolean(options.force) });
  } finally {
    releaseLock();
  }
  appendTraceEvent(context, profile.subject?.story_id || null, {
    type: "decision",
    summary: `Proposed capability recommendation ${id}`,
    action: "capability.recommend",
    actor: attribution.actor,
    evidence: [toProjectPath(context, recommendationPath), toProjectPath(context, profilePath)],
    related: [id, profileId, profile.subject?.story_id].filter(Boolean),
    git: attribution.git,
    run: attribution.run,
  });
  const approvalRequest = buildCapabilityRecommendationApprovalRequest(context, recommendation);
  const assistantMessage = renderApprovalRequestsAssistantMessage([approvalRequest]);
  const localizedAssistantLines = approvalAssistantMessageLinesForLocale(
    [approvalRequest],
    options,
    assistantMessage,
  );
  output(
    options,
    {
      status: "proposed",
      recommendation_path: recommendationPath,
      recommendation,
      assistant_message: assistantMessage,
      ...assistantMessagePresentationFields(),
      approval_request: approvalRequest,
    },
    [
      humanGuidanceLocale(options) === "it"
        ? `Proposta la selezione di strumenti ${id}`
        : `Proposed capability recommendation ${id}`,
      "",
      ...localizedAssistantLines,
    ],
  );
}

function approveCapabilityRecommendation(context, options) {
  ensureInitialized(context);
  const id = normalizeId(requireOption(options, "id"));
  const recommendationPath = capabilityRecommendationPath(context, id);
  if (!fs.existsSync(recommendationPath)) {
    fail(`Capability recommendation ${id} does not exist`);
  }
  const attribution = buildAttribution(context, options, "capability.approve");
  requireFormalApprovalActor(context, options, attribution, "Approving a capability recommendation");
  const requestedApprovalSource = String(getOptionString(options, "approval-source") || "").trim().toLowerCase();
  const directInstallApproval =
    (requestedApprovalSource === "explicit-user" && attribution.actor.type === "human") ||
    ((requestedApprovalSource === "ci" || (!requestedApprovalSource && attribution.actor.type === "ci")) && attribution.actor.type === "ci");
  if (options["approve-install"] && !directInstallApproval) {
    fail("Approving capability installation requires direct explicit-user or CI approval; delegated automation cannot expand into installs.");
  }
  let recommendation;
  let profile;
  let approval;
  const releaseLock = acquireFileLock(`${recommendationPath}.lock`);
  try {
    recommendation = readProjectJson(context, recommendationPath);
    profile = readCapabilityProfile(context, recommendation.profile_id);
    validateApprovedCapabilityProfileForUse(context, profile, `capability profile ${recommendation.profile_id}`);
    validateCapabilityRecordSourceHashes(context, recommendation, `capability recommendation ${id}`, { failOnStale: true });
    if (options["approve-install"]) {
      recommendation.recommendations = (recommendation.recommendations || []).map((item) =>
        item.install_required ? { ...item, install_approved: true, install_approved_at: now(), install_approved_by: attribution.actor } : item,
      );
    }
    recommendation.profile_ref = {
      path: toProjectPath(context, capabilityProfilePath(context, recommendation.profile_id)),
      approved_content_hash: latestApprovedRecordApproval(profile)?.approved_content_hash || null,
      current_content_hash: hashApprovalSubject(profile),
    };
    approval = buildApprovalRecord(context, options, attribution, {
      subject: recommendation,
      subject_id_field: "recommendation_id",
      subject_id: id,
      scope: options.scope || "capability-recommendation",
      label: `capability recommendation ${id}`,
    });
    recommendation.status = "approved";
    recommendation.approvals = Array.isArray(recommendation.approvals) ? recommendation.approvals : [];
    recommendation.approvals.push(approval);
    recommendation.updated_at = now();
    recommendation.audit = {
      ...(recommendation.audit || {}),
      approved_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    };
    writeJsonFile(recommendationPath, recommendation, { force: true });
  } finally {
    releaseLock();
  }
  appendTraceEvent(context, profile.subject?.story_id || null, {
    type: "gate",
    summary: `Approved capability recommendation ${id}`,
    action: "capability.approve",
    actor: attribution.actor,
    evidence: [toProjectPath(context, recommendationPath)],
    related: [id, recommendation.profile_id, profile.subject?.story_id].filter(Boolean),
    git: attribution.git,
    run: attribution.run,
  });
  output(options, { status: "approved", recommendation_path: recommendationPath, approval, recommendation }, [`Approved capability recommendation ${id}`]);
}

function showCapabilityStatus(context, options) {
  ensureInitialized(context);
  const storyId = options.story ? normalizeId(String(options.story)) : null;
  const profileId = options.profile ? normalizeId(String(options.profile)) : null;
  const profiles = readCapabilityProfiles(context).filter((profile) => {
    if (profileId && profile.id !== profileId) {
      return false;
    }
    return !storyId || profile.subject?.story_id === storyId;
  });
  const profileIds = new Set(profiles.map((profile) => profile.id));
  const recommendations = readCapabilityRecommendations(context).filter((recommendation) => {
    if (profileId && recommendation.profile_id !== profileId) {
      return false;
    }
    return !storyId || profileIds.has(recommendation.profile_id);
  });
  const scopedStoryId = storyId || (
    profiles.length === 1 ? profiles[0].subject?.story_id || null : null
  );
  const executionContext = scopedStoryId
    ? executionContextForStory(context, scopedStoryId)
    : null;
  const status = {
    profiles: profiles.map((profile) => capabilityRecordStatus(
      context,
      profile,
      `capability profile ${profile.id}`,
      { executionContext, bindingKind: "capability_profile" },
    )),
    recommendations: recommendations.map((recommendation) =>
      capabilityRecordStatus(
        context,
        recommendation,
        `capability recommendation ${recommendation.id}`,
        { executionContext, bindingKind: "capability_recommendation" },
      ),
    ),
  };
  output(
    options,
    status,
    [
      `Capability profiles: ${status.profiles.length}`,
      ...status.profiles.map((profile) => `${profile.id}: ${profile.status}${profile.fresh ? "" : " (stale)"}`),
      `Capability recommendations: ${status.recommendations.length}`,
      ...status.recommendations.map((recommendation) => `${recommendation.id}: ${recommendation.status}${recommendation.fresh ? "" : " (stale)"}`),
    ],
  );
}

function ensurePlanningDirectories(context) {
  ensureDir(workItemsRoot(context));
  ensureDir(path.join(workItemsRoot(context), "epics"));
  ensureDir(path.join(workItemsRoot(context), "tasks"));
  ensureDir(workBreakdownRoot(context));
  ensureDir(dependenciesRoot(context));
}

function workItemsRoot(context) {
  return path.join(context.sdlcRoot, "work-items");
}

function workBreakdownRoot(context) {
  return path.join(context.sdlcRoot, "work-breakdown");
}

function dependenciesRoot(context) {
  return path.join(context.sdlcRoot, "dependencies");
}

function capabilityDiscoveryRoot(context) {
  return path.join(context.sdlcRoot, "capability-discovery");
}

function capabilityProfilesRoot(context) {
  return path.join(capabilityDiscoveryRoot(context), "profiles");
}

function capabilityRecommendationsRoot(context) {
  return path.join(capabilityDiscoveryRoot(context), "recommendations");
}

function ensureCapabilityDiscoveryDirectories(context) {
  ensureDir(capabilityDiscoveryRoot(context));
  ensureDir(capabilityProfilesRoot(context));
  ensureDir(capabilityRecommendationsRoot(context));
}

function baselineRoot(context) {
  return path.join(context.sdlcRoot, "baseline");
}

function ensureBaselineDirectory(context) {
  ensureDir(baselineRoot(context));
}

function baselinePathById(context, id) {
  return path.join(baselineRoot(context), `${normalizeId(id)}.json`);
}

function readBaselines(context) {
  return safeReadDir(baselineRoot(context))
    .filter((name) => name.endsWith(".json"))
    .map((name) => readProjectJson(context, path.join(baselineRoot(context), name)))
    .sort((a, b) => {
      const createdComparison = String(a.created_at || "").localeCompare(String(b.created_at || ""));
      return createdComparison || String(a.id).localeCompare(String(b.id));
    });
}

function buildBaselineDocumentEvidence(context, rawPath) {
  const snapshot = stableContextSourceSnapshot(context, rawPath, "Baseline document");
  const resolved = snapshot.filePath;
  const content = snapshot.content;
  const text = content.toString("utf8");
  return {
    type: "document",
    path: snapshot.projectPath,
    sha256: snapshot.sha256,
    size_bytes: content.length,
    title: inferTitle(resolved, text),
    headings: text
      .split(/\r?\n/)
      .map((line) => line.match(/^#{1,4}\s+(.+)$/)?.[1]?.trim())
      .filter(Boolean)
      .slice(0, 12),
    excerpt: safeEvidenceExcerpt(resolved, text, 800),
    trust: "untrusted_project_evidence",
  };
}

function normalizeBaselineSourcePaths(context, rawPaths) {
  for (const rawPath of rawPaths) {
    const resolved = resolveProjectFilePath(context, rawPath, { mustExist: true });
    assertContextSourcePathSafe(context, resolved, "Baseline source");
  }
  const discovery = discoverBaselineSourcePaths({
    projectRoot: context.root,
    requestedPaths: rawPaths,
    policy: context.config.baseline_policy,
  });
  if (discovery.truncated) {
    fail(
      `Baseline source discovery reached its ${discovery.policy.max_discovered_files}-file limit. `
      + "Narrow --source or raise baseline_policy.max_discovered_files explicitly; no silent partial baseline was created.",
    );
  }
  return discovery.paths;
}

function buildRepositorySnapshot(context, detectedStack = detectProjectStack(context)) {
  const keyFiles = collectProjectKeyFiles(context);
  return {
    root_name: path.basename(context.root),
    git: buildGitMetadata(context.root),
    detected_stack: detectedStack,
    key_files: keyFiles,
    package_scripts: readPackageScripts(context),
    package_summary: readPackageSummary(context),
    source_roots: inferSourceRoots(context),
    test_roots: inferTestRoots(context),
    ci_files: keyFiles.filter((item) => item.path.startsWith(".github/") || item.path.includes("ci") || item.path.includes("workflow")),
  };
}

function readPackageSummary(context) {
  const packageJsonPath = path.join(context.root, "package.json");
  if (!fs.existsSync(packageJsonPath)) {
    return null;
  }
  try {
    const pkg = readProjectJson(context, packageJsonPath);
    return {
      name: pkg.name || null,
      description: pkg.description || null,
      version: pkg.version || null,
      private: Boolean(pkg.private),
      runtime_dependencies: Object.keys(pkg.dependencies || {}).sort(),
      development_dependencies: Object.keys(pkg.devDependencies || {}).sort(),
    };
  } catch {
    return null;
  }
}

function collectProjectKeyFiles(context) {
  const candidates = [
    "README.md",
    "package.json",
    "pnpm-lock.yaml",
    "package-lock.json",
    "yarn.lock",
    "tsconfig.json",
    "jsconfig.json",
    "vite.config.js",
    "vite.config.ts",
    "next.config.js",
    "next.config.mjs",
    "pyproject.toml",
    "requirements.txt",
    "Dockerfile",
    "docker-compose.yml",
    "go.mod",
    "Cargo.toml",
    "Package.swift",
    ".github/workflows",
  ];
  const files = [];
  for (const candidate of candidates) {
    const resolved = path.join(context.root, candidate);
    if (!fs.existsSync(resolved)) {
      continue;
    }
    const stat = fs.statSync(resolved);
    if (stat.isDirectory()) {
      for (const filePath of walkFiles(resolved)) {
        if (shouldIndexFile(context, filePath)) {
          files.push(fileSummary(context, filePath));
        }
      }
    } else if (stat.isFile()) {
      files.push(fileSummary(context, resolved));
    }
  }
  return files.sort((a, b) => a.path.localeCompare(b.path));
}

function fileSummary(context, filePath) {
  return {
    path: toProjectPath(context, filePath),
    sha256: hashFile(filePath),
    size_bytes: fs.statSync(filePath).size,
  };
}

function readPackageScripts(context) {
  const packageJsonPath = path.join(context.root, "package.json");
  if (!fs.existsSync(packageJsonPath)) {
    return {};
  }
  try {
    const pkg = readProjectJson(context, packageJsonPath);
    return normalizeObject(pkg.scripts);
  } catch {
    return {};
  }
}

function inferSourceRoots(context) {
  return ["src", "app", "pages", "lib", "bin", "server", "client"]
    .filter((entry) => fs.existsSync(path.join(context.root, entry)) && fs.statSync(path.join(context.root, entry)).isDirectory());
}

function inferTestRoots(context) {
  return ["test", "tests", "__tests__", "spec", "e2e"]
    .filter((entry) => fs.existsSync(path.join(context.root, entry)) && fs.statSync(path.join(context.root, entry)).isDirectory());
}

function buildInferredContext(repoSnapshot, detectedStack, documents) {
  const primaryDocument = documents.find((document) => /(^|\/)readme\./i.test(document.path)) || documents[0] || null;
  return {
    product_signal: repoSnapshot.package_summary?.description || primaryDocument?.excerpt || null,
    document_map: documents.map((document) => ({
      path: document.path,
      title: document.title || null,
      headings: document.headings || [],
      summary: document.excerpt || null,
    })),
    architecture_signals: documents
      .filter((document) => /architecture|design|adr|api|requirement/i.test(`${document.path} ${(document.headings || []).join(" ")}`))
      .map((document) => ({ path: document.path, headings: document.headings || [], summary: document.excerpt || null })),
    component_roots: repoSnapshot.source_roots || [],
    runtime_and_validation_scripts: repoSnapshot.package_scripts || {},
    stack_summary: detectedStack.map((item) => `${item.type}:${item.name}`),
    likely_entrypoints: repoSnapshot.key_files.map((item) => item.path),
    test_surface: Object.keys(repoSnapshot.package_scripts || {}).filter((script) => /test|check|lint|smoke/i.test(script)),
    imported_document_count: documents.length,
    confidence: detectedStack.length > 0 || documents.length > 0 ? 0.7 : 0.35,
    caveats: [
      "This is inferred from repository files and imported documents.",
      "Historical authorship, prior approvals, and rationale are unknown unless present in evidence files.",
    ],
  };
}

function renderBaselineReport(baseline) {
  return [
    `# ${baseline.id} Current State`,
    "",
    `Status: ${baseline.status}`,
    `Kind: ${baseline.kind}`,
    "",
    "## Summary",
    baseline.summary || "No summary provided.",
    "",
    "## Product Signal",
    baseline.inferred_context?.product_signal || "Not evidenced.",
    "",
    "## Architecture And Component Signals",
    ...listOrNone([
      ...(baseline.inferred_context?.component_roots || []).map((root) => `Source root: ${root}`),
      ...(baseline.inferred_context?.architecture_signals || []).map((item) => `${item.path}: ${(item.headings || []).join(" > ") || item.summary || "architecture evidence"}`),
    ]),
    "",
    "## Detected Stack",
    ...listOrNone((baseline.repository_snapshot?.detected_stack || []).map((item) => `${item.type}: ${item.name}${item.source_path ? ` (${item.source_path})` : ""}`)),
    "",
    "## Key Files",
    ...listOrNone((baseline.repository_snapshot?.key_files || []).map((item) => `${item.path} (${item.sha256})`)),
    "",
    "## Imported Documents",
    ...listOrNone((baseline.imported_documents || []).map((item) => `${item.path}: ${item.title || "Untitled"}; sections ${(item.headings || []).join(" > ") || "not detected"}; evidence ${item.sha256}`)),
    "",
    "## Open Questions",
    ...listOrNone(baseline.open_questions || []),
    "",
    "## Caveats",
    ...listOrNone(baseline.inferred_context?.caveats || []),
    "",
    "## Approval Guidance",
    "Approve this baseline only after the user confirms which inferred facts are canonical. Use bootstrap only for migration/provisional records.",
    "",
  ].join("\n");
}

function listOrNone(values) {
  return values.length ? values.map((value) => `- ${value}`) : ["- None"];
}

function validateBaselineSourceHashes(context, baseline, label, options = {}) {
  const issues = [];
  const sourceHashes = baseline.source_hashes || {};
  const sourcePaths = new Set([...(baseline.source_paths || []), ...Object.keys(sourceHashes)]);
  for (const sourcePath of sourcePaths) {
    const expectedHash = sourceHashes[sourcePath];
    if (!expectedHash) {
      issues.push(`${label} source ${sourcePath} has no recorded hash`);
    } else {
      let currentMatches = false;
      let safeSnapshot = false;
      let snapshotError = null;
      try {
        const snapshot = stableContextSourceSnapshot(context, sourcePath, "Baseline source");
        safeSnapshot = true;
        currentMatches = snapshot.sha256 === expectedHash;
      } catch (error) {
        snapshotError = error.message;
      }
      if (currentMatches) continue;
      const evolution = safeSnapshot && options.executionContext
        ? executionContextSourceEvolution(context, {
            ...options.executionContext,
            sourcePath,
            expectedSha256: expectedHash,
            bindingKind: "baseline",
            bindingId: baseline.id,
          })
        : { allowed: false };
      if (!evolution.allowed) {
        issues.push(
          snapshotError
            ? `${label} source ${sourcePath} is unsafe: ${snapshotError}`
            : `${label} source ${sourcePath} is missing or changed outside its approved pre-change snapshot. `
              + executionContextRecoveryMessage(sourcePath),
        );
      }
    }
  }
  if (options.failOnStale && issues.length > 0) {
    fail(issues.join("; "));
  }
  if (options.collectOnly) {
    return issues;
  }
  return issues;
}

function capabilityProfilePath(context, id) {
  return path.join(capabilityProfilesRoot(context), `${normalizeId(id)}.json`);
}

function capabilityRecommendationPath(context, id) {
  return path.join(capabilityRecommendationsRoot(context), `${normalizeId(id)}.json`);
}

function readCapabilityProfile(context, id) {
  const profilePath = capabilityProfilePath(context, id);
  if (!fs.existsSync(profilePath)) {
    fail(`Capability profile ${id} does not exist`);
  }
  return readProjectJson(context, profilePath);
}

function readCapabilityProfiles(context) {
  return safeReadDir(capabilityProfilesRoot(context))
    .filter((name) => name.endsWith(".json"))
    .map((name) => readProjectJson(context, path.join(capabilityProfilesRoot(context), name)))
    .sort((a, b) => String(a.id).localeCompare(String(b.id)));
}

function readCapabilityRecommendations(context) {
  return safeReadDir(capabilityRecommendationsRoot(context))
    .filter((name) => name.endsWith(".json"))
    .map((name) => readProjectJson(context, path.join(capabilityRecommendationsRoot(context), name)))
    .sort((a, b) => String(a.id).localeCompare(String(b.id)));
}

function loadOptionalJsonInput(context, options, inlineKey, fileKey, label) {
  const inline = getOptionString(options, inlineKey);
  const file = getOptionString(options, fileKey);
  if (inline && file) {
    fail(`Use only one of --${inlineKey} or --${fileKey}.`);
  }
  if (!inline && !file) {
    return {};
  }
  try {
    if (file) {
      const filePath = resolveProjectFilePath(context, file, { mustExist: true, fileOnly: true });
      assertNotDerivedArtifact(context, filePath, label);
      return JSON.parse(readProjectText(context, filePath));
    }
    return JSON.parse(inline);
  } catch (error) {
    fail(`Invalid ${label} JSON: ${error.message}`);
  }
}

function normalizeCapabilitySubject(options, subject) {
  const requirementIds = mergeList(
    normalizeListValue(subject.requirement_ids || subject.requirements, []),
    normalizeListOption(options.requirement),
  ).map(normalizeId);
  return {
    story_id: options.story ? normalizeId(String(options.story)) : subject.story_id ? normalizeId(subject.story_id) : null,
    requirement_ids: requirementIds,
    phase: options.phase ? normalizeRoutePhase(options.phase) : subject.phase ? normalizeRoutePhase(subject.phase) : null,
    scope: String(options.scope || subject.scope || "project"),
  };
}

function normalizeCapabilityEvidence(evidence) {
  if (!Array.isArray(evidence)) {
    return [];
  }
  return evidence
    .filter((item) => item && typeof item === "object" && !Array.isArray(item))
    .map((item) => ({
      type: String(item.type || "evidence"),
      path: item.path ? String(item.path) : null,
      summary: item.summary ? String(item.summary) : null,
      sha256: item.sha256 ? String(item.sha256) : null,
    }));
}

function buildCapabilityEvidenceFromContextFiles(context, contextFiles) {
  return contextFiles.map((rawPath) => {
    const snapshot = stableContextSourceSnapshot(context, rawPath, "Capability context file");
    const resolved = snapshot.filePath;
    const content = snapshot.content;
    return {
      type: "context_file",
      path: snapshot.projectPath,
      sha256: snapshot.sha256,
      size_bytes: content.length,
      excerpt: safeEvidenceExcerpt(resolved, content.toString("utf8"), 600),
      trust: "untrusted_project_evidence",
    };
  });
}

function normalizeCapabilitySourcePaths(context, rawPaths) {
  const result = [];
  for (const rawPath of rawPaths) {
    if (!rawPath) {
      continue;
    }
    const snapshot = stableContextSourceSnapshot(context, rawPath, "Capability source path");
    result.push(snapshot.projectPath);
  }
  return Array.from(new Set(result)).sort();
}

function buildSourceHashes(context, sourcePaths) {
  const hashes = {};
  for (const sourcePath of sourcePaths || []) {
    const snapshot = stableContextSourceSnapshot(context, sourcePath, "Canonical context source");
    hashes[sourcePath] = snapshot.sha256;
  }
  return hashes;
}

function normalizeObject(value) {
  return value && typeof value === "object" && !Array.isArray(value) ? value : {};
}

function normalizeConfidence(value) {
  const confidence = Number(value);
  if (!Number.isFinite(confidence)) {
    fail("Capability confidence must be a number between 0 and 1");
  }
  return clamp01(confidence);
}

function normalizeCapabilityRecommendations(recommendations) {
  if (!Array.isArray(recommendations)) {
    fail("Capability recommendations must be an array");
  }
  return recommendations.map((item, index) => {
    if (!item || typeof item !== "object" || Array.isArray(item)) {
      fail(`Capability recommendation ${index + 1} must be a JSON object`);
    }
    const type = normalizeCapabilityItemType(item.type);
    const name = String(item.name || "").trim();
    if (!name) {
      fail(`Capability recommendation ${index + 1} is missing name`);
    }
    const availability = normalizeCapabilityAvailability(item.availability || item.status || "unknown");
    const installRequired = Boolean(item.install_required || availability === "install_required");
    return {
      type,
      name,
      availability: installRequired ? "install_required" : availability,
      purpose: item.purpose ? String(item.purpose) : null,
      rationale: item.rationale ? String(item.rationale) : null,
      risk: item.risk ? String(item.risk) : null,
      permissions: normalizeListValue(item.permissions, []),
      install_required: installRequired,
      install_approved: Boolean(item.install_approved),
      approval_required: item.approval_required !== undefined ? Boolean(item.approval_required) : installRequired,
    };
  });
}

function normalizeCapabilityItemType(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (!["skill", "mcp", "tool", "plugin", "connector", "model"].includes(normalized)) {
    fail(`Unknown capability recommendation type '${value}'`);
  }
  return normalized;
}

function normalizeCapabilityAvailability(value) {
  const normalized = String(value || "unknown").trim().toLowerCase();
  if (!CAPABILITY_RECOMMENDATION_AVAILABILITY.has(normalized)) {
    fail(`Unknown capability availability '${value}'`);
  }
  return normalized;
}

function buildDefaultCapabilityRecommendations(profile, availableCapabilities) {
  const availableSkills = new Set(normalizeAvailableCapabilityNames(availableCapabilities, "skills"));
  const recommendations = [
    {
      type: "skill",
      name: "agentic-sdlc",
      // This default is produced by the running Agentic SDLC plugin itself.
      // The optional inventory is needed only to attest additional host
      // capabilities; absence of that inventory must not make the plugin's own
      // intrinsic governance capability unusable after approval.
      availability: "available",
      purpose: "Govern the work through contracts, gates, traces, and shared project KB.",
      rationale: availableSkills.has("agentic-sdlc")
        ? "The reviewed inventory and the running plugin both confirm this capability."
        : "The running plugin provides this intrinsic governance capability.",
      install_required: false,
    },
  ];
  const hasNode = (profile.detected_stack || []).some((item) => ["node", "npm", "package-json"].includes(item.name) || item.type === "node");
  if (hasNode) {
    recommendations.push({
      type: "tool",
      name: "test-runner",
      availability: "available",
      purpose: "Run the repository's Node checks and tests.",
      rationale: "package.json is present and exposes the project test surface.",
      permissions: ["read", "execute"],
      install_required: false,
    });
  }
  const declaredGroups = [
    ["skills", "skill"],
    ["tools", "tool"],
    ["mcp", "mcp"],
    ["plugins", "plugin"],
    ["connectors", "connector"],
    ["models", "model"],
  ];
  const recommendedKeys = new Set(recommendations.map((item) => `${item.type}\0${item.name}`));
  for (const [group, type] of declaredGroups) {
    for (const item of normalizeAvailableCapabilityEntries(availableCapabilities, group)) {
      const key = `${type}\0${item.name}`;
      if (recommendedKeys.has(key) || item.recommended === false) continue;
      recommendations.push({
        type,
        name: item.name,
        availability: "available",
        purpose: item.purpose || item.description || `Use the declared available ${type} capability for this work.`,
        rationale: item.rationale || "The capability was supplied in the reviewed available-capabilities inventory.",
        permissions: normalizeListValue(item.permissions, type === "tool" ? ["read", "execute"] : []),
        install_required: false,
      });
      recommendedKeys.add(key);
    }
  }
  return recommendations;
}

function normalizeAvailableCapabilityEntries(availableCapabilities, key) {
  const value = availableCapabilities?.[key] || availableCapabilities?.[key.replace(/s$/, "")] || [];
  const rawEntries = Array.isArray(value)
    ? value
    : value && typeof value === "object"
      ? value.installed || value.available || value.names || []
      : [];
  return (Array.isArray(rawEntries) ? rawEntries : [])
    .map((item) => typeof item === "string" ? { name: item } : item)
    .filter((item) => item && typeof item === "object" && !Array.isArray(item))
    .map((item) => ({ ...item, name: String(item.name || "").trim() }))
    .filter((item) => item.name);
}

function normalizeAvailableCapabilityNames(availableCapabilities, key) {
  return normalizeAvailableCapabilityEntries(availableCapabilities, key).map((item) => item.name);
}

function buildDefaultCapabilityPolicyPatch(recommendations) {
  const policy = buildCapabilityPolicy(null);
  for (const item of recommendations) {
    const group = item.install_required ? "required" : "allowed";
    if (item.type === "skill") {
      pushAllUnique(policy.skills[group], [item.name]);
    } else if (item.type === "mcp") {
      pushAllUnique(policy.mcp[group], [item.name]);
    } else if (item.type === "tool") {
      pushAllUnique(policy.tools[group], [item.name]);
    }
    if (item.approval_required) {
      pushAllUnique(policy.approval_required_for, [`${item.type}:${item.name}`]);
    }
  }
  return policy;
}

function detectProjectStack(context) {
  const detections = [];
  const add = (name, type, sourcePath, details = {}) => {
    detections.push({
      name,
      type,
      source_path: sourcePath,
      ...details,
    });
  };
  const has = (relativePath) => fs.existsSync(path.join(context.root, relativePath));
  if (has("package.json")) {
    const packageJsonPath = path.join(context.root, "package.json");
    add("package-json", "node", "package.json");
    try {
      const pkg = readProjectJson(context, packageJsonPath);
      const deps = { ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) };
      for (const [dependency, type] of Object.entries({
        next: "web-framework",
        react: "frontend-library",
        vue: "frontend-framework",
        "@angular/core": "frontend-framework",
        svelte: "frontend-framework",
        vite: "build-tool",
        typescript: "language",
        jest: "test-runner",
        vitest: "test-runner",
        playwright: "browser-test-runner",
      })) {
        if (deps[dependency]) {
          add(dependency, type, "package.json", { version: deps[dependency] });
        }
      }
      if (pkg.scripts && Object.keys(pkg.scripts).length > 0) {
        add("npm-scripts", "automation", "package.json", { scripts: Object.keys(pkg.scripts).sort() });
      }
    } catch {
      add("package-json-unreadable", "warning", "package.json");
    }
  }
  for (const [relativePath, name, type] of [
    ["tsconfig.json", "typescript", "language"],
    ["next.config.js", "next", "web-framework"],
    ["next.config.mjs", "next", "web-framework"],
    ["vite.config.js", "vite", "build-tool"],
    ["vite.config.ts", "vite", "build-tool"],
    ["pyproject.toml", "python", "language"],
    ["requirements.txt", "python-requirements", "dependency-file"],
    ["Dockerfile", "docker", "container"],
    ["docker-compose.yml", "docker-compose", "container"],
    ["go.mod", "go", "language"],
    ["Cargo.toml", "rust", "language"],
    ["Package.swift", "swift-package", "language"],
    ["build.gradle", "gradle", "build-tool"],
    ["pom.xml", "maven", "build-tool"],
    ["terraform.tf", "terraform", "infrastructure"],
  ]) {
    if (has(relativePath)) {
      add(name, type, relativePath);
    }
  }
  return detections;
}

function findApprovedCapabilityProfiles(context, options = {}) {
  return readCapabilityProfiles(context).filter((profile) => {
    if (profile.status !== "approved" || !isApprovedRecordFresh(profile)) {
      return false;
    }
    if (validateCapabilityRecordSourceHashes(context, profile, `capability profile ${profile.id}`, { collectOnly: true }).length > 0) {
      return false;
    }
    if (options.storyId && profile.subject?.story_id && profile.subject.story_id !== options.storyId) {
      return false;
    }
    if (options.phase && profile.subject?.phase && profile.subject.phase !== options.phase) {
      return false;
    }
    return true;
  });
}

function capabilityRecordStatus(context, record, label, options = {}) {
  const staleSources = validateCapabilityRecordSourceHashes(context, record, label, {
    collectOnly: true,
    executionContext: options.executionContext || null,
    bindingKind: options.bindingKind,
  });
  return {
    id: record.id,
    status: record.status || "unknown",
    fresh: staleSources.length === 0 && (record.status !== "approved" || isApprovedRecordFresh(record)),
    stale_sources: staleSources,
    source_paths: record.source_paths || [],
  };
}

function validateCapabilityRecordSourceHashes(context, record, label, options = {}) {
  const issues = [];
  const sourceHashes = record.source_hashes || {};
  const sourcePaths = new Set([...(record.source_paths || []), ...Object.keys(sourceHashes)]);
  for (const sourcePath of sourcePaths) {
    const expectedHash = sourceHashes[sourcePath];
    if (!expectedHash) {
      issues.push(`${label} source ${sourcePath} has no recorded hash`);
    } else {
      let currentMatches = false;
      let safeSnapshot = false;
      let snapshotError = null;
      try {
        const snapshot = stableContextSourceSnapshot(context, sourcePath, "Capability source");
        safeSnapshot = true;
        currentMatches = snapshot.sha256 === expectedHash;
      } catch (error) {
        snapshotError = error.message;
      }
      if (currentMatches) continue;
      const evolution = safeSnapshot && options.executionContext
        ? executionContextSourceEvolution(context, {
            ...options.executionContext,
            sourcePath,
            expectedSha256: expectedHash,
            bindingKind: options.bindingKind || "capability_profile",
            bindingId: record.id,
          })
        : { allowed: false };
      if (!evolution.allowed) {
        issues.push(
          snapshotError
            ? `${label} source ${sourcePath} is unsafe: ${snapshotError}`
            : `${label} source ${sourcePath} changed after record creation and is missing or changed outside its approved pre-change snapshot. `
              + executionContextRecoveryMessage(sourcePath),
        );
      }
    }
  }
  if (options.failOnStale && issues.length > 0) {
    fail(issues.join("; "));
  }
  if (options.collectOnly) {
    return issues;
  }
  return issues;
}

function validateApprovedCapabilityProfileForUse(context, profile, label, options = {}) {
  if (!profile || profile.status !== "approved" || !isApprovedRecordFresh(profile)) {
    fail(`${label} is not approved or its approval is stale`);
  }
  validateCapabilityRecordSourceHashes(context, profile, label, {
    failOnStale: true,
    executionContext: options.executionContext || null,
    bindingKind: "capability_profile",
  });
}

function validateApprovedCapabilityRecommendationForUse(context, recommendation, label, options = {}) {
  if (!recommendation || recommendation.status !== "approved" || !isApprovedRecordFresh(recommendation)) {
    fail(`${label} is not approved or its approval is stale`);
  }
  validateCapabilityRecordSourceHashes(context, recommendation, label, {
    failOnStale: true,
    executionContext: options.executionContext || null,
    bindingKind: "capability_recommendation",
  });
  const profile = readCapabilityProfile(context, recommendation.profile_id);
  validateApprovedCapabilityProfileForUse(
    context,
    profile,
    `capability profile ${recommendation.profile_id}`,
    options,
  );
  for (const item of recommendation.recommendations || []) {
    if (item.install_required && !item.install_approved) {
      fail(`${label} requires installation of ${item.type}:${item.name} without install approval`);
    }
  }
}

function workItemPath(context, type, id) {
  const directory = type === "epic" ? "epics" : type === "task" ? "tasks" : `${type}s`;
  return path.join(workItemsRoot(context), directory, `${id}.json`);
}

function breakdownPathById(context, id) {
  return path.join(workBreakdownRoot(context), `${id}.json`);
}

function dependencyProposalPath(context, id) {
  return path.join(dependenciesRoot(context), `${id}.json`);
}

function dependencyGraphPath(context) {
  return path.join(dependenciesRoot(context), "graph.json");
}

function normalizeWorkItemType(value, options = {}) {
  const normalized = String(value || "").trim().toLowerCase().replace(/\s+/g, "-");
  const allowed = options.allowStory ? WORK_ITEM_TYPES : WORK_ITEM_CREATE_TYPES;
  if (!allowed.has(normalized)) {
    fail(`Unknown work item type '${value}'. Valid values: ${Array.from(allowed).join(", ")}`);
  }
  return normalized;
}

function parseBreakdownItemRef(value) {
  const parts = String(value || "").split(":").map((part) => part.trim());
  if (parts.length !== 2 || parts.some((part) => !part)) {
    fail("Breakdown items must use --item type:id");
  }
  return {
    type: normalizeWorkItemType(parts[0], { allowStory: true }),
    id: normalizeId(parts[1]),
  };
}

function parseDependencyEdge(value) {
  const parts = String(value || "").split(":").map((part) => part.trim());
  if (parts.length !== 5 || parts.some((part) => !part)) {
    fail("Dependency edges must use --edge from:to:type:blocks:required_state");
  }
  const [from, to, type, blocks, requiredState] = parts;
  const normalizedType = String(type).trim().toLowerCase();
  const normalizedBlocks = String(blocks).trim().toLowerCase();
  if (!DEPENDENCY_TYPES.has(normalizedType)) {
    fail(`Unknown dependency type '${type}'. Valid values: ${Array.from(DEPENDENCY_TYPES).join(", ")}`);
  }
  if (!DEPENDENCY_BLOCK_SCOPES.has(normalizedBlocks)) {
    fail(`Unknown dependency blocking scope '${blocks}'. Valid values: ${Array.from(DEPENDENCY_BLOCK_SCOPES).join(", ")}`);
  }
  return {
    from: normalizeId(from),
    to: normalizeId(to),
    type: normalizedType,
    blocks: normalizedBlocks,
    required_state: String(requiredState).trim().toLowerCase(),
  };
}

function readEffectiveBreakdownPolicy(context) {
  const configured = context.config.work_breakdown_policy || {};
  const defaults = {
    levels: ["requirement", "epic", "story", "task"],
    default_flow: ["requirement", "story"],
    optional_levels: ["epic", "task"],
    delivery_unit: "story",
    claimable_units: ["story", "task"],
    strict_gate_unit: "story",
    task_gate: "light",
  };
  const policyPath = path.join(workBreakdownRoot(context), "project-policy.json");
  const projectPolicy = fs.existsSync(policyPath) ? readProjectJson(context, policyPath).policy || {} : {};
  const policy = {
    ...defaults,
    ...configured,
    ...projectPolicy,
  };
  policy.levels = normalizeListValue(policy.levels, defaults.levels).map((item) => normalizeWorkItemType(item, { allowStory: true }));
  policy.default_flow = normalizeListValue(policy.default_flow, defaults.default_flow);
  policy.optional_levels = normalizeListValue(policy.optional_levels, defaults.optional_levels);
  policy.claimable_units = normalizeListValue(policy.claimable_units, defaults.claimable_units).map((item) => normalizeWorkItemType(item, { allowStory: true }));
  policy.delivery_unit = normalizeWorkItemType(policy.delivery_unit || defaults.delivery_unit, { allowStory: true });
  policy.strict_gate_unit = normalizeWorkItemType(policy.strict_gate_unit || defaults.strict_gate_unit, { allowStory: true });
  policy.task_gate = String(policy.task_gate || defaults.task_gate);
  return policy;
}

function normalizeListValue(value, fallback = []) {
  if (!Array.isArray(value)) {
    return [...fallback];
  }
  return value.map((item) => String(item || "").trim()).filter(Boolean);
}

function readBreakdowns(context) {
  const root = workBreakdownRoot(context);
  return safeReadDir(root)
    .filter((name) => name.endsWith(".json") && name !== "project-policy.json")
    .map((name) => readProjectJson(context, path.join(root, name)));
}

function latestApprovedRecordApproval(record) {
  return [...(record.approvals || [])]
    .filter((approval) => approval?.status === "approved")
    .sort((a, b) => String(a.created_at || "").localeCompare(String(b.created_at || "")))
    .at(-1);
}

function isApprovedRecordFresh(record) {
  const latest = latestApprovedRecordApproval(record);
  return Boolean(latest?.approved_content_hash && latest.approved_content_hash === hashApprovalSubject(record));
}

function requireFormalApprovalActor(context, options, attribution, action) {
  const source = getOptionString(options, "approval-source");
  if (String(source || "").trim().toLowerCase() === "automation") {
    if (!isAutomationApprovalActor(attribution.actor)) {
      fail(`${action} with --approval-source automation requires --actor-type agent, system, or ci.`);
    }
    return;
  }
  if (!["human", "ci"].includes(attribution.actor.type)) {
    fail(`${action} requires --actor-type human or an approved CI actor.`);
  }
}

function isAutomationApprovalActor(actor) {
  return ["agent", "system", "ci"].includes(actor?.type);
}

function hasFormalApprovalAttribution(actor, source = null) {
  if (source === "automation") {
    return isAutomationApprovalActor(actor);
  }
  return ["human", "ci"].includes(actor?.type);
}

function formalApprovalActorDescription(source = null) {
  return source === "automation" ? "agent/system/CI delegated automation" : "human/CI";
}

function readDependencyGraph(context, options = {}) {
  const graphPath = dependencyGraphPath(context);
  if (!fs.existsSync(graphPath)) {
    if (!options.missingOk) {
      fail("Missing .sdlc/dependencies/graph.json. Run dependency approve first.");
    }
    return {
      schema_version: context.config.schema_version,
      status: "approved",
      edges: [],
      updated_at: null,
      audit: {},
    };
  }
  const graph = readProjectJson(context, graphPath);
  graph.edges = Array.isArray(graph.edges) ? graph.edges : [];
  return graph;
}

function readDependencyProposals(context) {
  return safeReadDir(dependenciesRoot(context))
    .filter((name) => name.endsWith(".json") && name !== "graph.json")
    .map((name) => readProjectJson(context, path.join(dependenciesRoot(context), name)))
    .sort((a, b) => String(a.id).localeCompare(String(b.id)));
}

function upsertDependencyEdge(graph, edge) {
  graph.edges = Array.isArray(graph.edges) ? graph.edges : [];
  const key = dependencyEdgeKey(edge);
  const index = graph.edges.findIndex((candidate) => dependencyEdgeKey(candidate) === key);
  if (index >= 0) {
    graph.edges[index] = edge;
  } else {
    graph.edges.push(edge);
  }
}

function dependencyEdgeKey(edge) {
  return [edge.from, edge.to, edge.type, edge.blocks].join("::");
}

function buildDependencyStatus(context, storyId = null, query = null) {
  const graph = query?.graph || readDependencyGraph(context, { missingOk: true });
  const edges = query?.edges_by_story && storyId
    ? query.edges_by_story.get(storyId) || []
    : (graph.edges || []).filter((edge) => !storyId || edge.from === storyId || edge.to === storyId);
  const blockers = [];
  const warnings = [];
  for (const edge of edges) {
    if (storyId && edge.from !== storyId) {
      warnings.push(`${edge.from} depends on ${edge.to} via ${edge.type}`);
      continue;
    }
    // Status and orchestration expose blockers for upcoming phases. Phase-aware
    // enforcement is applied by the story gate, which passes the current story.
    const state = inspectDependencyEdge(context, edge, null, query);
    if (state.blocking && !state.satisfied) {
      blockers.push(state.message);
    } else if (!state.satisfied) {
      warnings.push(state.message);
    } else if (!isHardDependencyEdge(edge)) {
      warnings.push(state.message);
    }
  }
  const cycles = query?.cycles || findBlockingDependencyCycles(graph.edges || []);
  for (const cycle of cycles) {
    blockers.push(`blocking dependency cycle: ${cycle.join(" -> ")}`);
  }
  return {
    graph_path: dependencyGraphPath(context),
    story_id: storyId,
    edges,
    blockers,
    warnings,
    cycles,
  };
}

function inspectDependencyEdge(context, edge, story = null, query = null) {
  const blocking = isHardDependencyEdge(edge)
    && shouldDependencyBlockStory(context, edge, story);
  const satisfied = isDependencySatisfied(context, edge, query);
  const message = `${edge.from} depends on ${edge.to} (${edge.type}, ${edge.blocks}, requires ${edge.required_state})`;
  if (!satisfied) {
    return { blocking, satisfied, message };
  }
  const stale = dependencyUpstreamArtifactChanged(context, edge, query);
  if (stale && !hasDependencyRevalidationTrace(context, edge.from, edge, stale.since, query)) {
    return {
      blocking,
      satisfied: false,
      message: `${edge.from} requires revalidation because upstream artifact ${stale.artifact_path} changed after linking`,
    };
  }
  return { blocking: false, satisfied: true, message };
}

function isHardDependencyEdge(edge) {
  return edge.blocks !== "none" && ["blocks", "requires_artifact", "requires_contract"].includes(edge.type);
}

function shouldDependencyBlockStory(context, edge, story) {
  if (!story || edge.blocks === "none") {
    return true;
  }
  return storyPhaseRank(context, story) >= phaseRank(edge.blocks);
}

function storyPhaseRank(context, story) {
  const lifecycle = effectiveStoryLifecycleProjection(context, story);
  const value = String(lifecycle.phase || lifecycle.status || "").toLowerCase();
  return phaseRank(value);
}

function phaseRank(value) {
  const order = ["discovery", "analysis", "design", "implementation", "validation", "release"];
  if (["in_progress", "review"].includes(value)) {
    return order.indexOf("implementation");
  }
  if (value === "done") {
    return order.indexOf("release");
  }
  const index = order.indexOf(value);
  return index >= 0 ? index : order.indexOf("design");
}

function isDependencySatisfied(context, edge, query = null) {
  const upstream = query?.stories_by_id?.get(edge.to) || readStory(context, edge.to);
  if (!upstream) {
    return false;
  }
  const lifecycle = query?.lifecycle_by_story?.get(edge.to)
    || effectiveStoryLifecycleProjection(context, upstream);
  const effectiveStatus = lifecycle.status;
  const effectivePhase = lifecycle.phase;
  const state = String(edge.required_state || "").toLowerCase();
  if (lifecycle.blocked && isHardDependencyEdge(edge)) {
    return false;
  }
  if (edge.type === "requires_contract" || state === "contract_approved") {
    let contractState = query?.contract_state_by_story?.get(upstream.id);
    if (!contractState) {
      contractState = inspectStoryContract(context, upstream);
      query?.contract_state_by_story?.set(upstream.id, contractState);
    }
    return contractState.exists && contractState.approved;
  }
  if (edge.type === "requires_artifact" || state === "artifact_linked") {
    return storyHasOutputLink(context, edge.to, query);
  }
  if (["exists", "none"].includes(state)) {
    return true;
  }
  if (lifecycle.blocked) {
    return false;
  }
  if (state === "ready") {
    return ["ready", "implementation", "in_progress", "review", "validation", "release", "done"]
      .includes(String(effectiveStatus));
  }
  if (state === "validated") {
    return ["validation", "release", "done"].includes(String(effectiveStatus))
      || effectivePhase === "validation"
      || effectivePhase === "release";
  }
  if (state === "done") {
    return lifecycle.terminal;
  }
  return effectiveStatus === state || effectivePhase === state;
}

function storyHasOutputLink(context, storyId, query = null) {
  if (query?.registry_index) {
    return (query.registry_index.links_by_story.get(storyId) || []).length > 0;
  }
  const registry = readOutputRegistry(context, { missingOk: true });
  return (registry?.links || []).some((link) => link.story_id === storyId);
}

function dependencyUpstreamArtifactChanged(context, edge, query = null) {
  if (!["requires_artifact", "blocks"].includes(edge.type)) {
    return null;
  }
  const registry = query?.registry || readOutputRegistry(context, { missingOk: true });
  const links = query?.registry_index
    ? query.registry_index.links_by_story.get(edge.to) || []
    : (registry?.links || []).filter((link) => link.story_id === edge.to);
  for (const link of links) {
    if (!link.artifact_path || !link.fingerprints?.artifact_sha256) {
      continue;
    }
    const artifactPath = resolveProjectFilePath(context, link.artifact_path, { mustExist: false });
    const currentHash = fs.existsSync(artifactPath) ? hashFile(artifactPath) : null;
    if (currentHash && currentHash !== link.fingerprints.artifact_sha256) {
      return {
        artifact_path: link.artifact_path,
        since: link.updated_at || link.created_at || null,
      };
    }
  }
  return null;
}

function hasDependencyRevalidationTrace(context, storyId, edge, since, query = null) {
  const sinceTime = since ? Date.parse(since) : 0;
  const events = query?.traces_by_story?.get(storyId) || readTraceEvents(context, storyId);
  return events.some((event) => {
    const eventTime = Date.parse(String(event.created_at || ""));
    return (
      event.action === "dependency.revalidate" &&
      (!Number.isFinite(sinceTime) || !Number.isFinite(eventTime) || eventTime >= sinceTime) &&
      Array.isArray(event.related) &&
      event.related.includes(edge.to)
    );
  });
}

function findBlockingDependencyCycles(edges) {
  const graph = new Map();
  for (const edge of edges.filter(isHardDependencyEdge)) {
    if (!graph.has(edge.from)) {
      graph.set(edge.from, []);
    }
    graph.get(edge.from).push(edge.to);
  }
  const cycles = [];
  const visiting = new Set();
  const visited = new Set();
  const stack = [];
  function visit(node) {
    if (visiting.has(node)) {
      const start = stack.indexOf(node);
      cycles.push([...stack.slice(start), node]);
      return;
    }
    if (visited.has(node)) {
      return;
    }
    visiting.add(node);
    stack.push(node);
    for (const next of graph.get(node) || []) {
      visit(next);
    }
    stack.pop();
    visiting.delete(node);
    visited.add(node);
  }
  for (const node of graph.keys()) {
    visit(node);
  }
  return cycles;
}

function buildDependencyQuery(context, { stories = [], traceEvents = [], session = null } = {}) {
  const graph = readDependencyGraph(context, { missingOk: true });
  const edgesByStory = new Map();
  for (const edge of graph.edges || []) {
    for (const storyId of new Set([edge.from, edge.to])) {
      if (!storyId) continue;
      const edges = edgesByStory.get(storyId) || [];
      edges.push(edge);
      edgesByStory.set(storyId, edges);
    }
  }
  const tracesByStory = new Map();
  for (const event of traceEvents) {
    if (!event.story_id) continue;
    const events = tracesByStory.get(event.story_id) || [];
    events.push(event);
    tracesByStory.set(event.story_id, events);
  }
  const registry = readOutputRegistry(context, { missingOk: true });
  const lifecycleByStory = new Map(
    stories
      .filter((story) => story?.id && story.__folder_id === story.id)
      .map((story) => [story.id, effectiveStoryLifecycleProjection(context, story)]),
  );
  return {
    graph,
    edges_by_story: edgesByStory,
    cycles: findBlockingDependencyCycles(graph.edges || []),
    stories_by_id: new Map(
      stories
        .filter((story) => story?.id && story.__folder_id === story.id)
        .map((story) => [story.id, story]),
    ),
    lifecycle_by_story: lifecycleByStory,
    traces_by_story: tracesByStory,
    registry,
    registry_index: createOutputRegistryQueryIndex(registry),
    contract_state_by_story: new Map(),
    session,
  };
}

function claimStory(context, options) {
  ensureInitialized(context);
  const id = normalizeId(requireOption(options, "id"));
  const agent = requireOption(options, "agent");
  const claimedAt = now();
  const expiresAt = options["expires-at"]
    ? normalizeOptionalDateTime(options["expires-at"], "expires-at")
    : defaultClaimExpiration(context, claimedAt);
  const storyDir = path.join(context.sdlcRoot, "stories", id);
  if (!fs.existsSync(path.join(storyDir, "story.json"))) {
    fail(`Story ${id} does not exist. Create it with 'story create' first.`);
  }

  const claimPath = path.join(storyDir, "claim.json");
  const releaseTaskStartBoundaryLock = acquireFileLock(
    path.join(storyDir, "task-start-boundary.lock"),
  );
  let releaseLifecycleLock = () => {};
  let releaseClaimLock = () => {};
  let claim;
  let traceEvent;
  const attribution = buildAttribution(context, options, "story.claim");
  try {
    releaseLifecycleLock = acquireFileLock(
      storyLifecycleCertificationLockPath(context, id),
    );
    releaseClaimLock = acquireFileLock(path.join(storyDir, "claim.lock"));
    const story = readStory(context, id);
    if (storyAcceptanceCriteria(story).length === 0) {
      fail(
        `Story ${id} has no observable acceptance criteria and cannot be claimed. `
        + `Add one with 'story acceptance add --id ${id} --acceptance <criterion>' first.`,
        {
          en: {
            result: "This work item cannot be assigned yet because it has no observable success criterion.",
            impact: "No assignment was created and work remains paused.",
            required_decision: "State at least one verifiable result that will show when this work is complete.",
            protection_boundary: "Existing files, agreements, delivery choices, and remote systems remain unchanged.",
            next_action: "Add the observable criterion, then retry the assignment.",
            details: {},
          },
          it: {
            result: "Questa attività non può ancora essere assegnata perché non ha un criterio di successo osservabile.",
            impact: "Non è stata creata alcuna assegnazione e il lavoro resta fermo.",
            required_decision: "Indica almeno un risultato verificabile che dimostri quando l’attività è completa.",
            protection_boundary: "File, accordi, scelte di consegna e sistemi remoti restano invariati.",
            next_action: "Aggiungi il criterio osservabile, poi riprova l’assegnazione.",
            details: {},
          },
        },
      );
    }
    if (story.contract_review_required) {
      fail(
        `Story ${id} acceptance criteria changed after its previous contract and it cannot be claimed. `
        + "Create and approve a new exact contract with --replace-story-contract, run task start, then retry story claim.",
        {
          en: {
            result: "This work item cannot be assigned because its success criteria changed after the previous agreement.",
            impact: "No assignment was created and the previous agreement cannot authorize the revised work.",
            required_decision: "Review the revised criteria and approve a new work agreement before starting.",
            protection_boundary: "Existing files, historical agreements, delivery choices, and remote systems remain unchanged.",
            next_action: "Prepare and approve the new agreement, start the revised work, then retry the assignment.",
            details: {},
          },
          it: {
            result: "Questa attività non può essere assegnata perché i criteri di successo sono cambiati dopo l’accordo precedente.",
            impact: "Non è stata creata alcuna assegnazione e l’accordo precedente non può autorizzare il lavoro aggiornato.",
            required_decision: "Rivedi i criteri aggiornati e approva un nuovo accordo di lavoro prima dell’avvio.",
            protection_boundary: "File, accordi storici, scelte di consegna e sistemi remoti restano invariati.",
            next_action: "Prepara e approva il nuovo accordo, avvia il lavoro aggiornato, poi riprova l’assegnazione.",
            details: {},
          },
        },
      );
    }
    const lifecycle = effectiveStoryLifecycleProjection(context, story);
    if (lifecycle.blocked) {
      fail(
        `Story ${id} has an invalid or unreadable final lifecycle receipt and cannot be claimed. `
        + "Inspect the bound workflow and restore valid certification evidence first.",
      );
    }
    if (lifecycle.terminal) {
      fail(`Story ${id} is in terminal status '${lifecycle.status}' and cannot be claimed.`);
    }
    const contractState = inspectStoryContract(context, story);
    const taskStartIssues = contractState.exists && contractState.approved
      ? validateTaskStartReceipt(context, id, contractState.contract)
      : [contractState.message || "the current work agreement is not approved"];
    if (!contractState.exists || !contractState.approved || taskStartIssues.length > 0) {
      fail(
        [
          `Story ${id} cannot be claimed before its current approved contract and immutable task start are valid.`,
          ...taskStartIssues.map((issue) => `- ${issue}`),
          `Run task start --story ${id} --confirm-start for the current approved contract, then retry story claim.`,
        ].join("\n"),
        {
          en: {
            result: "This work item cannot be assigned because its current work agreement has not been validly started.",
            impact: "No assignment was created and no phase work may begin.",
            required_decision: "Confirm the exact current work agreement and start only that agreed work.",
            protection_boundary: "Existing files, agreements, delivery choices, and remote systems remain unchanged.",
            next_action: "Complete the governed task start, then retry the assignment.",
            details: {},
          },
          it: {
            result: "Questa attività non può essere assegnata perché l’accordo di lavoro corrente non è stato avviato validamente.",
            impact: "Non è stata creata alcuna assegnazione e nessuna fase di lavoro può iniziare.",
            required_decision: "Conferma l’accordo di lavoro corrente e avvia soltanto il lavoro concordato.",
            protection_boundary: "File, accordi, scelte di consegna e sistemi remoti restano invariati.",
            next_action: "Completa l’avvio governato, poi riprova l’assegnazione.",
            details: {},
          },
        },
      );
    }
    const claimExists = pathEntryExistsNoFollow(claimPath);
    const priorClaimSnapshot = claimExists
      ? readStableRegularFileBuffer(claimPath, context.root)
      : null;
    if (claimExists && !options.force) {
      const existing = readProjectJson(context, claimPath);
      if (existing.status === "active") {
        fail(`Story ${id} already has an active claim by ${existing.agent}. Release it first or use --force after coordination.`);
      }
    }
    if (claimExists && options.force) {
      const existing = readProjectJson(context, claimPath);
      if (existing.status === "active") {
        requireCoordinationOverrideActor(attribution, `Force-claiming active story ${id}`);
      }
    }
    const checkpoint = consumeStoryActionCheckpoint(
      context,
      id,
      "story.claim",
      options,
    );
    claim = {
      story_id: id,
      agent: String(agent),
      branch: String(options.branch || defaultStoryBranch(context, id)),
      status: "active",
      claimed_at: claimedAt,
      expires_at: expiresAt,
      notes: options.notes ? String(options.notes) : null,
      ...(checkpoint || {}),
      audit: {
        claimed_by: attribution.actor,
        git: attribution.git,
        run: attribution.run,
      },
    };
    let traceMutation;
    let claimWritten = false;
    try {
      assertRecordSchema(claim, "claim.schema.json", `Claim for story ${id}`);
      writeJsonFile(claimPath, claim, { force: Boolean(options.force || claimExists) });
      claimWritten = true;
      traceMutation = prepareGovernedTraceMutation(context, id, {
        type: "claim",
        summary: `Story ${id} claimed by ${agent}`,
        action: "story.claim",
        actor: attribution.actor,
        evidence: [
          toProjectPath(context, claimPath),
          claim.authorization_use_ref,
          claim.checkpoint_profile_ref?.path,
        ].filter(Boolean),
        related: [id],
        git: attribution.git,
        run: attribution.run,
      });
      try {
        traceEvent = traceMutation.commit();
      } catch (error) {
        traceEvent = traceMutation.recoverCommitted();
        if (!traceEvent) throw error;
      }
    } catch (error) {
      if (claimWritten && !traceEvent) {
        try {
          if (priorClaimSnapshot) {
            writeTextFile(
              claimPath,
              priorClaimSnapshot.content.toString("utf8"),
              { force: true },
            );
          } else if (pathEntryExistsNoFollow(claimPath)) {
            removePathGoverned(claimPath, { force: true });
          }
        } catch (rollbackError) {
          fail(
            `Story ${id} claim transaction could not restore its exact prior state `
            + `(${rollbackError.message}). Original failure: ${error.message}`,
          );
        }
      }
      throw error;
    } finally {
      traceMutation?.release();
    }
  } finally {
    releaseClaimLock();
    releaseLifecycleLock();
    releaseTaskStartBoundaryLock();
  }
  output(
    options,
    { status: "claimed", claim_path: claimPath, claim, trace_event: traceEvent },
    [`Claimed story ${id} for ${agent}`],
  );
}

function releaseStoryClaim(context, options) {
  const result = releaseStoryClaimRecord(context, options);
  output(options, result, [`Released claim for story ${result.claim.story_id}`]);
}

function releaseStoryClaimRecord(context, options, lockOptions = {}) {
  ensureInitialized(context);
  const id = normalizeId(requireOption(options, "id"));
  const storyDir = path.join(context.sdlcRoot, "stories", id);
  const claimPath = path.join(storyDir, "claim.json");
  const attribution = buildAttribution(context, options, "story.release");
  const requestedAgent = options.agent ? String(options.agent) : null;
  let claim;
  let traceEvent;
  let releaseTaskStartBoundaryLock = () => {};
  let releaseLifecycleLock = () => {};
  let releaseClaimLock = () => {};
  try {
    if (!lockOptions.boundaryAndLifecycleLocked) {
      releaseTaskStartBoundaryLock = acquireFileLock(
        path.join(storyDir, "task-start-boundary.lock"),
      );
      releaseLifecycleLock = acquireFileLock(
        storyLifecycleCertificationLockPath(context, id),
      );
    }
    releaseClaimLock = acquireFileLock(path.join(storyDir, "claim.lock"));
    if (!pathEntryExistsNoFollow(claimPath)) {
      fail(`Story ${id} has no claim to release`);
    }
    const priorClaimSnapshot = readStableRegularFileBuffer(claimPath, context.root);
    claim = JSON.parse(priorClaimSnapshot.content.toString("utf8"));
    if (requestedAgent && claim.agent !== requestedAgent && !options.force) {
      fail(`Story ${id} is claimed by ${claim.agent}, not ${requestedAgent}. Use --force only after coordination.`);
    }
    if (requestedAgent && claim.agent !== requestedAgent && options.force) {
      requireCoordinationOverrideActor(attribution, `Force-releasing story ${id} claimed by another agent`);
    }
    claim.status = normalizeClaimStatus(options.status || "released");
    claim.released_at = now();
    claim.release_reason = options.reason ? String(options.reason) : null;
    claim.audit = {
      ...(claim.audit || {}),
      released_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    };
    let traceMutation;
    let claimWritten = false;
    try {
      writeJsonFile(claimPath, claim, { force: true });
      claimWritten = true;
      traceMutation = prepareGovernedTraceMutation(context, id, {
        type: "sync",
        summary: `Story ${id} claim ${claim.status}`,
        action: "story.release",
        actor: attribution.actor,
        evidence: [toProjectPath(context, claimPath)],
        related: [id],
        git: attribution.git,
        run: attribution.run,
      });
      try {
        traceEvent = traceMutation.commit();
      } catch (error) {
        traceEvent = traceMutation.recoverCommitted();
        if (!traceEvent) throw error;
      }
    } catch (error) {
      if (claimWritten && !traceEvent) {
        try {
          writeTextFile(
            claimPath,
            priorClaimSnapshot.content.toString("utf8"),
            { force: true },
          );
        } catch (rollbackError) {
          fail(
            `Story ${id} claim release transaction could not restore its exact prior state `
            + `(${rollbackError.message}). Original failure: ${error.message}`,
          );
        }
      }
      throw error;
    } finally {
      traceMutation?.release();
    }
  } finally {
    releaseClaimLock();
    releaseLifecycleLock();
    releaseTaskStartBoundaryLock();
  }
  return { status: "released", claim_path: claimPath, claim, trace_event: traceEvent };
}

function createStoryHandoff(context, options) {
  const result = createStoryHandoffRecord(context, options);
  output(options, result, [`Created handoff ${result.handoff.id}`]);
}

function createStoryHandoffRecord(context, options) {
  ensureInitialized(context);
  const storyId = normalizeId(requireOption(options, "id"));
  const storyPath = path.join(context.sdlcRoot, "stories", storyId, "story.json");
  if (!fs.existsSync(storyPath)) {
    fail(`Story ${storyId} does not exist`);
  }
  const toAgent = requireOption(options, "to-agent");
  const attribution = buildAttribution(context, options, "story.handoff");
  const handoffId = normalizeId(String(options["handoff-id"] || `HND-${storyId}-${uniqueRecordSuffix()}`));
  const handoffPath = path.join(context.sdlcRoot, "handoffs", `${handoffId}.json`);
  const handoff = {
    id: handoffId,
    story_id: storyId,
    from_actor: attribution.actor,
    to_agent: String(toAgent),
    status: normalizeHandoffStatus(options.status || "open"),
    summary: options.summary ? String(options.summary) : null,
    required_artifacts: normalizeListOption(options.artifact).map(normalizeProjectPathInput),
    open_items: normalizeListOption(options["open-item"]),
    created_at: now(),
    audit: {
      created_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
  };
  assertRecordSchema(handoff, "handoff.schema.json", `Handoff ${handoffId}`);
  writeJsonFile(handoffPath, handoff, { force: Boolean(options.force) });
  appendTraceEvent(context, storyId, {
    type: "handoff",
    summary: handoff.summary || `Story ${storyId} handed off to ${toAgent}`,
    action: "story.handoff",
    actor: attribution.actor,
    evidence: [toProjectPath(context, handoffPath)],
    related: [storyId, handoffId],
    git: attribution.git,
    run: attribution.run,
  });
  return { status: "created", handoff_path: handoffPath, handoff };
}

function completeStoryStep(context, options) {
  ensureInitialized(context);
  const storyId = normalizeId(requireOption(options, "id"));
  if (!readStory(context, storyId)) {
    fail(`Story ${storyId} does not exist`);
  }
  const releaseTaskStartBoundaryLock = acquireFileLock(
    path.join(context.sdlcRoot, "stories", storyId, "task-start-boundary.lock"),
  );
  let releaseLifecycleLock = () => {};
  try {
    releaseLifecycleLock = acquireFileLock(
      storyLifecycleCertificationLockPath(context, storyId),
    );
    const story = readStory(context, storyId);
    if (!story) {
      fail(`Story ${storyId} does not exist`);
    }
    const lifecycle = effectiveStoryLifecycleProjection(context, story);
    if (lifecycle.terminal) {
      fail(
        `Story ${storyId} lifecycle is already certified `
        + `(${lifecycle.source}); its completed steps cannot be changed.`,
      );
    }
    assertReleaseClaimPrecondition(context, storyId, options);
    const step = normalizeStoryStep(context, requireOption(options, "step"));
    const stepPhase = storyStepPhase(context, step);
    const summary = getOptionString(options, "summary") || null;
    const outputTypes = normalizeListOption(options.type).map(normalizeArtifactType);
    const contract = validateApprovedStoryContractForPhaseOutput(
      context,
      story,
      "story.complete-step",
      outputTypes.map((artifactType) => ({
        artifact_type: artifactType,
        phase: stepPhase,
      })),
      options,
    );
    const phaseOutputRefs = (contract?.output_contract_refs || [])
      .filter((ref) => ref.phase === stepPhase);
    for (const ref of phaseOutputRefs) {
      if (!outputTypes.includes(ref.artifact_type)) {
        fail(
          `Story ${storyId} ${stepPhase} step requires --type ${ref.artifact_type} `
          + `because approved contract ${contract.id} assigns that output to this phase.`,
        );
      }
    }
    const artifactEvidence = buildCanonicalEvidence(context, normalizeListOption(options.artifact), "Story step artifact");
    const extraEvidence = buildCanonicalEvidence(context, normalizeListOption(options.evidence), "Story step evidence");
    if (!summary && outputTypes.length === 0 && artifactEvidence.length === 0 && extraEvidence.length === 0) {
      fail("Complete-step requires --summary, --type, --artifact, or --evidence.");
    }

    const registry = readOutputRegistry(context, { missingOk: true });
    const outputLinks = collectStoryOutputLinksForStep(
      context,
      registry,
      storyId,
      outputTypes,
    ).filter((link) =>
      !contract
      || (contract.output_contract_refs || []).some((ref) =>
        ref.artifact_type === link.artifact_type
        && ref.template_id === link.template_id
        && ref.mode === link.mode
        && (!ref.phase || ref.phase === stepPhase)));
    if (outputTypes.length > 0) {
      const linkedTypes = new Set(outputLinks.map((link) => link.artifact_type));
      for (const artifactType of outputTypes) {
        if (!linkedTypes.has(artifactType)) {
          fail(
            `Story ${storyId} has no linked ${artifactType} output. Run output resolve/link before completing this step.`,
          );
        }
      }
    }
    for (const ref of phaseOutputRefs) {
      const exactLinks = outputLinks.filter((link) =>
        link.artifact_type === ref.artifact_type
        && link.template_id === ref.template_id
        && link.mode === ref.mode);
      if (exactLinks.length !== 1) {
        fail(
          `Story ${storyId} ${stepPhase} step requires one exact linked output `
          + `${ref.artifact_type}:${ref.template_id}:${ref.mode}; found ${exactLinks.length}.`,
        );
      }
    }
    if (["validation", "release"].includes(step)) {
      if (artifactEvidence.length === 0 && extraEvidence.length === 0 && outputLinks.length === 0) {
        fail(`${step} completion requires --artifact, --evidence, or a linked output; a summary alone is not release evidence.`);
      }
      const requiredTraceType = step === "validation" ? "test" : "release";
      const acceptableOutcomes = step === "validation" ? ["passed"] : ["ready", "passed"];
      const supportingTrace = latestTraceEvent(readTraceEvents(context, storyId), requiredTraceType);
      if (!supportingTrace || !acceptableOutcomes.includes(supportingTrace.outcome)) {
        fail(
          `${step} completion requires the latest ${requiredTraceType} trace to have outcome `
          + `${acceptableOutcomes.join(" or ")}.`,
        );
      }
    }

    const checkpoint = consumeStoryActionCheckpoint(
      context,
      storyId,
      "story.complete-step",
      options,
      { artifact_types: outputTypes, step },
    );
    const attribution = buildAttribution(context, options, "story.complete-step");
    const stepDir = path.join(context.sdlcRoot, "stories", storyId, "steps");
    const stepPath = path.join(stepDir, `${step}.json`);
    const historyPath = path.join(stepDir, "history.jsonl");
    const stepDirectoryExisted = pathEntryExistsNoFollow(stepDir);
    const relativeStepPath = toProjectPath(context, stepPath);
    const record = {
      id: normalizeId(String(options["completion-id"] || `STEP-${storyId}-${step}-${uniqueRecordSuffix()}`)),
      story_id: storyId,
      step,
      status: "completed",
      phase: stepPhase,
      summary,
      output_types: outputTypes,
      output_links: outputLinks.map((link) => ({
        id: link.id,
        artifact_type: link.artifact_type,
        artifact_path: link.artifact_path,
        template_id: link.template_id,
        mode: link.mode,
        base_artifact: link.base_artifact || null,
        requirements: Array.isArray(link.requirements) ? link.requirements : [],
      })),
      artifacts: artifactEvidence,
      evidence: extraEvidence,
      next_step: options["next-step"]
        ? normalizeStoryStep(context, options["next-step"])
        : defaultNextStoryStep(context, step),
      completed_at: now(),
      ...(checkpoint || {}),
      audit: {
        completed_by: attribution.actor,
        git: attribution.git,
        run: attribution.run,
      },
    };
    const priorStepSnapshot = pathEntryExistsNoFollow(stepPath)
      ? readStableRegularFileBuffer(stepPath, context.root)
      : null;
    const priorHistorySnapshot = pathEntryExistsNoFollow(historyPath)
      ? readStableRegularFileBuffer(historyPath, context.root)
      : null;
    let stepWritten = false;
    let historyWritten = false;
    let traceMutation;
    let traceEvent;
    try {
      writeJsonFile(stepPath, record, { force: true });
      stepWritten = true;
      const stepSnapshot = readStableRegularFileBuffer(stepPath, context.root);
      const storyStepRef = {
        schema_version: "story-step-completion-ref:v1",
        story_id: storyId,
        step,
        phase: stepPhase,
        path: relativeStepPath,
        record_id: record.id,
        completed_at: record.completed_at,
        sha256: stepSnapshot.sha256,
        hash_algorithm: "sha256:file:v1",
      };
      appendJsonLine(historyPath, record);
      historyWritten = true;
      traceMutation = prepareGovernedTraceMutation(context, storyId, {
        type: "gate",
        summary: summary || `Completed ${step} for ${storyId}`,
        action: "story.complete-step",
        actor: attribution.actor,
        evidence: Array.from(new Set([
          relativeStepPath,
          ...record.artifacts.map((item) => item.path),
          ...record.evidence.map((item) => item.path),
          ...record.output_links.map((item) => item.artifact_path).filter(Boolean),
          record.authorization_use_ref,
          record.checkpoint_profile_ref?.path,
        ].filter(Boolean))),
        related: [storyId, step, ...record.output_links.map((item) => item.id)],
        story_step_ref: storyStepRef,
        git: attribution.git,
        run: attribution.run,
      });
      try {
        traceEvent = traceMutation.commit();
      } catch (error) {
        traceEvent = traceMutation.recoverCommitted();
        if (!traceEvent) throw error;
      }
    } catch (error) {
      if (!traceEvent) {
        const rollbackFailures = [];
        const restore = (label, filePath, snapshot, written) => {
          if (!written) return;
          try {
            if (snapshot) {
              writeTextFile(filePath, snapshot.content.toString("utf8"), { force: true });
            } else if (pathEntryExistsNoFollow(filePath)) {
              removePathGoverned(filePath, { force: true });
            }
          } catch (rollbackError) {
            rollbackFailures.push(`${label}: ${rollbackError.message}`);
          }
        };
        restore("story step history", historyPath, priorHistorySnapshot, historyWritten);
        restore("story step record", stepPath, priorStepSnapshot, stepWritten);
        if (
          !stepDirectoryExisted
          && pathEntryExistsNoFollow(stepDir)
          && fs.readdirSync(stepDir).length === 0
        ) {
          try {
            removeEmptyDirectoryGoverned(stepDir);
          } catch (rollbackError) {
            rollbackFailures.push(`story step directory: ${rollbackError.message}`);
          }
        }
        if (rollbackFailures.length > 0) {
          fail(
            `Story ${storyId} step transaction could not restore exact prior state `
            + `(${rollbackFailures.join("; ")}). Original failure: ${error.message}`,
          );
        }
      }
      throw error;
    } finally {
      traceMutation?.release();
    }

    const release = options["release-claim"]
      ? releaseStoryClaimRecord(context, {
          ...options,
          id: storyId,
          status: "released",
          reason: getOptionString(options, "reason") || `Completed ${step}; story prepared for handoff`,
        }, { boundaryAndLifecycleLocked: true })
      : null;

    output(
      options,
      { status: "completed", step_path: stepPath, step: record, trace_event: traceEvent, release },
      [
        `Completed ${step} for story ${storyId}`,
        `Step record: ${relativeStepPath}`,
        release ? `Released claim for story ${storyId}` : null,
      ].filter(Boolean),
    );
  } finally {
    releaseLifecycleLock();
    releaseTaskStartBoundaryLock();
  }
}

function prepareStoryHandoff(context, options) {
  ensureInitialized(context);
  const storyId = normalizeId(requireOption(options, "id"));
  if (!readStory(context, storyId)) {
    fail(`Story ${storyId} does not exist`);
  }
  assertReleaseClaimPrecondition(context, storyId, options);
  requireOption(options, "to-agent");
  const handoffId = normalizeId(String(options["handoff-id"] || `HND-${storyId}-${uniqueRecordSuffix()}`));
  const packagePath = path.join(context.sdlcRoot, "stories", storyId, "handoffs", `${handoffId}-package.json`);
  const handoffPackage = buildStoryHandoffPackage(context, storyId, handoffId, options);
  writeJsonFile(packagePath, handoffPackage, { force: Boolean(options.force) });

  const existingArtifacts = normalizeListOption(options.artifact);
  const handoffOptions = {
    ...options,
    id: storyId,
    "handoff-id": handoffId,
    artifact: [...existingArtifacts, toProjectPath(context, packagePath)],
  };
  const handoff = createStoryHandoffRecord(context, handoffOptions);
  const release = options["release-claim"]
    ? releaseStoryClaimRecord(context, {
        ...options,
        id: storyId,
        status: "released",
        reason: getOptionString(options, "reason") || `Prepared handoff ${handoffId}`,
      })
    : null;

  output(
    options,
    {
      status: "prepared",
      handoff_id: handoffId,
      package_path: packagePath,
      package: handoffPackage,
      handoff: handoff.handoff,
      release,
    },
    [
      `Prepared handoff ${handoffId} for story ${storyId}`,
      `Handoff package: ${toProjectPath(context, packagePath)}`,
      release ? `Released claim for story ${storyId}` : null,
    ].filter(Boolean),
  );
}

function closeHandoff(context, options) {
  ensureInitialized(context);
  const handoffId = normalizeId(requireOption(options, "id"));
  const handoffPath = path.join(context.sdlcRoot, "handoffs", `${handoffId}.json`);
  if (!fs.existsSync(handoffPath)) {
    fail(`Handoff ${handoffId} does not exist`);
  }
  const handoff = readProjectJson(context, handoffPath);
  const status = normalizeHandoffCloseStatus(options.status || "closed");
  const attribution = buildAttribution(context, options, "handoff.close");
  handoff.status = status;
  handoff.closed_at = now();
  handoff.close_summary = getOptionString(options, "summary") || null;
  handoff.open_items = normalizeListOption(options["open-item"]);
  handoff.audit = {
    ...(handoff.audit || {}),
    closed_by: attribution.actor,
    git: attribution.git,
    run: attribution.run,
  };
  assertRecordSchema(handoff, "handoff.schema.json", `Handoff ${handoffId}`);
  writeJsonFile(handoffPath, handoff, { force: true });
  appendTraceEvent(context, handoff.story_id || null, {
    type: "handoff",
    summary: handoff.close_summary || `Handoff ${handoffId} ${status}`,
    action: "handoff.close",
    actor: attribution.actor,
    evidence: [toProjectPath(context, handoffPath)],
    related: [handoff.story_id, handoffId].filter(Boolean),
    git: attribution.git,
    run: attribution.run,
  });
  output(options, { status, handoff_path: handoffPath, handoff }, [`Handoff ${handoffId} ${status}`]);
}

function lockPhase(context, options) {
  ensureInitialized(context);
  const phase = String(requireOption(options, "phase"));
  if (!context.config.phases[phase]) {
    fail(`Unknown phase '${phase}'. Valid phases: ${Object.keys(context.config.phases).join(", ")}`);
  }
  const scope = String(options.scope || phase);
  const expiresAt = options["expires-at"] ? normalizeOptionalDateTime(options["expires-at"], "expires-at") : null;
  const lockMutexPath = path.join(context.sdlcRoot, "locks", `.phase-${shortHash(`${phase}:${scope}`)}.lock`);
  const releaseLock = acquireFileLock(lockMutexPath);
  let lock;
  let lockPath;
  let lockId;
  const attribution = buildAttribution(context, options, "phase.lock");
  try {
    const conflictingLock = readActiveLocks(context).find(
      (candidate) => candidate.phase === phase && String(candidate.scope || candidate.phase) === scope,
    );
    if (conflictingLock && !options.force) {
      fail(
        `Phase ${phase} scope ${scope} already has active lock ${conflictingLock.id}. Release it first or use --force after coordination.`,
      );
    }
    if (conflictingLock && options.force) {
      requireCoordinationOverrideActor(attribution, `Overriding phase lock ${conflictingLock.id}`);
      const conflictingPath = path.join(context.sdlcRoot, "locks", `${normalizeId(conflictingLock.id)}.json`);
      conflictingLock.status = "cancelled";
      conflictingLock.released_at = now();
      conflictingLock.release_reason = `Replaced by coordinated override from ${attribution.actor.id}`;
      conflictingLock.audit = {
        ...(conflictingLock.audit || {}),
        released_by: attribution.actor,
        git: attribution.git,
        run: attribution.run,
      };
      writeJsonFile(conflictingPath, conflictingLock, { force: true });
    }
    lockId = normalizeId(String(options.id || `LOCK-${phase}-${uniqueRecordSuffix()}`));
    lockPath = path.join(context.sdlcRoot, "locks", `${lockId}.json`);
    lock = {
      id: lockId,
      phase,
      scope,
      status: "active",
      reason: options.reason ? String(options.reason) : null,
      expires_at: expiresAt,
      created_at: now(),
      audit: {
        locked_by: attribution.actor,
        git: attribution.git,
        run: attribution.run,
      },
    };
    assertRecordSchema(lock, "phase-lock.schema.json", `Phase lock ${lockId}`);
    writeJsonFile(lockPath, lock, { force: Boolean(options.force) });
  } finally {
    releaseLock();
  }
  appendTraceEvent(context, null, {
    type: "lock",
    summary: `Phase ${phase} locked: ${lock.reason || lock.scope}`,
    action: "phase.lock",
    actor: attribution.actor,
    evidence: [toProjectPath(context, lockPath)],
    related: [phase, lockId],
    git: attribution.git,
    run: attribution.run,
  });
  output(options, { status: "locked", lock_path: lockPath, lock }, [`Locked phase ${phase} with ${lockId}`]);
}

function releasePhaseLock(context, options) {
  ensureInitialized(context);
  const id = normalizeId(requireOption(options, "id"));
  const lockPath = path.join(context.sdlcRoot, "locks", `${id}.json`);
  if (!fs.existsSync(lockPath)) {
    fail(`Phase lock ${id} does not exist`);
  }
  const lock = readProjectJson(context, lockPath);
  const attribution = buildAttribution(context, options, "phase.release");
  lock.status = normalizeLockStatus(options.status || "released");
  lock.released_at = now();
  lock.release_reason = options.reason ? String(options.reason) : null;
  lock.audit = {
    ...(lock.audit || {}),
    released_by: attribution.actor,
    git: attribution.git,
    run: attribution.run,
  };
  writeJsonFile(lockPath, lock, { force: true });
  appendTraceEvent(context, null, {
    type: "lock",
    summary: `Phase lock ${id} ${lock.status}`,
    action: "phase.release",
    actor: attribution.actor,
    evidence: [toProjectPath(context, lockPath)],
    related: [lock.phase, id],
    git: attribution.git,
    run: attribution.run,
  });
  output(options, { status: lock.status, lock_path: lockPath, lock }, [`Released phase lock ${id}`]);
}

function appendTrace(context, options) {
  ensureInitialized(context);
  const type = String(requireOption(options, "type"));
  if (!TRACE_TYPES.has(type)) {
    fail(`Unknown trace type '${type}'. Valid types: ${Array.from(TRACE_TYPES).join(", ")}`);
  }
  const summary = requireOption(options, "summary");
  const storyId = options.story ? normalizeId(String(options.story)) : null;
  if (storyId && !readStory(context, storyId)) {
    fail(`Story ${storyId} does not exist`);
  }
  const releaseLifecycleLock = storyId && ["test", "release"].includes(type)
    ? acquireFileLock(storyLifecycleCertificationLockPath(context, storyId))
    : () => {};
  try {
    appendTraceLocked(context, options, type, summary, storyId);
  } finally {
    releaseLifecycleLock();
  }
}

function appendTraceLocked(context, options, type, summary, storyId) {
  if (storyId && ["test", "release"].includes(type)) {
    const finalReceiptExists = fs.existsSync(
      workflowFinalGateReceiptPath(context, storyId),
    );
    const lifecycle = effectiveStoryLifecycleProjection(
      context,
      readStory(context, storyId),
    );
    const repairOutcome = type === "test"
      ? options.outcome === "passed"
      : ["passed", "ready"].includes(options.outcome);
    if (
      (
        lifecycle.terminal
        && lifecycle.source === "workflow_final_receipt"
      )
      || (finalReceiptExists && !repairOutcome)
    ) {
      fail(
        `Story ${storyId} already has a terminal lifecycle receipt. `
        + "An invalidated receipt permits only passing in-place repair evidence before recertification; "
        + "create a new governed story for later failed attempts or different lifecycle evidence.",
      );
    }
  }
  const traceFile = storyId ? `${storyId}.jsonl` : "project.jsonl";
  const tracePath = path.join(context.sdlcRoot, "traces", traceFile);
  const attribution = buildAttribution(context, options, `trace.${type}`);
  const gitEvent = options["git-event"] ? normalizeGitEvent(options["git-event"]) : null;
  let narrative;
  try {
    narrative = buildTraceNarrative(options);
  } catch (error) {
    fail(error.message);
  }
  const event = {
    id: `TR-${compactTimestamp()}-${crypto.randomBytes(3).toString("hex")}`,
    story_id: storyId,
    type,
    summary,
    outcome: options.outcome ? normalizeTraceOutcome(options.outcome) : null,
    actor: attribution.actor,
    ...buildTraceAuthorityMetadata(context, options, attribution),
    action: normalizeScalarOption(options.action, "action") || type,
    evidence: normalizeListOption(options.evidence).map(normalizeProjectPathInput),
    related: normalizeListOption(options.related),
    ...(narrative ? { narrative } : {}),
    git: {
      ...attribution.git,
      event: gitEvent,
    },
    run: attribution.run,
    correlation_id: CLI_OPERATION_CONTEXT.correlation_id,
    created_at: now(),
  };
  assertManualTraceActionIsSafe(event);
  const snapshottedEvent = snapshotManualTraceEvidence(context, event);
  const sealedEvent = sealGovernedTraceEvent(context, tracePath, snapshottedEvent);
  output(options, { status: "appended", trace_path: tracePath, event: sealedEvent }, [`Appended ${type} trace ${sealedEvent.id}`]);
}

function assertManualTraceActionIsSafe(event) {
  const generatedBy = {
    "data.migrate": "autonomy delivery action",
    "data.rollback": "autonomy delivery action",
    "git.commit": "autonomy delivery action",
    "git.push": "autonomy delivery action",
    "pull_request.merge": "autonomy delivery action",
    "release.local": "autonomy delivery action",
    "sync.commit": "sync record",
    "sync.merge": "sync record",
    "sync.push": "sync record",
    "workflow.instance.start": "workflow instance start",
    "workflow.instance.transition": "workflow instance transition",
  };
  const command = generatedBy[event.action];
  if (!command) return;
  fail(
    `Protected action '${event.action}' cannot be appended manually because one incomplete event would permanently block strict gates. `
    + `Run '${command}' for the exact action instead; it records the verified receipt and trace automatically.`,
  );
}

function snapshotManualTraceEvidence(context, event) {
  if (!["test", "release"].includes(event.type) || !Array.isArray(event.evidence) || event.evidence.length === 0) {
    return event;
  }
  const redactionPolicy = buildTraceRedactionPolicy(context);
  const mappings = [];
  const evidence = event.evidence.map((projectPath, index) => {
    const sourcePath = resolveProjectFilePath(context, projectPath, { mustExist: true, fileOnly: true });
    assertNotDerivedArtifact(context, sourcePath, "Trace evidence");
    const safeName = path.basename(sourcePath)
      .replace(/[^A-Za-z0-9._-]+/gu, "-")
      .replace(/^-+|-+$/gu, "") || "evidence.txt";
    const snapshotRelativePath = [
      SDLC_DIR,
      "traces",
      "evidence",
      normalizeId(event.id),
      `${String(index + 1).padStart(2, "0")}-${safeName}`,
    ].join("/");
    const snapshotPath = resolveProjectFilePath(context, snapshotRelativePath, { mustExist: false });
    const representation = redactedEvidenceRepresentation(context, sourcePath, redactionPolicy);
    writeTextFile(snapshotPath, representation, { atomicCreate: true, durable: true });
    mappings.push({
      source_path: projectPath,
      snapshot_path: snapshotRelativePath,
    });
    return snapshotRelativePath;
  });
  return {
    ...event,
    evidence,
    evidence_sources: mappings,
  };
}

function bindHistoricalTraceEvidencePolicy(context, options) {
  ensureInitialized(context);
  const storyId = options.story ? normalizeId(String(options.story)) : null;
  if (storyId && !readStory(context, storyId)) {
    fail(`Story ${storyId} does not exist`);
  }
  const targetIds = [...new Set(normalizeListOption(options["target-event"]).map(String))];
  if (targetIds.length === 0) fail("Provide at least one --target-event to bind.");
  const policyName = String(requireOption(options, "redaction-policy"));
  if (!["legacy_evidence_v1", "operational_evidence_v1", "operational_v2"].includes(policyName)) {
    fail("--redaction-policy must be legacy_evidence_v1, operational_evidence_v1, or operational_v2.");
  }
  const policy = policyName === "legacy_evidence_v1"
    ? buildLegacyEvidenceV1RedactionPolicy(context)
    : policyName === "operational_evidence_v1"
      ? buildHistoricalOperationalEvidenceV1RedactionPolicy(context)
      : buildTraceRedactionPolicy(context);
  let policySourceRef;
  const traceFile = storyId ? `${storyId}.jsonl` : "project.jsonl";
  const tracePath = path.join(context.sdlcRoot, "traces", traceFile);
  const bindUnderLock = () => {
    let records;
    try {
      records = withTraceIntegritySnapshot(
        traceIntegrityOptions(context, tracePath),
        ({ integrity, records: snapshotRecords, present }) => {
          if (!present || !integrity.valid || !integrity.initialized) {
            fail("Historical evidence policy binding requires a valid sealed trace.");
          }
          return snapshotRecords;
        },
      );
    } catch (error) {
      if (error instanceof UserError) throw error;
      failTraceIntegrityWrite(error);
    }
    if (
      process.env.NODE_ENV === "test"
      && /^\d{1,4}$/u.test(process.env.AGENTIC_SDLC_TEST_TRACE_BIND_DELAY_MS || "")
    ) {
      sleepSync(Math.min(Number(process.env.AGENTIC_SDLC_TEST_TRACE_BIND_DELAY_MS), 1_000));
    }
    const events = records.filter((record) => record.valid).map((record) => record.event);
    const byId = new Map();
    for (const event of events) {
      if (byId.has(event.id)) fail(`Trace contains duplicate event id ${event.id}.`);
      byId.set(event.id, event);
    }
    const alreadyBound = new Set();
    for (const event of events) {
      for (const binding of Array.isArray(event.evidence_policy_bindings) ? event.evidence_policy_bindings : []) {
        const key = traceEvidencePolicyBindingKey(binding?.target);
        if (key) alreadyBound.add(key);
      }
    }
    const bindings = [];
    for (const targetId of targetIds) {
      const target = byId.get(targetId);
      if (!target || target?._trace_integrity?.schema_version !== "trace-integrity-event:v1") {
        fail(`Target trace event ${targetId} is missing or unsealed.`);
      }
      const refs = Array.isArray(target.evidence_refs)
        ? target.evidence_refs.filter((ref) => ref?.representation === "redacted_utf8_v1")
        : [];
      if (refs.length === 0) fail(`Target trace event ${targetId} has no historical v1 evidence refs.`);
      for (const ref of refs) {
        const bindingTarget = {
          event_id: target.id,
          event_hash: target._trace_integrity.event_hash,
          evidence_path: ref.path,
          evidence_sha256: ref.sha256,
          evidence_ref_sha256: traceEvidenceRefHash(ref),
        };
        const key = traceEvidencePolicyBindingKey(bindingTarget);
        if (alreadyBound.has(key)) fail(`Historical evidence ref ${target.id}:${ref.path} is already bound.`);
        const filePath = resolveProjectFilePath(context, ref.path, { mustExist: true, fileOnly: true });
        const representation = redactedEvidenceRepresentation(context, filePath, policy);
        if (!evidenceRepresentationMatchesRef(representation, ref)) {
          fail(`Selected redaction policy does not reproduce ${target.id}:${ref.path}.`);
        }
        policySourceRef ||= traceEvidencePolicySourceRef(context, policy);
        alreadyBound.add(key);
        bindings.push({
          schema_version: TRACE_EVIDENCE_POLICY_BINDING_SCHEMA,
          target: bindingTarget,
          policy_source_ref: policySourceRef,
        });
      }
    }
    const attribution = buildAttribution(context, options, "trace.evidence-policy.bind");
    const event = sealPreparedTraceEventLocked(
      context,
      tracePath,
      prepareGovernedTraceEvent(context, {
        id: `TR-${compactTimestamp()}-${crypto.randomBytes(3).toString("hex")}`,
        story_id: storyId,
        type: "decision",
        summary: getOptionString(options, "summary")
          || `Bound ${bindings.length} historical evidence reference${bindings.length === 1 ? "" : "s"} to ${policyName}`,
        outcome: "passed",
        actor: attribution.actor,
        ...buildTraceAuthorityMetadata(context, options, attribution),
        action: "trace.evidence-policy.bind",
        evidence: [policySourceRef.path],
        evidence_policy_bindings: bindings,
        related: targetIds,
        git: attribution.git,
        run: attribution.run,
        correlation_id: CLI_OPERATION_CONTEXT.correlation_id,
        created_at: now(),
      }),
    );
    return { bindings, event };
  };
  const releaseTraceLock = acquireFileLock(`${tracePath}.lock`);
  let result;
  try {
    assertNoPendingWorkflowTraceTransaction(context, tracePath);
    result = bindUnderLock();
  } finally {
    releaseTraceLock();
  }
  const { bindings, event } = result;
  output(options, {
    status: "bound",
    trace_path: tracePath,
    policy_source_ref: policySourceRef,
    binding_count: bindings.length,
    event,
  }, [`Bound ${bindings.length} historical evidence references to ${policyName}`]);
}

function traceEvidenceRefHash(ref) {
  return hashBuffer(Buffer.from(stableJson(ref), "utf8"));
}

function traceEvidencePolicyBindingKey(target) {
  if (!target || typeof target !== "object") return null;
  const values = [
    target.event_id,
    target.event_hash,
    target.evidence_path,
    target.evidence_sha256,
    target.evidence_ref_sha256,
  ];
  return values.every((value) => typeof value === "string" && value.length > 0)
    ? values.join("\u0000")
    : null;
}

function recordSyncEvent(context, options) {
  ensureInitialized(context);
  const event = normalizeGitEvent(requireOption(options, "event"));
  const storyId = options.story ? normalizeId(String(options.story)) : null;
  if (storyId && !readStory(context, storyId)) {
    fail(`Story ${storyId} does not exist`);
  }
  const attribution = buildAttribution(context, options, `sync.${event}`);
  const summary = options.summary ? String(options.summary) : `Recorded git ${event}`;
  const traceEvent = appendTraceEvent(context, storyId, {
    type: "sync",
    summary,
    action: `sync.${event}`,
    actor: attribution.actor,
    ...buildTraceAuthorityMetadata(context, options, attribution),
    evidence: normalizeListOption(options.evidence).map(normalizeProjectPathInput),
    related: normalizeListOption(options.related),
    git: {
      ...attribution.git,
      event,
      remote: getOptionString(options, "remote") || null,
      upstream: execGit(context.root, ["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"]),
      before_sha: getOptionString(options, "before-sha") || null,
      after_sha: getOptionString(options, "after-sha") || attribution.git.head_sha,
      pr_url: getOptionString(options, "pr-url") || null,
    },
    run: attribution.run,
  });
  output(options, { status: "recorded", event: traceEvent }, [`Recorded sync ${event}`]);
}

function testRunsRoot(context) {
  return path.join(context.sdlcRoot, "tests");
}

function normalizeRecordedCommandArgv(value) {
  const raw = String(value || "").trim();
  let argv;
  try {
    argv = JSON.parse(raw);
  } catch {
    fail(`--command must be a JSON argument vector, for example '["npm","test"]': ${raw}`);
  }
  if (
    !Array.isArray(argv)
    || argv.length === 0
    || argv.some((item) => typeof item !== "string" || item.length === 0 || item.includes("\0"))
  ) {
    fail("--command must be a non-empty JSON array of non-empty strings.");
  }
  return argv;
}

function boundedNonNegativeIntegerOption(options, key, { defaultValue = 0, maximum } = {}) {
  const raw = options[key];
  const value = raw === undefined || raw === null || raw === "" || raw === true
    ? defaultValue
    : Number(raw);
  if (!Number.isSafeInteger(value) || value < 0 || value > maximum) {
    fail(`--${key} must be an integer between 0 and ${maximum}`);
  }
  return value;
}

function deriveTestRunOutcome(exitCode, totals) {
  if (exitCode !== 0 || totals.failed > 0) {
    return "failed";
  }
  return totals.passed > 0 ? "passed" : "skipped";
}

function buildTestRunEvidence(context, options) {
  const evidence = normalizeListOption(options.evidence).map((rawPath) => {
    const evidencePath = resolveProjectFilePath(context, rawPath, { mustExist: true, fileOnly: true });
    assertNotDerivedArtifact(context, evidencePath, "Test run evidence");
    return {
      path: toProjectPath(context, evidencePath),
      size_bytes: fs.statSync(evidencePath).size,
      sha256: hashFile(evidencePath),
    };
  });
  if (evidence.length === 0) {
    fail(
      "test record needs at least one --evidence file holding the output of the run.",
      {
        en: {
          result: "The test run was not recorded because no output file was attached.",
          impact: "No record was written, and the story history is unchanged.",
          required_decision: "Decide which file holds the output a reviewer would read to confirm the result.",
          protection_boundary: "No approval, delivery, release, or wider file access was created.",
          next_action: "Save the test runner output to a file inside the project, then pass it with --evidence.",
          details: {},
        },
        it: {
          result: "L’esecuzione dei test non è stata registrata perché non è stato allegato alcun file di output.",
          impact: "Nessun record è stato scritto e la cronologia della story resta invariata.",
          required_decision: "Decidi quale file contiene l’output che una persona leggerebbe per confermare il risultato.",
          protection_boundary: "Non sono stati creati approvazioni, consegne, rilasci o accessi più ampi ai file.",
          next_action: "Salva l’output dello strumento di test in un file dentro il progetto, poi passalo con --evidence.",
          details: {},
        },
      },
    );
  }
  return evidence;
}

function recordTestRun(context, options) {
  ensureInitialized(context);
  const storyId = normalizeId(requireOption(options, "story"));
  const story = readStory(context, storyId);
  if (!story) {
    fail(`Story ${storyId} does not exist`);
  }
  const argv = normalizeRecordedCommandArgv(requireOption(options, "command"));
  requireOption(options, "exit-code");
  const exitCode = boundedNonNegativeIntegerOption(options, "exit-code", { maximum: 255 });
  const totals = {
    passed: boundedNonNegativeIntegerOption(options, "passed", { maximum: 1_000_000 }),
    failed: boundedNonNegativeIntegerOption(options, "failed", { maximum: 1_000_000 }),
    skipped: boundedNonNegativeIntegerOption(options, "skipped", { maximum: 1_000_000 }),
  };
  const outcome = deriveTestRunOutcome(exitCode, totals);
  const evidence = buildTestRunEvidence(context, options);

  const cwdInput = getOptionString(options, "cwd");
  const cwd = cwdInput
    ? toProjectPath(context, resolveProjectFilePath(context, cwdInput, { mustExist: true, directoryOnly: true })) || "."
    : ".";
  const startedAtInput = getOptionString(options, "started-at");
  const finishedAt = now();
  const startedAt = startedAtInput
    ? new Date(normalizeOptionalDateTime(startedAtInput, "started-at")).toISOString()
    : finishedAt;
  const durationMs = Date.parse(finishedAt) - Date.parse(startedAt);
  if (!Number.isSafeInteger(durationMs) || durationMs < 0) {
    fail("--started-at must be an RFC 3339 timestamp that is not later than the moment the record is written.");
  }

  const phase = getOptionString(options, "phase") || story.phase || null;
  if (phase && !context.config.phases[phase]) {
    fail(`Unknown phase '${phase}'. Use one of: ${Object.keys(context.config.phases).join(", ")}`);
  }
  const id = normalizeId(options.id ? String(options.id) : `${storyId}-test-run-${uniqueRecordSuffix()}`);
  const attribution = buildAttribution(context, options, "test.record");
  const record = {
    kind: "test_run",
    schema_version: "test-run:v1",
    id,
    story_id: storyId,
    phase,
    summary: getOptionString(options, "summary") || `Recorded ${outcome} test run for ${storyId}`,
    framework: getOptionString(options, "framework") || null,
    command: { argv, cwd },
    exit_code: exitCode,
    outcome,
    totals,
    started_at: startedAt,
    finished_at: finishedAt,
    duration_ms: durationMs,
    evidence,
    acceptance_criteria: normalizeListOption(options.acceptance),
    requirement_ids: normalizeListOption(options.requirement).map(normalizeId),
    actor: attribution.actor,
    git: attribution.git,
    run: attribution.run,
    created_at: finishedAt,
    audit: {
      created_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
    hash_algorithm: "sha256:stable-json:v1",
  };
  record.record_hash = computeStableHash(record);
  assertRecordSchema(record, "test-run.schema.json", `Test run ${id}`);

  const recordPath = path.join(testRunsRoot(context), `${id}.json`);
  assertNotDerivedArtifact(context, recordPath, "Test run record");
  writeJsonFile(recordPath, record, { force: Boolean(options.force) });

  const projectRecordPath = toProjectPath(context, recordPath);
  const traceEvent = appendTraceEvent(context, storyId, {
    type: "test",
    summary: record.summary,
    outcome,
    action: "test.record",
    actor: attribution.actor,
    ...buildTraceAuthorityMetadata(context, options, attribution),
    evidence: [projectRecordPath, ...evidence.map((item) => item.path)],
    related: record.requirement_ids,
    git: attribution.git,
    run: attribution.run,
  });

  output(
    options,
    {
      status: "recorded",
      test_run_path: projectRecordPath,
      test_run: record,
      event: traceEvent,
    },
    [
      `Recorded ${outcome} test run ${id} for story ${storyId}`,
      `Command: ${argv.join(" ")} (exit ${exitCode})`,
      `Results: ${totals.passed} passed, ${totals.failed} failed, ${totals.skipped} skipped`,
      `Path: ${projectRecordPath}`,
    ],
  );
}

function readTestRunRecords(context, storyId) {
  const normalizedStoryId = storyId ? normalizeId(String(storyId)) : null;
  const records = [];
  for (const name of safeReadDir(testRunsRoot(context))) {
    if (!name.endsWith(".json")) continue;
    const recordPath = path.join(testRunsRoot(context), name);
    let record;
    try {
      record = readProjectJson(context, recordPath);
    } catch {
      continue;
    }
    if (record?.kind !== "test_run") continue;
    if (normalizedStoryId && record.story_id !== normalizedStoryId) continue;
    records.push({ path: toProjectPath(context, recordPath), record });
  }
  return records.sort((left, right) =>
    String(left.record.finished_at || "").localeCompare(String(right.record.finished_at || ""), "en")
    || String(left.record.id || "").localeCompare(String(right.record.id || ""), "en"));
}

function operationsRoot(context) {
  return path.join(context.sdlcRoot, "operations");
}

function requireEnumOption(options, key, values) {
  const value = requireOption(options, key);
  if (!values.includes(value)) {
    fail(`--${key} must be one of: ${values.join(", ")}`);
  }
  return value;
}

function resolveIncidentFeedbackPhase(context, options, story) {
  const phase = getOptionString(options, "phase") || story.phase || null;
  if (phase && !context.config.phases[phase]) {
    fail(`Unknown phase '${phase}'. Use one of: ${Object.keys(context.config.phases).join(", ")}`);
  }
  return phase;
}

function resolveOperationsReleaseManifestId(context, options) {
  const releaseManifestInput = requireOption(options, "release-manifest");
  const { manifest } = readReleaseManifest(context, releaseManifestInput);
  return manifest.id;
}

function recordIncident(context, options) {
  ensureInitialized(context);
  const storyId = normalizeId(requireOption(options, "story"));
  const story = readStory(context, storyId);
  if (!story) {
    fail(`Story ${storyId} does not exist`);
  }
  const releaseManifestId = resolveOperationsReleaseManifestId(context, options);
  const severity = requireEnumOption(options, "severity", ["sev1", "sev2", "sev3", "sev4"]);
  const summary = requireOption(options, "summary");
  const impact = requireOption(options, "impact");
  const detectedAtInput = getOptionString(options, "detected-at");
  const detectedAt = detectedAtInput ? normalizeOptionalDateTime(detectedAtInput, "detected-at") : now();
  const resolvedAtInput = getOptionString(options, "resolved-at");
  const resolvedAt = resolvedAtInput ? normalizeOptionalDateTime(resolvedAtInput, "resolved-at") : null;
  const actions = normalizeListOption(options["incident-action"]);
  const phase = resolveIncidentFeedbackPhase(context, options, story);
  const id = normalizeId(options.id ? String(options.id) : `${storyId}-incident-${uniqueRecordSuffix()}`);
  const attribution = buildAttribution(context, options, "incident.record");
  const createdAt = now();
  const record = {
    kind: "incident",
    schema_version: "incident:v1",
    id,
    story_id: storyId,
    release_manifest_id: releaseManifestId,
    phase,
    severity,
    detected_at: detectedAt,
    resolved_at: resolvedAt,
    summary,
    impact,
    actions,
    requirement_ids: normalizeListOption(options.requirement).map(normalizeId),
    actor: attribution.actor,
    git: attribution.git,
    run: attribution.run,
    created_at: createdAt,
    audit: {
      created_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
    hash_algorithm: "sha256:stable-json:v1",
  };
  record.record_hash = computeStableHash(record);
  assertRecordSchema(record, "incident.schema.json", `Incident ${id}`);

  const recordPath = path.join(operationsRoot(context), `${id}.json`);
  assertNotDerivedArtifact(context, recordPath, "Incident record");
  writeJsonFile(recordPath, record, { force: Boolean(options.force) });
  const projectRecordPath = toProjectPath(context, recordPath);

  const traceEvent = appendTraceEvent(context, storyId, {
    type: "release",
    summary: record.summary,
    action: "incident.record",
    actor: attribution.actor,
    ...buildTraceAuthorityMetadata(context, options, attribution),
    evidence: [projectRecordPath],
    related: record.requirement_ids,
    git: attribution.git,
    run: attribution.run,
  });

  output(
    options,
    {
      status: "recorded",
      incident_path: projectRecordPath,
      incident: record,
      event: traceEvent,
    },
    [
      `Recorded ${severity} incident ${id} for story ${storyId}`,
      `Release manifest: ${releaseManifestId}`,
      `Path: ${projectRecordPath}`,
    ],
  );
}

function readIncidentRecords(context, storyId) {
  const normalizedStoryId = storyId ? normalizeId(String(storyId)) : null;
  const records = [];
  for (const name of safeReadDir(operationsRoot(context))) {
    if (!name.endsWith(".json")) continue;
    const recordPath = path.join(operationsRoot(context), name);
    let record;
    try {
      record = readProjectJson(context, recordPath);
    } catch {
      continue;
    }
    if (record?.kind !== "incident") continue;
    if (normalizedStoryId && record.story_id !== normalizedStoryId) continue;
    records.push({ path: toProjectPath(context, recordPath), record });
  }
  return records.sort((left, right) =>
    String(left.record.detected_at || "").localeCompare(String(right.record.detected_at || ""), "en")
    || String(left.record.id || "").localeCompare(String(right.record.id || ""), "en"));
}

function buildFeedbackEvidence(context, options) {
  return normalizeListOption(options.evidence).map((rawPath) => {
    const evidencePath = resolveProjectFilePath(context, rawPath, { mustExist: true, fileOnly: true });
    assertNotDerivedArtifact(context, evidencePath, "Feedback evidence");
    return {
      path: toProjectPath(context, evidencePath),
      size_bytes: fs.statSync(evidencePath).size,
      sha256: hashFile(evidencePath),
    };
  });
}

function recordFeedback(context, options) {
  ensureInitialized(context);
  const storyId = normalizeId(requireOption(options, "story"));
  const story = readStory(context, storyId);
  if (!story) {
    fail(`Story ${storyId} does not exist`);
  }
  const releaseManifestId = resolveOperationsReleaseManifestId(context, options);
  const source = requireEnumOption(options, "feedback-source", ["user", "monitoring", "review", "other"]);
  const summary = requireOption(options, "summary");
  const sentimentInput = getOptionString(options, "sentiment");
  if (sentimentInput && !["positive", "neutral", "negative"].includes(sentimentInput)) {
    fail("--sentiment must be one of: positive, neutral, negative");
  }
  const sentiment = sentimentInput || null;
  const evidence = buildFeedbackEvidence(context, options);
  const phase = resolveIncidentFeedbackPhase(context, options, story);
  const id = normalizeId(options.id ? String(options.id) : `${storyId}-feedback-${uniqueRecordSuffix()}`);
  const attribution = buildAttribution(context, options, "feedback.record");
  const createdAt = now();
  const record = {
    kind: "feedback",
    schema_version: "feedback:v1",
    id,
    story_id: storyId,
    release_manifest_id: releaseManifestId,
    phase,
    source,
    sentiment,
    summary,
    evidence,
    requirement_ids: normalizeListOption(options.requirement).map(normalizeId),
    actor: attribution.actor,
    git: attribution.git,
    run: attribution.run,
    created_at: createdAt,
    audit: {
      created_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
    hash_algorithm: "sha256:stable-json:v1",
  };
  record.record_hash = computeStableHash(record);
  assertRecordSchema(record, "feedback.schema.json", `Feedback ${id}`);

  const recordPath = path.join(operationsRoot(context), `${id}.json`);
  assertNotDerivedArtifact(context, recordPath, "Feedback record");
  writeJsonFile(recordPath, record, { force: Boolean(options.force) });
  const projectRecordPath = toProjectPath(context, recordPath);

  const traceEvent = appendTraceEvent(context, storyId, {
    type: "release",
    summary: record.summary,
    action: "feedback.record",
    actor: attribution.actor,
    ...buildTraceAuthorityMetadata(context, options, attribution),
    evidence: [projectRecordPath, ...evidence.map((item) => item.path)],
    related: record.requirement_ids,
    git: attribution.git,
    run: attribution.run,
  });

  output(
    options,
    {
      status: "recorded",
      feedback_path: projectRecordPath,
      feedback: record,
      event: traceEvent,
    },
    [
      `Recorded ${source} feedback ${id} for story ${storyId}`,
      `Release manifest: ${releaseManifestId}`,
      `Path: ${projectRecordPath}`,
    ],
  );
}

function readFeedbackRecords(context, storyId) {
  const normalizedStoryId = storyId ? normalizeId(String(storyId)) : null;
  const records = [];
  for (const name of safeReadDir(operationsRoot(context))) {
    if (!name.endsWith(".json")) continue;
    const recordPath = path.join(operationsRoot(context), name);
    let record;
    try {
      record = readProjectJson(context, recordPath);
    } catch {
      continue;
    }
    if (record?.kind !== "feedback") continue;
    if (normalizedStoryId && record.story_id !== normalizedStoryId) continue;
    records.push({ path: toProjectPath(context, recordPath), record });
  }
  return records.sort((left, right) =>
    String(left.record.created_at || "").localeCompare(String(right.record.created_at || ""), "en")
    || String(left.record.id || "").localeCompare(String(right.record.id || ""), "en"));
}

function appendOperationsPhaseGateChecks(context, report, storyId, story) {
  if (story?.phase !== "operations") return;
  const incidents = readIncidentRecords(context, storyId);
  const feedbackItems = readFeedbackRecords(context, storyId);
  report.checked.push(`${incidents.length} incident record(s) for story ${storyId}`);
  report.checked.push(`${feedbackItems.length} feedback record(s) for story ${storyId}`);
  if (incidents.length === 0 && feedbackItems.length === 0) {
    report.warnings.push(
      `Story ${storyId} is in the operations phase with no incident or feedback records yet.`,
    );
  }
}

function secretScansRoot(context) {
  return path.join(context.sdlcRoot, "security");
}

/**
 * Reads gate_policy.secret_scan from the effective project configuration.
 *
 * `enabled` is compared against true and not against false. A project whose
 * configuration predates this block keeps the gate it agreed to; only a project
 * initialized from the current template, or migrated through the reviewed
 * `config migrate` path, gets the blocking check. Rules and exclusions are
 * project data merged over the shipped defaults by the scanner, so a project
 * can retune one pattern without restating the rest.
 */
function secretScanPolicy(context) {
  return {
    enabled: context.config.gate_policy?.secret_scan?.enabled === true,
    rules: Array.isArray(context.config.gate_policy?.secret_scan?.rules)
      ? context.config.gate_policy.secret_scan.rules
      : [],
    excludePaths: Array.isArray(context.config.gate_policy?.secret_scan?.exclude_paths)
      ? context.config.gate_policy.secret_scan.exclude_paths
      : [],
  };
}

function resolveSecretScanCommit(context, ref, label) {
  const sha = execGit(context.root, ["rev-parse", "--verify", `${ref}^{commit}`]);
  if (!sha || !/^[a-f0-9]{40,64}$/iu.test(sha)) {
    fail(`--${label} must name a commit that exists in this repository: ${ref}`);
  }
  return sha.toLowerCase();
}

function secretScanGitPaths(context, args) {
  return String(execGit(context.root, args) || "")
    .split(/\r?\n/u)
    .map((item) => item.trim())
    .filter(Boolean);
}

/**
 * Resolve which files one delivery changed.
 *
 * The preferred source is the committed range between the delivery's base and
 * the current head. A story whose work is not committed yet falls back to the
 * uncommitted workspace, and a local release with neither falls back to the
 * files inside the write paths the story's approved requirement profiles
 * recorded. Every source names the same head commit, so a stored record always
 * states which project state was scanned.
 */
function resolveSecretScanTargets(context, storyId, options) {
  if (execGit(context.root, ["rev-parse", "--is-inside-work-tree"]) !== "true") {
    if (getOptionString(options, "base") || getOptionString(options, "head")) {
      fail("--base and --head need the project to be a Git worktree.");
    }
    return {
      source: "story_write_paths",
      base_sha: null,
      head_sha: null,
      paths: secretScanStoryWritePaths(context, storyId),
    };
  }
  const headSha = resolveSecretScanCommit(context, getOptionString(options, "head") || "HEAD", "head");
  const explicitBase = getOptionString(options, "base");
  const taskStartPath = path.join(context.sdlcRoot, "stories", storyId, "task-start.json");
  const recordedBase = fs.existsSync(taskStartPath)
    ? readProjectJson(context, taskStartPath)?.audit?.git?.head_sha || null
    : null;
  const baseCandidate = explicitBase
    || (recordedBase
      && /^[a-f0-9]{7,64}$/iu.test(recordedBase)
      && gitCommandSucceeds(context.root, ["cat-file", "-e", `${recordedBase}^{commit}`])
      ? recordedBase
      : null);
  if (baseCandidate) {
    const baseSha = resolveSecretScanCommit(context, baseCandidate, "base");
    return {
      source: "git_range",
      base_sha: baseSha,
      head_sha: headSha,
      paths: secretScanGitPaths(context, ["diff", "--name-only", "--no-renames", `${baseSha}..${headSha}`, "--"]),
    };
  }
  const workspacePaths = [
    ...secretScanGitPaths(context, ["diff", "--name-only", "--no-renames", "HEAD", "--"]),
    ...secretScanGitPaths(context, ["ls-files", "--others", "--exclude-standard"]),
  ];
  if (workspacePaths.length > 0) {
    return { source: "git_workspace", base_sha: null, head_sha: headSha, paths: workspacePaths };
  }
  return {
    source: "story_write_paths",
    base_sha: null,
    head_sha: headSha,
    paths: secretScanStoryWritePaths(context, storyId),
  };
}

function secretScanStoryWritePaths(context, storyId) {
  const story = readStory(context, storyId);
  const requirementIds = Array.isArray(story?.links?.requirements) ? story.links.requirements.filter(Boolean) : [];
  const writePaths = new Set();
  for (const requirementId of requirementIds) {
    const requirement = readRequirement(context, requirementId, { missingOk: true });
    if (!requirement?.autonomy_profile_id) continue;
    let profile;
    try {
      profile = readRequirementAutonomyProfile(context, requirement.autonomy_profile_id);
    } catch {
      continue;
    }
    for (const writePath of profile.constraints?.allowed_write_paths || []) {
      writePaths.add(String(writePath));
    }
  }
  const files = [];
  for (const writePath of writePaths) {
    const base = writePath.replace(/\*+.*$/u, "").replace(/\/$/u, "");
    if (!base) continue;
    const resolved = resolveProjectFilePath(context, base, { mustExist: false });
    if (!fs.existsSync(resolved)) continue;
    if (fs.statSync(resolved).isDirectory()) files.push(...listProjectFilesUnder(context, resolved));
    else files.push(toProjectPath(context, resolved));
  }
  return files;
}

function listProjectFilesUnder(context, directoryPath) {
  const files = [];
  for (const name of safeReadDir(directoryPath)) {
    const entryPath = path.join(directoryPath, name);
    let entry;
    try {
      entry = fs.lstatSync(entryPath);
    } catch {
      continue;
    }
    if (entry.isSymbolicLink()) continue;
    if (entry.isDirectory()) {
      if (name === ".git" || name === "node_modules") continue;
      files.push(...listProjectFilesUnder(context, entryPath));
    } else if (entry.isFile()) {
      files.push(toProjectPath(context, entryPath));
    }
  }
  return files;
}

/** Content above this size, or holding a NUL byte, is not text and is not scanned. */
const SECRET_SCAN_MAX_FILE_BYTES = 4 * 1024 * 1024;

function readSecretScanFiles(context, projectPaths) {
  const files = [];
  const unreadable = [];
  for (const projectPath of [...new Set(projectPaths)].sort((left, right) => left.localeCompare(right, "en"))) {
    let resolved;
    try {
      resolved = resolveProjectFilePath(context, projectPath, { mustExist: false });
      assertNoSymlinkSegmentsWithinBoundary(context.root, resolved);
    } catch {
      unreadable.push(projectPath);
      continue;
    }
    if (!fs.existsSync(resolved) || !fs.statSync(resolved).isFile()) {
      unreadable.push(projectPath);
      continue;
    }
    const content = fs.readFileSync(resolved);
    if (content.length > SECRET_SCAN_MAX_FILE_BYTES || content.includes(0)) {
      unreadable.push(projectPath);
      continue;
    }
    files.push({ path: toProjectPath(context, resolved), content: content.toString("utf8") });
  }
  return { files, unreadable };
}

function runSecretScan(context, options) {
  ensureInitialized(context);
  const storyId = normalizeId(requireOption(options, "story"));
  const story = readStory(context, storyId);
  if (!story) {
    fail(`Story ${storyId} does not exist`);
  }
  const policy = secretScanPolicy(context);
  const startedAt = now();
  const targets = resolveSecretScanTargets(context, storyId, options);
  const { files, unreadable } = readSecretScanFiles(context, targets.paths);

  let scan;
  try {
    scan = scanFiles(files, { rules: policy.rules, excludePaths: policy.excludePaths });
  } catch (error) {
    if (error instanceof SecretScanConfigurationError) {
      fail(`gate_policy.secret_scan is not usable: ${error.message}`);
    }
    throw error;
  }

  const phase = getOptionString(options, "phase") || story.phase || null;
  if (phase && !context.config.phases[phase]) {
    fail(`Unknown phase '${phase}'. Use one of: ${Object.keys(context.config.phases).join(", ")}`);
  }
  const id = normalizeId(options.id ? String(options.id) : `${storyId}-secret-scan-${uniqueRecordSuffix()}`);
  const attribution = buildAttribution(context, options, "secret.scan");
  const finishedAt = now();
  const record = {
    kind: "secret_scan",
    schema_version: "secret-scan:v1",
    id,
    story_id: storyId,
    delivery_id: getOptionString(options, "delivery") || null,
    phase,
    summary: getOptionString(options, "summary")
      || `Scanned ${scan.scanned_paths.length} changed file(s) of ${storyId} for credentials`,
    base_sha: targets.base_sha,
    head_sha: targets.head_sha,
    source: targets.source,
    file_count: scan.scanned_paths.length,
    scanned_paths: scan.scanned_paths,
    excluded_paths: [...scan.skipped_paths, ...unreadable]
      .sort((left, right) => left.localeCompare(right, "en")),
    rule_set_hash: scan.rule_set_hash,
    rule_ids: scan.rules.map((rule) => rule.id),
    findings: scan.findings,
    outcome: scan.outcome,
    started_at: startedAt,
    finished_at: finishedAt,
    duration_ms: Math.max(0, Date.parse(finishedAt) - Date.parse(startedAt)),
    requirement_ids: normalizeListOption(options.requirement).map(normalizeId),
    actor: attribution.actor,
    git: attribution.git,
    run: attribution.run,
    created_at: finishedAt,
    audit: {
      created_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
    hash_algorithm: "sha256:stable-json:v1",
  };
  record.record_hash = computeStableHash(record);
  assertRecordSchema(record, "secret-scan.schema.json", `Secret scan ${id}`);

  const recordPath = path.join(secretScansRoot(context), `${id}.json`);
  assertNotDerivedArtifact(context, recordPath, "Secret scan record");
  writeJsonFile(recordPath, record, { force: Boolean(options.force) });
  const projectRecordPath = toProjectPath(context, recordPath);

  const traceEvent = appendTraceEvent(context, storyId, {
    type: "gate",
    summary: record.summary,
    outcome: scan.outcome === "clean" ? "passed" : "failed",
    action: "secret.scan",
    actor: attribution.actor,
    ...buildTraceAuthorityMetadata(context, options, attribution),
    evidence: [projectRecordPath],
    related: record.requirement_ids,
    git: attribution.git,
    run: attribution.run,
  });

  const lines = [
    scan.outcome === "clean"
      ? `No credential pattern matched in ${record.file_count} scanned file(s) of story ${storyId}`
      : `Found ${record.findings.length} credential match(es) in ${record.file_count} scanned file(s) of story ${storyId}`,
    `Source: ${record.source}${record.head_sha ? ` (head ${record.head_sha.slice(0, 12)}` : " (no Git head"}${record.base_sha ? `, base ${record.base_sha.slice(0, 12)})` : ")"}`,
    ...record.findings.map((finding) => `${finding.path}:${finding.line} ${finding.rule} ${finding.redacted_match}`),
    `Path: ${projectRecordPath}`,
  ];
  if (scan.outcome !== "clean") {
    lines.push("Remove each credential from the file, rotate it at its provider, then run secret scan again.");
  }
  // A scan with findings reports the blocked status so the human-readable
  // envelope frames it as a refused request, which is what the exit code says.
  output(
    options,
    {
      status: scan.outcome === "clean" ? "clean" : "blocked",
      outcome: scan.outcome,
      secret_scan_path: projectRecordPath,
      secret_scan: record,
      event: traceEvent,
    },
    lines,
  );
  if (scan.outcome !== "clean") {
    process.exitCode = EXIT_CODES.userError;
  }
}

function readSecretScanRecords(context, storyId) {
  const normalizedStoryId = storyId ? normalizeId(String(storyId)) : null;
  const records = [];
  for (const name of safeReadDir(secretScansRoot(context))) {
    if (!name.endsWith(".json")) continue;
    const recordPath = path.join(secretScansRoot(context), name);
    let record;
    try {
      record = readProjectJson(context, recordPath);
    } catch {
      continue;
    }
    if (record?.kind !== "secret_scan") continue;
    if (normalizedStoryId && record.story_id !== normalizedStoryId) continue;
    records.push({ path: toProjectPath(context, recordPath), record });
  }
  return records.sort((left, right) =>
    String(left.record.finished_at || "").localeCompare(String(right.record.finished_at || ""), "en")
    || String(left.record.id || "").localeCompare(String(right.record.id || ""), "en"));
}

function codeReviewsRoot(context) {
  return path.join(context.sdlcRoot, "reviews");
}

/**
 * Author identities of every commit in base..head, read from the repository.
 */
function codeReviewRangeAuthors(context, baseSha, headSha) {
  return parseCommitAuthors(execGit(context.root, ["log", "--format=%an%x00%ae", `${baseSha}..${headSha}`, "--"]));
}

function readPullRequestDeliveryForReview(context, profileId) {
  const profile = readDeliveryAutonomyProfile(context, profileId);
  if (profile.delivery_kind !== "pull_request" || !profile.pull_request_target) {
    fail(`Delivery profile ${profileId} is not a pull-request delivery; only a pull request diff can be reviewed.`);
  }
  const storyId = profile.story_refs?.length === 1 ? profile.story_refs[0].id : null;
  if (!storyId) {
    fail(`Delivery profile ${profileId} does not name exactly one story.`);
  }
  return { profile, storyId };
}

function recordCodeReview(context, options) {
  ensureInitialized(context);
  const profileId = normalizeId(requireOption(options, "delivery"));
  const verdict = requireOption(options, "verdict");
  if (!CODE_REVIEW_VERDICTS.includes(verdict)) {
    fail(`--verdict must be one of: ${CODE_REVIEW_VERDICTS.join(", ")}.`);
  }
  let findings;
  try {
    findings = normalizeCodeReviewFindings(normalizeRawListOption(options.finding));
  } catch (error) {
    if (error instanceof TypeError) fail(`--finding is invalid: ${error.message}.`);
    throw error;
  }
  if (verdict === "approved" && findings.some((finding) => finding.severity === "blocking")) {
    fail("An approved review cannot carry a blocking finding; record --verdict changes_requested instead.");
  }
  const { profile, storyId } = readPullRequestDeliveryForReview(context, profileId);
  const target = profile.pull_request_target;
  // The reviewed commit is whatever the head branch points at now, read from
  // the repository. A caller-supplied commit would let a review of one state
  // stand in for another.
  const runtimeTarget = validatePullRequestGitBoundary(context, target);
  if (!runtimeTarget.base_sha || !runtimeTarget.head_sha) {
    fail(`Delivery ${profile.delivery_id} has no resolvable base and head commit to review.`);
  }
  const attribution = buildAttribution(context, options, "review.record");
  const gitName = attribution.git.user?.name || null;
  const gitEmail = attribution.git.user?.email || null;
  if (!gitName || !gitEmail) {
    fail("The reviewer's Git identity is incomplete: set git config user.name and user.email before recording a review.");
  }
  const reviewer = {
    actor_id: attribution.actor.id,
    actor_type: attribution.actor.type,
    git_name: gitName,
    git_email: gitEmail,
  };
  const commitAuthors = codeReviewRangeAuthors(context, runtimeTarget.base_sha, runtimeTarget.head_sha);
  const conflicts = reviewerAuthorConflicts(reviewer, commitAuthors);
  const reviewedAt = now();
  const id = normalizeId(options.id ? String(options.id) : `${storyId}-code-review-${uniqueRecordSuffix()}`);
  const record = {
    kind: "code_review",
    schema_version: "code-review:v1",
    id,
    story_id: storyId,
    delivery_id: profile.delivery_id,
    delivery_profile_id: profile.id,
    repository: target.repository,
    base_branch: target.base_branch,
    head_branch: target.head_branch,
    base_sha: runtimeTarget.base_sha.toLowerCase(),
    reviewed_head_sha: runtimeTarget.head_sha.toLowerCase(),
    commit_authors: commitAuthors,
    reviewer,
    verdict,
    findings,
    summary: getOptionString(options, "summary")
      || `Code review of ${profile.delivery_id} at ${runtimeTarget.head_sha.slice(0, 12)}: ${verdict}`,
    reviewed_at: reviewedAt,
    requirement_ids: normalizeListOption(options.requirement).map(normalizeId),
    actor: attribution.actor,
    git: attribution.git,
    run: attribution.run,
    created_at: reviewedAt,
    audit: {
      created_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
    hash_algorithm: "sha256:stable-json:v1",
  };
  record.record_hash = computeStableHash(record);
  assertRecordSchema(record, "code-review.schema.json", `Code review ${id}`);

  const recordPath = path.join(codeReviewsRoot(context), `${id}.json`);
  assertNotDerivedArtifact(context, recordPath, "Code review record");
  writeJsonFile(recordPath, record, { force: Boolean(options.force) });
  const projectRecordPath = toProjectPath(context, recordPath);

  const traceEvent = appendTraceEvent(context, storyId, {
    type: "gate",
    summary: record.summary,
    outcome: verdict === "approved" && conflicts.length === 0 ? "passed" : "failed",
    action: "review.record",
    actor: attribution.actor,
    ...buildTraceAuthorityMetadata(context, options, attribution),
    evidence: [projectRecordPath],
    related: record.requirement_ids,
    git: attribution.git,
    run: attribution.run,
  });

  const lines = [
    `Recorded ${verdict} review of ${profile.delivery_id} at head ${record.reviewed_head_sha.slice(0, 12)} by ${reviewer.actor_id} <${reviewer.git_email}>`,
    `Range: ${record.base_sha.slice(0, 12)}..${record.reviewed_head_sha.slice(0, 12)} (${commitAuthors.length} author(s))`,
    ...findings.map((finding) =>
      `${finding.severity}: ${finding.summary}${finding.path ? ` (${finding.path}${finding.line ? `:${finding.line}` : ""})` : ""}`),
    `Path: ${projectRecordPath}`,
  ];
  if (conflicts.length > 0) {
    lines.push(
      "This reviewer also authored commits in the reviewed range, so this review does not satisfy the merge gate. "
      + "A reviewer whose actor and Git email differ from every author must review it.",
    );
  }
  output(
    options,
    {
      status: "recorded",
      verdict,
      independent: conflicts.length === 0,
      code_review_path: projectRecordPath,
      code_review: record,
      event: traceEvent,
    },
    lines,
  );
}

/**
 * Code review records for one delivery profile whose content still matches
 * its schema and its own record hash. A record edited after it was written is
 * not evidence of the review it claims.
 */
function readCodeReviewRecords(context, profileId) {
  const records = [];
  for (const name of safeReadDir(codeReviewsRoot(context))) {
    if (!name.endsWith(".json")) continue;
    let record;
    try {
      record = readProjectJson(context, path.join(codeReviewsRoot(context), name));
    } catch {
      continue;
    }
    if (record?.kind !== "code_review" || record.delivery_profile_id !== profileId) continue;
    if (!validateRecordSchema(record, "code-review.schema.json").valid) continue;
    const { record_hash: recordHash, ...unhashed } = record;
    if (computeStableHash(unhashed) !== recordHash) continue;
    records.push(record);
  }
  return records;
}

/**
 * Enforces gate_policy.merge_requires_code_review before pull_request.merge.
 *
 * The flag is read as `=== true`. A project that never declared it keeps the
 * merge gate it agreed to, so a plugin update cannot start refusing merges in
 * a project that did not opt in; the current template declares it, and an
 * existing project adopts it through the reviewed `config migrate` path.
 *
 * When on, the merge needs an approved `code-review:v1` record for this
 * delivery at exactly the head being merged, by a reviewer whose actor and Git
 * email differ from every author of base..head.
 */
function enforceMergeCodeReview(context, profile, runtimeTarget) {
  if (context.config.gate_policy?.merge_requires_code_review !== true) {
    return;
  }
  const headSha = String(runtimeTarget?.head_sha || "").toLowerCase();
  const authors = runtimeTarget?.base_sha
    ? codeReviewRangeAuthors(context, runtimeTarget.base_sha, headSha)
    : [];
  const decision = evaluateMergeReviews(readCodeReviewRecords(context, profile.id), {
    deliveryProfileId: profile.id,
    headSha,
    authors,
  });
  if (decision.allowed) {
    return;
  }
  const shortHead = headSha.slice(0, 12);
  const reasons = {
    no_review_for_head: {
      message: `no approved code review exists for head ${shortHead}`,
      en: `No code review was recorded for the commit being merged (${shortHead}). A review of an earlier commit does not cover later changes.`,
      it: `Non è stata registrata alcuna revisione del codice per il commit da unire (${shortHead}). La revisione di un commit precedente non copre le modifiche successive.`,
    },
    reviewer_is_author: {
      message: `review ${decision.review?.id} was recorded by an author of the reviewed range`,
      en: "The only review for this commit was recorded by someone who also authored commits in the pull request.",
      it: "L’unica revisione per questo commit è stata registrata da chi ha anche scritto commit nella pull request.",
    },
    changes_requested: {
      message: `the latest independent review ${decision.review?.id} requested changes`,
      en: "The latest independent review of this commit requested changes.",
      it: "L’ultima revisione indipendente di questo commit ha richiesto modifiche.",
    },
  }[decision.reason];
  const details = {
    delivery_profile_id: profile.id,
    delivery_id: profile.delivery_id,
    head_sha: headSha,
    reason: decision.reason,
    review_id: decision.review?.id || null,
  };
  fail(
    `Delivery action pull_request.merge is refused for ${profile.id}: ${reasons.message}. `
    + `Run 'review record --delivery ${profile.id} --verdict approved' as a reviewer who is not an author of the pull request.`,
    {
      en: {
        result: "The pull request cannot be merged yet.",
        impact: reasons.en,
        required_decision: "A person who did not author any commit in this pull request reviews the current diff.",
        protection_boundary: "Nothing was merged, pushed, or recorded as authorized.",
        next_action: `The reviewer records the outcome with 'review record --delivery ${profile.id} --verdict approved', then the merge is requested again.`,
        details,
      },
      it: {
        result: "La pull request non può ancora essere unita.",
        impact: reasons.it,
        required_decision: "Una persona che non ha scritto alcun commit di questa pull request revisiona il diff corrente.",
        protection_boundary: "Nulla è stato unito, inviato o registrato come autorizzato.",
        next_action: `Il revisore registra l’esito con 'review record --delivery ${profile.id} --verdict approved', poi il merge viene richiesto di nuovo.`,
        details,
      },
    },
  );
}

function initializeDependencyGraph(context, options = {}) {
  ensurePlanningDirectories(context);
  const graphPath = dependencyGraphPath(context);
  if (fs.existsSync(graphPath) && !options.force) {
    return readProjectJson(context, graphPath);
  }
  const attribution = options.attribution || buildAttribution(context, {}, "dependency.graph.init");
  const graph = {
    schema_version: context.config.schema_version,
    status: "approved",
    edges: [],
    updated_at: now(),
    audit: {
      created_by: attribution.actor,
      updated_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
  };
  writeJsonFile(graphPath, graph, { force: true });
  return graph;
}

function initializeOutputContracts(context, options = {}) {
  const root = outputContractsRoot(context);
  ensureDir(root);
  ensureDir(path.join(root, "templates"));
  ensureDir(path.join(root, "decisions"));

  const registryPath = outputRegistryPath(context);
  if (fs.existsSync(registryPath) && !options.force) {
    return readProjectJson(context, registryPath);
  }

  const project = readProjectSafe(context);
  const attribution = options.attribution || buildAttribution(context, {}, "output.registry.init");
  const registry = {
    schema_version: context.config.schema_version,
    project_id: options.project_id || project?.project_id || null,
    status: "active",
    policy: {
      template_registry_scope: "project",
      default_related_story_mode: "reuse+delta",
      approvals_required_for_new_templates: true,
      cache_is_source_of_truth: false,
    },
    templates: [],
    links: [],
    decisions: [],
    created_at: now(),
    updated_at: now(),
    audit: {
      created_by: attribution.actor,
      updated_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
  };
  writeJsonFile(registryPath, registry, { force: Boolean(options.force) });
  return registry;
}

function proposeOutputTemplate(context, options) {
  ensureInitialized(context);
  const artifactType = normalizeArtifactType(requireOption(options, "type"));
  const id = normalizeId(options.id || `${artifactType}-v1`);
  const delivery = buildOutputDelivery(options);
  const attribution = buildAttribution(context, options, "output.template.propose");
  const content = buildOutputTemplateContent(context, options, artifactType, id);
  return withOutputRegistryLock(context, () => {
  const registry = readOutputRegistry(context, { create: true, options, action: "output.template.propose" });
  if (findOutputTemplate(registry, id) && !options.force) {
    fail(`Output template ${id} already exists. Use --force to replace its proposal metadata.`);
  }

  const templatePath = path.join(outputContractsRoot(context), "templates", `${id}.md`);
  writeTextFile(templatePath, content.text, { force: Boolean(options.force) });

  const relativeTemplatePath = toProjectPath(context, templatePath);
  const templateRecord = {
    id,
    type: artifactType,
    status: "draft",
    path: relativeTemplatePath,
    summary: getOptionString(options, "summary") || null,
    preset: content.preset || null,
    delivery,
    source_paths: content.source_paths,
    proposed_at: now(),
    approved_at: null,
    approved_by: null,
    audit: {
      proposed_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
  };

  upsertById(registry.templates, templateRecord);
  registry.updated_at = now();
  registry.audit = {
    ...(registry.audit || {}),
    updated_by: attribution.actor,
    git: attribution.git,
    run: attribution.run,
  };
  writeOutputRegistry(context, registry);
  appendTraceEvent(context, null, {
    type: "decision",
    summary: `Proposed output template ${id} for ${artifactType}`,
    action: "output.template.propose",
    actor: attribution.actor,
    evidence: [relativeTemplatePath, toProjectPath(context, outputRegistryPath(context))],
    related: [id, artifactType],
    git: attribution.git,
    run: attribution.run,
  });
  const approvalRequest = buildOutputTemplateApprovalRequest(context, templateRecord);
  const assistantMessage = renderApprovalRequestsAssistantMessage([approvalRequest]);
  const localizedAssistantLines = approvalAssistantMessageLinesForLocale(
    [approvalRequest],
    options,
    assistantMessage,
  );

  output(
    options,
    {
      status: "proposed",
      template_path: templatePath,
      template: templateRecord,
      assistant_message: assistantMessage,
      ...assistantMessagePresentationFields(),
      approval_request: approvalRequest,
    },
    [
      humanGuidanceLocale(options) === "it"
        ? `Proposto il formato di risultato ${id} per ${artifactType}`
        : `Proposed output template ${id} for ${artifactType}`,
      "",
      ...localizedAssistantLines,
    ],
  );
  });
}

function approveOutputTemplate(context, options) {
  ensureInitialized(context);
  return withOutputRegistryLock(context, () => {
  const id = normalizeId(requireOption(options, "id"));
  const registry = readOutputRegistry(context, { create: true, options, action: "output.template.approve" });
  const template = findOutputTemplate(registry, id);
  if (!template) {
    fail(`Output template ${id} does not exist`);
  }

  const attribution = buildAttribution(context, options, "output.template.approve");
  requireFormalApprovalActor(context, options, attribution, "Approving an output template");

  const decisionId = normalizeId(String(options["decision-id"] || `DEC-output-template-${id}-${uniqueRecordSuffix()}`));
  const templatePath = resolveProjectFilePath(context, template.path, { mustExist: true, fileOnly: true });
  assertNotDerivedArtifact(context, templatePath, "Output template");
  const approvedContentHash = hashFile(templatePath);
  const delivery = effectiveOutputDelivery(template);
  const approvedDeliveryHash = hashApprovalSubject(delivery);
  const approvalEvidence = buildApprovalEvidence(context, options);
  const approvalSummaryOption = getOptionString(options, "summary") || null;
  const approvalSummary = approvalSummaryOption || template.approval_summary || null;
  const approvalSource = normalizeApprovalSource(context, options, attribution, `output template ${id}`, "approved");
  validateApprovalSourceForActor(context, {
    source: approvalSource,
    status: "approved",
    summary: approvalSummaryOption,
    evidence: approvalEvidence,
    actor: attribution.actor,
    label: `output template ${id}`,
  });
  const authorization = approvalSource === "automation"
    ? requireAutomationAuthorization(context, options, attribution.action, { label: `output template ${id}`, subject_id: id, artifact_type: template.type })
    : null;
  const approvalScope = buildApprovalRecordScope(approvalSource, {
    subject_id: id,
    artifact_type: template.type,
    label: `output template ${id}`,
    scope: String(options.scope || "output_template"),
    authorization,
  });
  template.status = "approved";
  template.approved_at = now();
  template.approved_by = attribution.actor;
  template.approval_summary = approvalSummary;
  template.approved_content_hash = approvedContentHash;
  template.approved_delivery_hash = approvedDeliveryHash;
  template.hash_algorithm = "sha256:file:v1";
  template.approval_evidence = approvalEvidence;
  template.approval_source = approvalSource;
  template.authorization_ref = authorization?.id || null;
  template.authorization_use_ref = authorization?.__use_receipt?.path || null;
  template.authorization_action = authorization ? attribution.action : null;
  template.approval_scope = approvalScope;
  template.explicit_user_confirmation = approvalSource === "explicit-user";
  template.provisional = approvalSource === "bootstrap";
  template.audit = {
    ...(template.audit || {}),
    approved_by: attribution.actor,
    git: attribution.git,
    run: attribution.run,
  };

  const decision = {
    id: decisionId,
    type: "template_approved",
    template_id: id,
    artifact_type: template.type,
    summary: template.approval_summary,
    status: "approved",
    evidence: template.approval_evidence,
    approval_source: approvalSource,
    authorization_ref: authorization?.id || null,
    authorization_use_ref: authorization?.__use_receipt?.path || null,
    authorization_action: authorization ? attribution.action : null,
    approval_scope: approvalScope,
    explicit_user_confirmation: approvalSource === "explicit-user",
    provisional: approvalSource === "bootstrap",
    approved_content_hash: approvedContentHash,
    approved_delivery_hash: approvedDeliveryHash,
    delivery,
    hash_algorithm: "sha256:file:v1",
    created_at: now(),
    audit: {
      decided_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
  };
  upsertById(registry.decisions, decision);
  registry.updated_at = now();
  registry.audit = {
    ...(registry.audit || {}),
    updated_by: attribution.actor,
    git: attribution.git,
    run: attribution.run,
  };
  writeOutputRegistry(context, registry);
  appendTraceEvent(context, null, {
    type: "gate",
    summary: `Approved output template ${id}`,
    action: "output.template.approve",
    actor: attribution.actor,
    evidence: [template.path, toProjectPath(context, outputRegistryPath(context))],
    related: [id, decisionId],
    git: attribution.git,
    run: attribution.run,
  });

  output(options, { status: "approved", template, decision }, [`Approved output template ${id}`]);
  });
}

function resolveOutput(context, options) {
  ensureInitialized(context);
  const storyId = normalizeId(requireOption(options, "story"));
  const artifactType = normalizeArtifactType(requireOption(options, "type"));
  const explicitRequirements = normalizeListOption(options.requirement);
  const cacheStatus = getCacheStatus(context);
  const canonicalResolution = buildOutputResolution(context, storyId, artifactType, {
    requirements: explicitRequirements,
    cache_used: false,
  });
  let resolution = canonicalResolution;

  if (explicitRequirements.length === 0 && cacheStatus.valid && cacheStatus.cache?.output_resolutions) {
    const cachedResolution = cacheStatus.cache.output_resolutions[outputResolutionKey(storyId, artifactType)] || null;
    if (cachedResolution) {
      if (outputResolutionFingerprint(cachedResolution) !== outputResolutionFingerprint(canonicalResolution)) {
        fail("Local cache output resolution differs from canonical KB files. Run 'agentic-sdlc cache rebuild'.");
      }
      resolution = { ...canonicalResolution, cache_used: true };
    }
  }

  const decisionRequired = ["template_required", "reuse_delta"].includes(resolution.recommendation);
  const payload = {
    ...resolution,
    status: decisionRequired ? "needs_user_input" : "resolved",
    decision_required: decisionRequired,
    human_guidance: outputResolutionGuidance(resolution, options),
  };
  output(
    options,
    payload,
    humanGuidanceLines(payload.human_guidance, [
      `Output resolution for ${storyId}/${artifactType}: ${resolution.recommendation}`,
      resolution.template_id ? `Template: ${resolution.template_id}` : "Template: missing approved template",
      resolution.delivery ? `Canonical delivery: ${formatOutputDeliveryForHuman(resolution.delivery)}` : null,
      resolution.base_artifact ? `Base artifact: ${resolution.base_artifact}` : "Base artifact: none",
      resolution.next_action,
    ].filter(Boolean), options),
  );
}

function outputResolutionGuidance(resolution, options = {}) {
  const italian = humanGuidanceLocale(options) === "it";
  if (resolution.recommendation === "template_required") {
    return {
      result: italian
        ? "Manca ancora un formato governato per questo risultato."
        : "A governed format for this result is still missing.",
      impact: italian
        ? "Il risultato non può essere creato o collegato finché struttura e formato canonico non sono stati concordati."
        : "The result cannot be created or linked until its structure and canonical file format are agreed.",
      required_decision: italian
        ? "Esamina la struttura proposta e approvala, oppure chiedi di cambiare sezioni o formato del file."
        : "Review and approve the proposed structure, or ask to change its sections or file format.",
      protection_boundary: italian
        ? "Questa verifica non crea documenti, non approva formati e non autorizza una consegna."
        : "This lookup creates no document, approves no format, and authorizes no delivery.",
      next_action: italian
        ? "Proponi il formato, esamina la struttura mostrata e approvala prima di scrivere il risultato."
        : "Propose the format, review the displayed structure, and approve it before writing the result.",
      details: {},
    };
  }
  if (resolution.recommendation === "reuse_delta") {
    return {
      result: italian
        ? "Esiste già un risultato approvato che può essere riutilizzato."
        : "An approved result already exists and can be reused.",
      impact: italian
        ? "È sufficiente produrre solo le differenze necessarie, senza duplicare tutto il documento."
        : "Only the necessary differences need to be produced instead of duplicating the whole document.",
      required_decision: italian
        ? "Conferma che il risultato precedente sia ancora una base valida, oppure richiedi un nuovo documento completo."
        : "Confirm that the earlier result is still a valid base, or request a complete new document.",
      protection_boundary: italian
        ? "La base esistente non viene modificata e nessun nuovo risultato viene collegato da questa verifica."
        : "The existing base is not modified, and this lookup links no new result.",
      next_action: italian
        ? "Conferma il riuso; poi crea e collega soltanto le differenze concordate."
        : "Confirm reuse, then create and link only the agreed differences.",
      details: {},
    };
  }
  return {
    result: resolution.recommendation === "linked"
      ? (italian ? "Il risultato ufficiale è già collegato." : "The official result is already linked.")
      : (italian ? "È disponibile un formato approvato per creare il risultato." : "An approved format is available for creating the result."),
    impact: resolution.recommendation === "linked"
      ? (italian ? "I controlli successivi useranno il file già registrato." : "Later checks will use the file already recorded.")
      : (italian ? "Il risultato può essere scritto nel formato concordato e poi collegato ai controlli." : "The result can be written in the agreed format and then linked for checks."),
    required_decision: italian
      ? "Non serve una nuova decisione, salvo che tu voglia cambiare formato o sostituire il risultato."
      : "No new decision is needed unless you want to change the format or replace the result.",
    protection_boundary: italian
      ? "Questa verifica non crea, modifica o collega alcun file."
      : "This lookup creates, changes, or links no file.",
    next_action: resolution.recommendation === "linked"
      ? (italian ? "Continua con il prossimo controllo concordato." : "Continue with the next agreed check.")
      : (italian ? "Crea il file nel formato approvato e collegalo come risultato ufficiale." : "Create the file in the approved format and link it as the official result."),
    details: {},
  };
}

function outputResolutionFingerprint(resolution) {
  const comparable = { ...resolution };
  delete comparable.cache_used;
  return stableJson(comparable);
}

function outputRenderEvidenceOptions(options) {
  return Array.from(new Set([
    ...normalizeListOption(options["render-evidence"]),
    ...normalizeListOption(options.evidence),
  ]));
}

function linkOutputArtifact(context, options) {
  ensureInitialized(context);
  const storyId = normalizeId(requireOption(options, "story"));
  if (!readStory(context, storyId)) {
    fail(`Story ${storyId} does not exist`);
  }
  const releaseTaskStartBoundaryLock = acquireFileLock(
    path.join(context.sdlcRoot, "stories", storyId, "task-start-boundary.lock"),
  );
  let releaseLifecycleLock = () => {};
  try {
    releaseLifecycleLock = acquireFileLock(
      storyLifecycleCertificationLockPath(context, storyId),
    );
    const story = readStory(context, storyId);
    if (!story) {
      fail(`Story ${storyId} does not exist`);
    }
    return withOutputRegistryLock(context, () => {
  const registryPath = outputRegistryPath(context);
  const priorRegistrySnapshot = pathEntryExistsNoFollow(registryPath)
    ? readStableRegularFileBuffer(registryPath, context.root)
    : null;
  const finalReceiptExists = fs.existsSync(
    workflowFinalGateReceiptPath(context, storyId),
  );
  const lifecycle = effectiveStoryLifecycleProjection(context, story);
  if (lifecycle.terminal && lifecycle.source === "workflow_final_receipt") {
    fail(
      `Story ${storyId} already has a valid terminal lifecycle certification. `
      + "Create a new governed story for later output changes instead of changing the certified run.",
    );
  }
  const artifactType = normalizeArtifactType(requireOption(options, "type"));
  const mode = normalizeOutputMode(requireOption(options, "mode"));
  const templateId = normalizeId(requireOption(options, "template"));
  validateApprovedStoryContractForPhaseOutput(
    context,
    story,
    "output.link",
    [{ artifact_type: artifactType, template_id: templateId, mode }],
    options,
  );
  const registry = readOutputRegistry(context, { create: true, options, action: "output.link" });
  const template = findOutputTemplate(registry, templateId);
  if (!template) {
    fail(`Output template ${templateId} does not exist`);
  }
  if (template.type !== artifactType) {
    fail(`Output template ${templateId} is for '${template.type}', not '${artifactType}'`);
  }
  if (template.status !== "approved") {
    fail(`Output template ${templateId} is '${template.status}'. Approve it before linking output artifacts.`);
  }

  const delivery = effectiveOutputDelivery(template);

  const artifactPath = resolveProjectFilePath(context, requireOption(options, "artifact"), {
    mustExist: true,
    fileOnly: true,
  });
  assertNotDerivedArtifact(context, artifactPath, "Output artifact");
  validateArtifactDeliveryPath(artifactPath, delivery, `Output template ${templateId}`);
  const relativeArtifactPath = toProjectPath(context, artifactPath);
  const id = normalizeId(
    options.id || `OUT-${storyId}-${artifactType}-${shortHash(`${relativeArtifactPath}:${mode}`)}`,
  );
  const existingStoryLink = (registry.links || [])
    .find((link) => link.story_id === storyId && link.id === id);
  if (
    finalReceiptExists
    && (
      !existingStoryLink
      || existingStoryLink.artifact_type !== artifactType
      || existingStoryLink.artifact_path !== relativeArtifactPath
      || existingStoryLink.template_id !== templateId
      || existingStoryLink.mode !== mode
    )
  ) {
    fail(
      `Story ${storyId} already has a terminal lifecycle receipt. `
      + "An invalidated receipt permits only an in-place refresh of the exact existing output link; "
      + "create a new governed story for replacement or additional outputs.",
    );
  }
  let verificationReceipt = verifyOutputArtifact(context, artifactPath, delivery, {
    evidence: outputRenderEvidenceOptions(options),
    requireVisualEvidence: true,
    receiptFile: getOptionString(options, "receipt-file"),
    id: `VERIFY-${id}-${hashFile(artifactPath).slice(0, 8)}`,
    subjectRef: {
      kind: "output_link",
      id,
      hash: shortHashFull(stableJson({
        story_id: storyId,
        artifact_type: artifactType,
        artifact_path: relativeArtifactPath,
        template_id: templateId,
        mode,
      })),
    },
  });
  const verificationFile = verificationReceiptPath(context, verificationReceipt.id);
  let verificationReceiptRef = {
    id: verificationReceipt.id,
    path: toProjectPath(context, verificationFile),
    hash: verificationReceipt.receipt_hash,
  };
  if (fs.existsSync(verificationFile)) {
    const persistedReceipt = readProjectJson(context, verificationFile);
    const persistedIntegrity = validateVerificationReceiptIntegrity(persistedReceipt);
    if (
      !persistedIntegrity.valid ||
      verificationArtifactSha256(persistedReceipt) !== hashFile(artifactPath) ||
      persistedReceipt.subject_ref?.id !== verificationReceipt.subject_ref?.id
    ) {
      fail(`Verification receipt ${verificationReceiptRef.path} already exists but is not valid for this exact output link and artifact.`);
    }
    verificationReceipt = persistedReceipt;
    verificationReceiptRef = {
      id: persistedReceipt.id,
      path: toProjectPath(context, verificationFile),
      hash: persistedReceipt.receipt_hash,
    };
  }

  const baseArtifact = options["base-artifact"]
    ? resolveProjectFilePath(context, options["base-artifact"], { mustExist: true, fileOnly: true })
    : null;
  if (mode === "delta" && !baseArtifact) {
    fail("Mode 'delta' requires --base-artifact.");
  }
  if (baseArtifact) {
    assertNotDerivedArtifact(context, baseArtifact, "Base artifact");
  }

  const requirements = normalizeListOption(options.requirement);
  const storyRequirements = Array.isArray(story.links?.requirements) ? story.links.requirements : [];
  const linkedRequirements = requirements.length > 0 ? requirements : storyRequirements;
  if (story.proposal_ref && linkedRequirements.length === 0) {
    fail(`Proposal-bound story ${storyId} must link its canonical requirement before an output can be accepted.`);
  }
  for (const requirementId of linkedRequirements) {
    const requirement = readRequirement(context, requirementId, { missingOk: true });
    if (!requirement) {
      fail(`Output link references missing requirement ${requirementId}. Create or restore the canonical requirement before linking the artifact.`);
    }
    if (
      story.proposal_ref &&
      (requirement.proposal_ref?.id !== story.proposal_ref.id || requirement.proposal_ref?.hash !== story.proposal_ref.hash)
    ) {
      fail(`Requirement ${requirementId} is not bound to the same immutable proposal as story ${storyId}.`);
    }
  }
  const relativeBaseArtifact = baseArtifact ? toProjectPath(context, baseArtifact) : null;
  const attribution = buildAttribution(context, options, "output.link");
  const decisionId = getOptionString(options, "decision-id");
  const existingDecision = decisionId
    ? (registry.decisions || []).find((decision) => decision.id === normalizeId(decisionId))
    : null;
  if (existingDecision && !hasApprovedOutputDecision(registry.decisions || [], decisionId)) {
    fail(`Decision ${decisionId} already exists but is not an approved output override decision.`);
  }
  if (decisionId && !hasApprovedOutputDecision(registry.decisions || [], decisionId)) {
    if (!["human", "ci"].includes(attribution.actor.type)) {
      fail("Creating an output override decision requires --actor-type human or an approved CI actor.");
    }
    const decisionEvidence = buildApprovalEvidence(context, options);
    const decisionSummary = getOptionString(options, "rationale");
    if (!decisionSummary && decisionEvidence.length === 0) {
      fail("Creating an output override decision requires --rationale or --approval-evidence describing the approved exception.");
    }
    const approvalSource = normalizeApprovalSource(context, options, attribution, `output override ${decisionId}`, "approved");
    validateApprovalSourceForActor(context, {
      source: approvalSource,
      status: "approved",
      summary: decisionSummary,
      evidence: decisionEvidence,
      actor: attribution.actor,
      label: `output override ${decisionId}`,
    });
    const authorization = approvalSource === "automation"
      ? requireAutomationAuthorization(context, options, attribution.action, { label: `output override ${decisionId}`, subject_id: normalizeId(decisionId), artifact_type: artifactType })
      : null;
    const decisionSubject = buildOutputLinkDecisionSubject({
      story_id: storyId,
      artifact_type: artifactType,
      artifact_path: relativeArtifactPath,
      template_id: templateId,
      mode,
      base_artifact: relativeBaseArtifact,
      requirements: linkedRequirements,
      rationale: getOptionString(options, "rationale") || null,
    });
    const decision = {
      id: normalizeId(decisionId),
      type: "output_link_override",
      story_id: storyId,
      artifact_type: artifactType,
      status: "approved",
      summary: decisionSummary,
      subject: decisionSubject,
      evidence: decisionEvidence,
      approval_source: approvalSource,
      authorization_ref: authorization?.id || null,
      authorization_use_ref: authorization?.__use_receipt?.path || null,
      authorization_action: authorization ? attribution.action : null,
      explicit_user_confirmation: approvalSource === "explicit-user",
      provisional: approvalSource === "bootstrap",
      approved_content_hash: hashApprovalSubject(decisionSubject),
      hash_algorithm: "sha256:stable-json:v1",
      created_at: now(),
      audit: {
        decided_by: attribution.actor,
        git: attribution.git,
        run: attribution.run,
      },
    };
    upsertById(registry.decisions, decision);
  }
  const existing = registry.links.find((link) => link.id === id);
  const link = {
    id,
    story_id: storyId,
    artifact_type: artifactType,
    artifact_path: relativeArtifactPath,
    template_id: templateId,
    mode,
    base_artifact: relativeBaseArtifact,
    requirements: linkedRequirements,
    decision_id: decisionId ? normalizeId(decisionId) : null,
    rationale: getOptionString(options, "rationale") || null,
    delivery_format: delivery.format,
    delivery_extension: delivery.extension,
    media_type: delivery.media_type,
    generator: delivery.generator,
    delivery_mode: delivery.mode,
    verification_receipt: verificationReceipt,
    verification_receipt_ref: verificationReceiptRef,
    source_paths: [
      relativeArtifactPath,
      relativeBaseArtifact,
      template.path,
      verificationReceiptRef.path,
      ...verificationReceipt.evidence.map((item) => item.path),
    ].filter(Boolean),
    fingerprints: {
      artifact_sha256: hashFile(artifactPath),
      base_artifact_sha256: baseArtifact ? hashFile(baseArtifact) : null,
      template_sha256: template.path
        ? hashFile(resolveProjectFilePath(context, template.path, { mustExist: true, fileOnly: true }))
        : null,
      hash_algorithm: "sha256:file:v1",
    },
    created_at: existing?.created_at || now(),
    updated_at: now(),
    audit: {
      ...(existing?.audit || {}),
      linked_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
  };

  const duplicateHints = findRelatedOutputLinks(registry, link).filter((related) => related.id !== id);
  if (mode === "new" && duplicateHints.length > 0 && !outputLinkHasMatchingApprovedDecision(registry.decisions || [], link)) {
    const related = duplicateHints.map((item) => `${item.story_id}:${item.artifact_path}`).join(", ");
    fail(
      `Output ${storyId}/${artifactType} duplicates requirements already covered by ${related}. Use --mode delta/reuse or pass an approved --decision-id.`,
    );
  }

  if (story.proposal_ref) {
    const proposal = readAssessmentProposal(context, story.proposal_ref.id);
    if (proposal.proposal_hash !== story.proposal_ref.hash) {
      fail(`Story ${storyId} is bound to a stale assessment proposal hash.`);
    }
    const authorizationId = getOptionString(options, "authorization");
    if (!authorizationId) {
      fail([
        `Output link ${id} is part of proposal ${proposal.id} and requires --authorization <id>.`,
        "What I need: the content authorization created when you approved checkpoint 2.",
        "Why: linking the canonical artifact is a write from the approved tranche and must leave a historical authorization-use receipt.",
        `Example: agentic-sdlc output link --story ${storyId} --type ${artifactType} --artifact ${relativeArtifactPath} --template ${templateId} --mode ${mode} --authorization AUTH-${proposal.id}-${proposal.proposal_hash.slice(0, 8)}.`,
        "Effect: only this exact proposal/story/artifact-type link is consumed; no additional scope or budget is granted.",
      ].join("\n"));
    }
    const authorization = readAuthorization(context, normalizeId(authorizationId));
    const proposalRef = {
      id: proposal.id,
      path: toProjectPath(context, assessmentProposalPath(context, proposal.id)),
      hash: proposal.proposal_hash,
    };
    const authorizationSettings = {
      proposal_ref: proposalRef,
      subject_id: storyId,
      artifact_types: [artifactType],
    };
    const authorizationErrors = authorizationUseErrors(authorization, "output.link", authorizationSettings);
    if (authorizationErrors.length > 0) {
      fail(authorizationErrors[0]);
    }
    const authorizationUse = recordOrReuseAuthorizationUse(
      context,
      authorization,
      "output.link",
      authorizationSettings,
    );
    link.authorization_ref = authorization.id;
    link.authorization_use_ref = authorizationUse.path;
    link.authorization_action = "output.link";
    link.source_paths = Array.from(new Set([...link.source_paths, authorizationUse.path]));
  }
  const checkpointPolicy = storyActionCheckpointPolicy(
    context,
    storyId,
    "output.link",
  );
  const checkpoint = story.proposal_ref && link.authorization_ref
    ? (
        checkpointPolicy.required
          ? {
              authorization_ref: link.authorization_ref,
              authorization_use_ref: link.authorization_use_ref,
              authorization_action: link.authorization_action,
              checkpoint_profile_ref: checkpointPolicy.profile_ref,
            }
          : null
      )
    : consumeStoryActionCheckpoint(
        context,
        storyId,
        "output.link",
        options,
        { artifact_types: [artifactType] },
      );
  if (checkpoint) {
    link.authorization_ref = checkpoint.authorization_ref;
    link.authorization_use_ref = checkpoint.authorization_use_ref;
    link.authorization_action = checkpoint.authorization_action;
    link.checkpoint_profile_ref = checkpoint.checkpoint_profile_ref;
    link.source_paths = Array.from(new Set([
      ...link.source_paths,
      checkpoint.authorization_use_ref,
      checkpoint.checkpoint_profile_ref?.path,
    ].filter(Boolean)));
  }

  const priorVerificationSnapshot = pathEntryExistsNoFollow(verificationFile)
    ? readStableRegularFileBuffer(verificationFile, context.root)
    : null;
  const verificationDirectory = path.dirname(verificationFile);
  const verificationDirectoryExisted = pathEntryExistsNoFollow(verificationDirectory);
  let verificationWritten = false;
  let registryWritten = false;
  let traceMutation;
  let traceEvent;
  try {
    ensureDir(verificationDirectory);
    if (pathEntryExistsNoFollow(verificationFile)) {
      const existingReceipt = readProjectJson(context, verificationFile);
      if (existingReceipt.receipt_hash !== verificationReceipt.receipt_hash) {
        fail(`Verification receipt ${verificationReceiptRef.path} already exists with different immutable content.`);
      }
    } else {
      writeJsonFile(verificationFile, verificationReceipt);
      verificationWritten = true;
    }

    upsertById(registry.links, link);
    registry.updated_at = now();
    registry.audit = {
      ...(registry.audit || {}),
      updated_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    };
    writeOutputRegistry(context, registry);
    registryWritten = true;
    traceMutation = prepareGovernedTraceMutation(context, storyId, {
      type: "decision",
      summary: `Linked ${artifactType} output ${relativeArtifactPath} as ${mode}`,
      action: "output.link",
      actor: attribution.actor,
      evidence: [
        relativeArtifactPath,
        toProjectPath(context, registryPath),
        link.authorization_use_ref,
        link.checkpoint_profile_ref?.path,
      ].filter(Boolean),
      related: [storyId, artifactType, templateId, id],
      git: attribution.git,
      run: attribution.run,
    });
    try {
      traceEvent = traceMutation.commit();
    } catch (error) {
      traceEvent = traceMutation.recoverCommitted();
      if (!traceEvent) throw error;
    }
  } catch (error) {
    if (!traceEvent) {
      const rollbackFailures = [];
      const restore = (label, filePath, snapshot, written) => {
        if (!written) return;
        try {
          if (snapshot) {
            writeTextFile(filePath, snapshot.content.toString("utf8"), { force: true });
          } else if (pathEntryExistsNoFollow(filePath)) {
            removePathGoverned(filePath, { force: true });
          }
        } catch (rollbackError) {
          rollbackFailures.push(`${label}: ${rollbackError.message}`);
        }
      };
      restore("output registry", registryPath, priorRegistrySnapshot, registryWritten);
      restore(
        "output verification receipt",
        verificationFile,
        priorVerificationSnapshot,
        verificationWritten,
      );
      if (
        !verificationDirectoryExisted
        && pathEntryExistsNoFollow(verificationDirectory)
        && fs.readdirSync(verificationDirectory).length === 0
      ) {
        try {
          removeEmptyDirectoryGoverned(verificationDirectory);
        } catch (rollbackError) {
          rollbackFailures.push(`output verification directory: ${rollbackError.message}`);
        }
      }
      if (rollbackFailures.length > 0) {
        fail(
          `Output link ${id} transaction could not restore exact prior state `
          + `(${rollbackFailures.join("; ")}). Original failure: ${error.message}`,
        );
      }
    }
    throw error;
  } finally {
    traceMutation?.release();
  }

  output(
    options,
    { status: "linked", link, related_outputs: duplicateHints, trace_event: traceEvent },
    [
      `Linked ${artifactType} output for ${storyId} as ${mode}`,
      duplicateHints.length > 0
        ? `Related outputs found: ${duplicateHints.map((item) => `${item.story_id}:${item.artifact_path}`).join(", ")}`
        : "No related outputs found",
    ],
  );
    });
  } finally {
    releaseLifecycleLock();
    releaseTaskStartBoundaryLock();
  }
}

function showOutputStatus(context, options) {
  ensureInitialized(context);
  const storyId = normalizeId(requireOption(options, "story"));
  const story = readStory(context, storyId);
  if (!story) {
    fail(`Story ${storyId} does not exist`);
  }
  const registry = readOutputRegistry(context, { missingOk: true });
  const types = outputStatusTypes(context, registry, { ...options, story });
  const links = registry ? registry.links.filter((link) => link.story_id === storyId) : [];
  const resolutions = types.map((type) => buildOutputResolution(context, storyId, type, { registry }));

  output(
    options,
    { story_id: storyId, links, resolutions },
    [
      `Output status for ${storyId}`,
      ...links.map((link) => `${link.artifact_type}: ${link.mode} ${link.artifact_path} (${link.template_id})`),
      ...resolutions.map((resolution) => `${resolution.artifact_type}: ${resolution.recommendation}`),
    ],
  );
}

function rebuildCache(context, options) {
  ensureInitialized(context);
  const cache = buildCache(context);
  const cachePath = path.join(context.sdlcRoot, "cache", CACHE_FILE_NAME);
  assertRecordSchema(cache, "cache.schema.json", "Local SDLC cache");
  writeJsonFile(cachePath, cache, { force: true });
  output(
    options,
    { status: "rebuilt", cache_path: cachePath, entries: cache.full_text_index.length },
    [`Rebuilt local SDLC cache with ${cache.full_text_index.length} indexed entries`],
  );
}

function showCacheStatus(context, options) {
  ensureInitialized(context);
  const status = getCacheStatus(context);
  output(
    options,
    options.full ? status : buildCompactCacheStatus(status),
    [
      status.exists ? `Cache: ${status.valid ? "valid" : "stale"}` : "Cache: missing",
      `Path: ${status.cache_path}`,
      `Changed: ${status.changed.length}`,
      `Missing: ${status.missing.length}`,
      `Added: ${status.added.length}`,
      status.valid ? "No rebuild required" : "Run: agentic-sdlc cache rebuild",
    ],
  );
}

function clearCache(context, options) {
  ensureInitialized(context);
  const cacheRoot = resolveProjectFilePath(context, path.join(SDLC_DIR, "cache"), { mustExist: false });
  assertNoSymlinkPathSegments(cacheRoot, context.root);
  removePathGoverned(cacheRoot, { recursive: true, force: true });
  ensureDir(cacheRoot);
  output(options, { status: "cleared", cache_root: cacheRoot }, [`Cleared local SDLC cache at ${cacheRoot}`]);
}

function reportActivity(context, options) {
  ensureInitialized(context);
  const report = buildActivityReport(context, options);
  if (options.out) {
    writeActivityReport(context, report, options);
  }
  output(
    options,
    report,
    [
      `Activity report (${report.view})`,
      `Window: ${report.window.since} -> ${report.window.until}`,
      `Events: ${report.summary.event_count}`,
      ...report.items.map((item) => `- ${item.created_at || "unknown"} ${item.story_id || "project"} ${item.action}: ${item.summary}`),
      report.items.length === 0 ? "- No canonical trace events in this window" : null,
    ].filter(Boolean),
  );
}

function reportQuery(context, options) {
  ensureInitialized(context);
  const queryLoad = loadReportQuery(context, options);
  if (!queryLoad.query) {
    const guidance = buildReportQueryNormalizationGuidance(options, queryLoad);
    output(options, guidance, [
      "Report query needs canonical normalization.",
      "Pass --query-json or --query-file with a report query object.",
      "Raw natural language is recorded only as context and is not keyword-matched by the CLI.",
    ]);
    return;
  }
  const report = buildReportQueryResult(context, queryLoad.query, options);
  if (options.out) {
    writeReportQueryResult(context, report, options);
  }
  output(
    options,
    report,
    [
      `Report query: ${report.status}`,
      `Matched: ${report.summary.result_count}`,
      ...report.results.map((item) => `- ${item.created_at || item.updated_at || "unknown"} ${item.kind} ${item.id}: ${item.summary}`),
      report.results.length === 0 ? "- No canonical KB records matched this query" : null,
    ].filter(Boolean),
  );
}

function loadReportQuery(context, options = {}) {
  const json = getOptionString(options, "query-json");
  const file = getOptionString(options, "query-file");
  if (json && file) {
    fail("Use either --query-json or --query-file, not both.");
  }
  if (json) {
    return { source: "query-json", query: loadOptionalJsonInput(context, options, "query-json", "query-file", "Report query") };
  }
  if (file) {
    const queryPath = resolveProjectFilePath(context, file, { mustExist: true, fileOnly: true });
    assertNotDerivedArtifact(context, queryPath, "Report query file");
    return { source: toProjectPath(context, queryPath), query: readProjectJson(context, queryPath) };
  }
  return { source: "missing", query: null, raw_text: getOptionString(options, "text", "query") || null };
}

function buildReportQueryNormalizationGuidance(options, queryLoad) {
  return {
    kind: "report_query_normalization",
    status: "needs_normalization",
    schema_version: "report-query:v1",
    raw_text: queryLoad.raw_text,
    rule: "Codex or another LLM must normalize natural language into canonical query JSON. The CLI never keyword-matches raw user language.",
    required_shape: {
      intent: "find_records",
      confidence: 0.0,
      subjects: ["activity"],
      time: { since: "10d", until: "now", field: "created_at" },
      filters: {
        actor: ["actor-id-or-email"],
        executor: ["agent-or-human-who-ran-the-action"],
        requester: ["human-or-system-who-requested-the-action"],
        authorizer: ["human-or-ci-who-authorized-the-action"],
        story_id: ["ST-001"],
        artifact_type: ["functional-analysis"],
        event_type: ["decision"],
        action: ["story.create"],
        phase: ["analysis"],
        status: ["draft"],
        requirement: ["REQ-001"],
        text: ["search term"],
      },
      sort: "created_at_desc",
      limit: 50,
    },
    examples: [
      {
        natural_language: "all changes made by me",
        query: {
          intent: "find_changes",
          confidence: 0.9,
          subjects: ["activity", "stories", "outputs", "contracts", "approvals"],
          filters: { requester: ["<current-user-id-or-email>"] },
          sort: "created_at_desc",
        },
      },
      {
        natural_language: "all new functional stories from the last 10 days",
        query: {
          intent: "find_new_functional_stories",
          confidence: 0.9,
          subjects: ["stories"],
          time: { since: "10d", until: "now", field: "created_at" },
          filters: { artifact_type: ["functional-analysis"], text: ["functional"] },
          sort: "created_at_desc",
        },
      },
    ],
  };
}

function buildReportQueryResult(context, rawQuery, options = {}) {
  const query = normalizeReportQuery(rawQuery, options);
  const session = openProjectQuerySession(context);
  const allRecords = collectReportQueryRecords(context, session);
  const filtered = allRecords
    .filter((record) => reportQuerySubjectMatches(record, query))
    .filter((record) => reportQueryTimeMatches(record, query))
    .filter((record) => reportQueryFiltersMatch(record, query))
    .sort((left, right) => compareReportQueryRecords(left, right, query.sort))
    .slice(0, query.limit)
    .map(formatReportQueryRecord);
  const sourcePaths = Array.from(
    new Set(filtered.flatMap((record) => (record.sources || []).map((source) => source.path).filter(Boolean))),
  ).sort();
  return {
    kind: "report_query_result",
    status: "matched",
    schema_version: context.config.schema_version,
    generated_at: now(),
    query,
    summary: {
      result_count: filtered.length,
      by_kind: countBy(filtered, "kind"),
      by_actor: countBy(filtered, (record) => traceActorKey(record.actor)),
      by_requester: countBy(
        filtered.filter((record) => record.requested_by),
        (record) => traceActorKey(record.requested_by),
      ),
      by_authorizer: countBy(
        filtered.filter((record) => record.authorized_by),
        (record) => traceActorKey(record.authorized_by),
      ),
      by_story: countBy(filtered, (record) => record.story_id || "project"),
    },
    results: filtered,
    source_paths: sourcePaths,
    source_hashes: buildSourceHashMap(context, sourcePaths, session),
    source_policy: "Query results cite canonical .sdlc files. Cache and indexes are never query evidence.",
  };
}

function normalizeReportQuery(rawQuery, options = {}) {
  if (!rawQuery || typeof rawQuery !== "object" || Array.isArray(rawQuery)) {
    fail("Report query must be a JSON object.");
  }
  const subjects = normalizeStringArray(rawQuery.subjects || rawQuery.subject || ["activity"]).map((subject) =>
    String(subject).trim().toLowerCase(),
  );
  if (subjects.length === 0) {
    fail("Report query subjects cannot be empty.");
  }
  for (const subject of subjects) {
    if (!REPORT_QUERY_SUBJECTS.has(subject)) {
      fail(`Unknown report query subject '${subject}'. Valid subjects: ${Array.from(REPORT_QUERY_SUBJECTS).join(", ")}`);
    }
  }
  const time = rawQuery.time && typeof rawQuery.time === "object" && !Array.isArray(rawQuery.time) ? rawQuery.time : {};
  const filters = rawQuery.filters && typeof rawQuery.filters === "object" && !Array.isArray(rawQuery.filters) ? rawQuery.filters : {};
  const limit = boundedPositiveInteger(rawQuery.limit ?? options.limit, "limit", {
    defaultValue: 50,
    maximum: 500,
  });
  const sort = String(rawQuery.sort || "created_at_desc");
  if (!["created_at_desc", "created_at_asc", "updated_at_desc", "updated_at_asc", "kind_asc"].includes(sort)) {
    fail("Report query sort must be created_at_desc, created_at_asc, updated_at_desc, updated_at_asc, or kind_asc.");
  }
  return {
    intent: String(rawQuery.intent || "find_records"),
    confidence: rawQuery.confidence === undefined ? null : Number(rawQuery.confidence),
    subjects,
    time: {
      since: time.since || options.since || null,
      until: time.until || options.until || null,
      field: String(time.field || "created_at"),
    },
    filters: normalizeReportQueryFilters(filters),
    sort,
    limit,
  };
}

function normalizeReportQueryFilters(filters) {
  return {
    actor: normalizeStringArray(filters.actor),
    executor: normalizeStringArray(filters.executor || filters.executed_by),
    requester: normalizeStringArray(filters.requester || filters.requested_by || filters.requestedBy),
    authorizer: normalizeStringArray(filters.authorizer || filters.authorized_by || filters.authorizedBy),
    story_id: normalizeStringArray(filters.story_id || filters.story),
    requirement: normalizeStringArray(filters.requirement || filters.requirements),
    artifact_type: normalizeStringArray(filters.artifact_type || filters.output_type),
    event_type: normalizeStringArray(filters.event_type || filters.type),
    action: normalizeStringArray(filters.action),
    phase: normalizeStringArray(filters.phase),
    status: normalizeStringArray(filters.status),
    kind: normalizeStringArray(filters.kind),
    path: normalizeStringArray(filters.path),
    text: normalizeStringArray(filters.text || filters.contains),
  };
}

function collectReportQueryRecords(context, session = openProjectQuerySession(context)) {
  const registry = readOutputRegistry(context, { missingOk: true });
  const registryIndex = createOutputRegistryQueryIndex(registry);
  const stories = readAllStories(context, session);
  return [
    ...collectTraceQueryRecords(context, session),
    ...collectStoryQueryRecords(context, registry, registryIndex, stories),
    ...collectStoryStepQueryRecords(context, stories, session),
    ...collectOutputQueryRecords(context, registry),
    ...collectContractQueryRecords(context, session),
    ...collectHandoffQueryRecords(context),
    ...collectWorkItemQueryRecords(context, session),
    ...collectApprovalQueryRecords(context, session),
    ...collectTestQueryRecords(context, session),
  ];
}

function collectTraceQueryRecords(context, session = null) {
  return readAllTraceEvents(context, { session })
    .filter((event) => event.type !== "invalid")
    .map((event) => ({
      kind: "activity",
      id: event.id || `${event.source?.path}:${event.source?.line}`,
      summary: event.summary || event.action || event.type,
      created_at: event.created_at || null,
      updated_at: event.created_at || null,
      actor: event.actor || null,
      requested_by: event.requested_by || null,
      authorized_by: event.authorized_by || null,
      request: event.request || null,
      action: event.action || event.type || null,
      event_type: event.type || null,
      story_id: event.story_id || null,
      artifact_type: inferArtifactTypeFromTrace(event),
      requirements: [],
      phase: null,
      status: null,
      text: stableJson(event),
      sources: [event.source].filter(Boolean),
      raw: event,
    }));
}

function collectStoryQueryRecords(context, registry = null, registryIndex = null, stories = null) {
  return (stories || readAllStories(context)).map((story) => {
    const storyLinks = registryIndex
      ? registryIndex.links_by_story.get(story.id) || []
      : (registry?.links || []).filter((link) => link.story_id === story.id);
    const storyOutputTypes = storyLinks
      .filter((link) => link.artifact_type)
      .map((link) => link.artifact_type);
    return {
      kind: "stories",
      id: story.id,
      summary: story.title || story.id,
      created_at: story.created_at || null,
      updated_at: story.updated_at || story.created_at || null,
      actor: story.audit?.created_by || story.audit?.updated_by || null,
      requested_by: null,
      authorized_by: null,
      request: null,
      action: "story.create",
      event_type: "story",
      story_id: story.id,
      artifact_type: storyOutputTypes[0] || inferStoryArtifactType(story),
      artifact_types: storyOutputTypes,
      requirements: Array.isArray(story.links?.requirements) ? story.links.requirements : [],
      phase: story.phase || null,
      status: story.status || null,
      text: stableJson(story),
      sources: [{ path: `.sdlc/stories/${story.id}/story.json`, line: 1 }],
      raw: story,
    };
  });
}

function collectStoryStepQueryRecords(context, stories = null, session = null) {
  const records = [];
  for (const story of stories || readAllStories(context)) {
    for (const step of readStoryStepRecords(context, story.id, session)) {
      records.push({
        kind: "story_steps",
        id: step.id || `${story.id}:${step.step}`,
        summary: step.summary || `${story.id} ${step.step} completed`,
        created_at: step.completed_at || null,
        updated_at: step.completed_at || null,
        actor: step.audit?.completed_by || null,
        requested_by: null,
        authorized_by: null,
        request: null,
        action: "story.complete-step",
        event_type: "gate",
        story_id: story.id,
        artifact_type: Array.isArray(step.output_types) ? step.output_types[0] || null : null,
        artifact_types: Array.isArray(step.output_types) ? step.output_types : [],
        requirements: Array.isArray(story.links?.requirements) ? story.links.requirements : [],
        phase: step.phase || story.phase || null,
        status: step.status || null,
        text: stableJson(step),
        sources: [{ path: `.sdlc/stories/${story.id}/steps/${step.step}.json`, line: 1 }],
        raw: step,
      });
    }
  }
  return records;
}

function collectOutputQueryRecords(context, registry = null) {
  const registrySource = fs.existsSync(outputRegistryPath(context)) ? [{ path: toProjectPath(context, outputRegistryPath(context)), line: 1 }] : [];
  const templateRecords = (registry?.templates || []).map((template) => ({
    kind: "outputs",
    id: template.id,
    summary: `Output template ${template.id} for ${template.type}`,
    created_at: template.proposed_at || template.created_at || null,
    updated_at: template.approved_at || template.proposed_at || null,
    actor: template.audit?.approved_by || template.audit?.proposed_by || template.approved_by || null,
    requested_by: null,
    authorized_by: null,
    request: null,
    action: template.status === "approved" ? "output.template.approve" : "output.template.propose",
    event_type: "decision",
    story_id: null,
    artifact_type: template.type || null,
    requirements: [],
    phase: null,
    status: template.status || null,
    text: stableJson(template),
    sources: registrySource,
    raw: template,
  }));
  const linkRecords = (registry?.links || []).map((link) => ({
    kind: "outputs",
    id: link.id,
    summary: `${link.artifact_type} output ${link.artifact_path} linked as ${link.mode}`,
    created_at: link.created_at || null,
    updated_at: link.updated_at || link.created_at || null,
    actor: link.audit?.linked_by || null,
    requested_by: null,
    authorized_by: null,
    request: null,
    action: "output.link",
    event_type: "decision",
    story_id: link.story_id || null,
    artifact_type: link.artifact_type || null,
    requirements: Array.isArray(link.requirements) ? link.requirements : [],
    phase: null,
    status: link.mode || null,
    text: stableJson(link),
    sources: registrySource,
    raw: link,
  }));
  return [...templateRecords, ...linkRecords];
}

function collectContractQueryRecords(context, session = null) {
  return collectJsonFiles(context, path.join(context.sdlcRoot, "contracts"), session).map((contract) => ({
    kind: "contracts",
    id: contract.id || path.basename(contract.__path, ".json"),
    summary: `${contract.phase || "unknown"} contract ${contract.id || path.basename(contract.__path, ".json")}`,
    created_at: contract.created_at || null,
    updated_at: contract.updated_at || contract.created_at || null,
    actor: contract.audit?.created_by || contract.audit?.updated_by || null,
    requested_by: null,
    authorized_by: null,
    request: null,
    action: "contract.create",
    event_type: "contract",
    story_id: contract.story_id || null,
    artifact_type: Array.isArray(contract.output_contract_refs) ? contract.output_contract_refs[0]?.artifact_type || null : null,
    artifact_types: Array.isArray(contract.output_contract_refs) ? contract.output_contract_refs.map((ref) => ref.artifact_type).filter(Boolean) : [],
    requirements: [],
    phase: contract.phase || null,
    status: contract.status || null,
    text: stableJson(contract),
    sources: [{ path: contract.__relative_path, line: 1 }],
    raw: contract,
  }));
}

function collectHandoffQueryRecords(context) {
  return readHandoffs(context).map((handoff) => ({
    kind: "handoffs",
    id: handoff.id,
    summary: handoff.summary || `Handoff ${handoff.id} to ${handoff.to_agent}`,
    created_at: handoff.created_at || null,
    updated_at: handoff.closed_at || handoff.created_at || null,
    actor: handoff.from_actor || handoff.audit?.created_by || null,
    requested_by: null,
    authorized_by: null,
    request: null,
    action: handoff.closed_at ? "handoff.close" : "story.handoff",
    event_type: "handoff",
    story_id: handoff.story_id || null,
    artifact_type: null,
    requirements: [],
    phase: null,
    status: handoff.status || null,
    text: stableJson(handoff),
    sources: [{ path: `.sdlc/handoffs/${handoff.id}.json`, line: 1 }],
    raw: handoff,
  }));
}

function collectWorkItemQueryRecords(context, session = null) {
  const roots = [path.join(workItemsRoot(context), "epics"), path.join(workItemsRoot(context), "tasks")];
  return roots.flatMap((root) =>
    collectJsonFiles(context, root, session).map((item) => ({
      kind: "work_items",
      id: item.id || path.basename(item.__path, ".json"),
      summary: item.title || item.summary || item.id || path.basename(item.__path, ".json"),
      created_at: item.created_at || null,
      updated_at: item.updated_at || item.created_at || null,
      actor: item.audit?.created_by || item.audit?.updated_by || null,
      requested_by: null,
      authorized_by: null,
      request: null,
      action: "work.item.create",
      event_type: "work_item",
      story_id: item.story_id || item.story || null,
      artifact_type: null,
      requirements: item.requirement_id ? [item.requirement_id] : normalizeStringArray(item.requirements),
      phase: null,
      status: item.status || null,
      text: stableJson(item),
      sources: [{ path: item.__relative_path, line: 1 }],
      raw: item,
    })),
  );
}

function collectApprovalQueryRecords(context, session = null) {
  return collectApprovalManifestEntries(context, session).map((approval) => ({
    kind: "approvals",
    id: approval.approval_id || `${approval.subject_id}:approval`,
    summary: `${approval.subject_id} approval ${approval.status || "unknown"}`,
    created_at: approval.created_at || null,
    updated_at: approval.created_at || null,
    actor: approval.actor || null,
    requested_by: null,
    authorized_by: null,
    request: null,
    action: "approve",
    event_type: "gate",
    story_id: null,
    artifact_type: null,
    requirements: [],
    phase: null,
    status: approval.status || null,
    text: stableJson(approval),
    sources: [{ path: approval.subject_path, line: 1 }],
    raw: approval,
  }));
}

function collectTestQueryRecords(context, session = null) {
  return collectJsonFiles(context, path.join(context.sdlcRoot, "tests"), session).map((testRecord) => ({
    kind: "tests",
    id: testRecord.id || path.basename(testRecord.__path, ".json"),
    summary: testRecord.summary || testRecord.id || path.basename(testRecord.__path, ".json"),
    created_at: testRecord.created_at || null,
    updated_at: testRecord.updated_at || testRecord.created_at || null,
    actor: testRecord.audit?.created_by || testRecord.audit?.updated_by || null,
    requested_by: null,
    authorized_by: null,
    request: null,
    action: "test.evidence",
    event_type: "test",
    story_id: testRecord.story_id || null,
    artifact_type: null,
    requirements: normalizeStringArray(testRecord.requirements),
    phase: "validation",
    status: testRecord.status || null,
    text: stableJson(testRecord),
    sources: [{ path: testRecord.__relative_path, line: 1 }],
    raw: testRecord,
  }));
}

function inferArtifactTypeFromTrace(event) {
  if (event.action === "output.link" && Array.isArray(event.related)) {
    return event.related.find((item) => String(item).includes("-analysis") || String(item).includes("summary")) || null;
  }
  return null;
}

function inferStoryArtifactType(story) {
  const text = stableJson(story).toLowerCase();
  if (text.includes("functional-analysis") || text.includes("functional")) {
    return "functional-analysis";
  }
  if (text.includes("technical-analysis") || text.includes("technical")) {
    return "technical-analysis";
  }
  return null;
}

function reportQuerySubjectMatches(record, query) {
  return query.subjects.includes("all") || query.subjects.includes(record.kind);
}

function reportQueryTimeMatches(record, query) {
  if (!query.time.since && !query.time.until) {
    return true;
  }
  const fields = query.time.field === "updated_at" ? ["updated_at"] : query.time.field === "any" ? ["created_at", "updated_at"] : ["created_at"];
  const timestamps = fields.map((field) => Date.parse(String(record[field] || ""))).filter(Number.isFinite);
  if (timestamps.length === 0) {
    return false;
  }
  const since = query.time.since ? parseDateBoundary(query.time.since, "query.time.since") : null;
  const until = query.time.until ? parseDateBoundary(query.time.until, "query.time.until", { defaultNow: true }) : null;
  return timestamps.some((timestamp) => (!since || timestamp >= since.getTime()) && (!until || timestamp <= until.getTime()));
}

function reportQueryFiltersMatch(record, query) {
  const filters = query.filters;
  return (
    listFilterMatches(filters.kind, record.kind) &&
    actorFilterMatches(filters.actor, record.actor) &&
    actorFilterMatches(filters.executor, record.actor) &&
    actorFilterMatches(filters.requester, record.requested_by) &&
    actorFilterMatches(filters.authorizer, record.authorized_by) &&
    listFilterMatches(filters.story_id, record.story_id) &&
    listFilterOverlaps(filters.requirement, record.requirements || []) &&
    listFilterOverlaps(filters.artifact_type, [record.artifact_type, ...(record.artifact_types || [])].filter(Boolean)) &&
    listFilterMatches(filters.event_type, record.event_type) &&
    listFilterMatches(filters.action, record.action) &&
    listFilterMatches(filters.phase, record.phase) &&
    listFilterMatches(filters.status, record.status) &&
    listFilterOverlaps(filters.path, (record.sources || []).map((source) => source.path)) &&
    textFilterMatches(filters.text, record.text)
  );
}

function actorFilterMatches(filters, actor) {
  if (!filters.length) {
    return true;
  }
  return filters.some((filter) => traceActorMatches(actor, filter));
}

function listFilterMatches(filters, value) {
  if (!filters.length) {
    return true;
  }
  return filters.map(normalizeQueryToken).includes(normalizeQueryToken(value));
}

function listFilterOverlaps(filters, values) {
  if (!filters.length) {
    return true;
  }
  const normalizedValues = new Set((Array.isArray(values) ? values : [values]).map(normalizeQueryToken));
  return filters.some((filter) => normalizedValues.has(normalizeQueryToken(filter)));
}

function textFilterMatches(filters, text) {
  if (!filters.length) {
    return true;
  }
  const normalized = normalizeText(text).toLowerCase();
  return filters.every((filter) => normalizeText(filter).toLowerCase().split(" ").filter(Boolean).every((term) => normalized.includes(term)));
}

function normalizeQueryToken(value) {
  return String(value || "").trim().toLowerCase();
}

function compareReportQueryRecords(left, right, sort) {
  if (sort === "kind_asc") {
    return `${left.kind}:${left.id}`.localeCompare(`${right.kind}:${right.id}`);
  }
  const field = sort.startsWith("updated_at") ? "updated_at" : "created_at";
  const direction = sort.endsWith("_asc") ? 1 : -1;
  return direction * String(left[field] || "").localeCompare(String(right[field] || ""));
}

function formatReportQueryRecord(record) {
  return {
    kind: record.kind,
    id: record.id,
    summary: record.summary,
    created_at: record.created_at,
    updated_at: record.updated_at,
    actor: record.actor,
    action: record.action,
    event_type: record.event_type,
    story_id: record.story_id,
    artifact_type: record.artifact_type,
    artifact_types: record.artifact_types || [],
    requirements: record.requirements || [],
    phase: record.phase,
    status: record.status,
    requested_by: record.requested_by || null,
    authorized_by: record.authorized_by || null,
    request: record.request || null,
    sources: record.sources || [],
  };
}

function countBy(items, keyOrFn) {
  const result = {};
  for (const item of items) {
    const key = typeof keyOrFn === "function" ? keyOrFn(item) : item[keyOrFn];
    result[key || "unknown"] = (result[key || "unknown"] || 0) + 1;
  }
  return result;
}

function writeReportQueryResult(context, report, options) {
  const reportPath = resolveProjectFilePath(context, options.out, { mustExist: false });
  assertNotDerivedArtifact(context, reportPath, "Report query result");
  if (path.extname(reportPath).toLowerCase() === ".md") {
    writeTextFile(reportPath, renderReportQueryMarkdown(report), { force: Boolean(options.force) });
    return;
  }
  writeJsonFile(reportPath, report, { force: Boolean(options.force) });
}

function renderReportQueryMarkdown(report) {
  return [
    "# SDLC Query Report",
    "",
    `- Intent: ${report.query.intent}`,
    `- Subjects: ${report.query.subjects.join(", ")}`,
    `- Results: ${report.summary.result_count}`,
    "",
    "## Results",
    ...(report.results.length
      ? report.results.map((item) => {
          const source = item.sources?.[0] ? ` (${item.sources[0].path}:${item.sources[0].line})` : "";
          return `- ${item.created_at || item.updated_at || "unknown"} ${item.kind} ${item.id}: ${item.summary}${source}`;
        })
      : ["- No canonical KB records matched this query"]),
    "",
    "## Sources",
    ...(report.source_paths.length ? report.source_paths.map((sourcePath) => `- ${sourcePath}`) : ["- None"]),
    "",
  ].join("\n");
}

function buildActivityReport(context, options = {}) {
  const session = openProjectQuerySession(context);
  const view = normalizeActivityReportView(options.view || "business");
  const untilDate = parseDateBoundary(options.until || "now", "until", { defaultNow: true });
  const sinceDate = parseDateBoundary(options.since || "3d", "since", { relativeTo: untilDate });
  if (sinceDate.getTime() > untilDate.getTime()) {
    fail("--since must be before --until");
  }
  const storyFilter = options.story ? normalizeId(options.story) : null;
  const actorFilter = getOptionString(options, "actor") || null;
  const allEvents = readAllTraceEvents(context, { story: storyFilter, session });
  const filteredEvents = allEvents
    .filter((event) => event.type !== "invalid")
    .filter((event) => isEventInsideWindow(event, sinceDate, untilDate))
    .filter((event) => !actorFilter || traceActorMatches(event.actor, actorFilter))
    .sort((a, b) => String(a.created_at || "").localeCompare(String(b.created_at || "")));
  const items = filteredEvents.map((event) => formatActivityEventForView(event, view));
  const summary = summarizeActivityEvents(filteredEvents);
  const sourcePaths = Array.from(new Set(filteredEvents.map((event) => event.source?.path).filter(Boolean))).sort();
  return {
    kind: "activity_report",
    schema_version: context.config.schema_version,
    generated_at: now(),
    view,
    window: {
      since: sinceDate.toISOString(),
      until: untilDate.toISOString(),
    },
    filters: {
      story_id: storyFilter,
      actor: actorFilter,
    },
    summary,
    items,
    parse_errors: allEvents.filter((event) => event.type === "invalid").map((event) => event.source),
    source_paths: sourcePaths,
    source_hashes: buildSourceHashMap(context, sourcePaths, session),
    source_policy: "Only canonical .sdlc trace files are summarized; cache and indexes are not cited as evidence.",
  };
}

function normalizeActivityReportView(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (!ACTIVITY_REPORT_VIEWS.has(normalized)) {
    fail(`Unknown activity report view '${value}'. Valid values: ${Array.from(ACTIVITY_REPORT_VIEWS).join(", ")}`);
  }
  return normalized;
}

function readAllTraceEvents(context, options = {}) {
  const tracesRoot = path.join(context.sdlcRoot, "traces");
  const storyFilter = options.story ? normalizeId(options.story) : null;
  if (options.session) {
    return options.session.traceEvents({ storyId: storyFilter, includeInvalid: true }).map((event) => {
      if (event.type === "invalid") {
        return {
          type: "invalid",
          summary: event.error?.message || "Invalid canonical trace event",
          source: event.source,
        };
      }
      const sourceFile = event.source?.path
        ? path.basename(event.source.path.replaceAll("/", path.sep))
        : null;
      return {
        ...event,
        story_id: event.story_id || (sourceFile ? inferStoryIdFromTraceFile(sourceFile) : null),
      };
    });
  }
  const files = walkFiles(tracesRoot)
    .filter((filePath) => filePath.endsWith(".jsonl"))
    .filter((filePath) => !storyFilter || path.basename(filePath) === `${storyFilter}.jsonl`);
  const events = [];
  for (const filePath of files) {
    const sourcePath = toProjectPath(context, filePath);
    const lines = fs.readFileSync(filePath, "utf8").split(/\r?\n/);
    lines.forEach((line, index) => {
      if (!line.trim()) {
        return;
      }
      try {
        const event = JSON.parse(line);
        events.push({
          ...event,
          story_id: event.story_id || inferStoryIdFromTraceFile(filePath),
          source: { path: sourcePath, line: index + 1 },
        });
      } catch (error) {
        events.push({
          type: "invalid",
          summary: error.message,
          source: { path: sourcePath, line: index + 1 },
        });
      }
    });
  }
  return events;
}

function inferStoryIdFromTraceFile(filePath) {
  const base = path.basename(filePath, ".jsonl");
  return base === "project" ? null : base;
}

function isEventInsideWindow(event, sinceDate, untilDate) {
  const timestamp = Date.parse(String(event.created_at || ""));
  return Number.isFinite(timestamp) && timestamp >= sinceDate.getTime() && timestamp <= untilDate.getTime();
}

function traceActorMatches(actor, filter) {
  if (!filter) {
    return true;
  }
  if (typeof actor === "string") {
    return actor === filter;
  }
  return [actor?.id, actor?.name, actor?.email, actor?.type].filter(Boolean).some((value) => String(value) === filter);
}

function formatActivityEventForView(event, view) {
  const base = {
    created_at: event.created_at || null,
    story_id: event.story_id || null,
    type: event.type || null,
    action: event.action || event.type || null,
    summary: event.summary || null,
    actor: event.actor || null,
    sources: [event.source].filter(Boolean),
  };
  if (view === "business") {
    return {
      ...base,
      impact: businessImpactForTrace(event),
      evidence_count: Array.isArray(event.evidence) ? event.evidence.length : 0,
      related: Array.isArray(event.related) ? event.related : [],
    };
  }
  if (view === "dev") {
    return {
      ...base,
      evidence: Array.isArray(event.evidence) ? event.evidence : [],
      related: Array.isArray(event.related) ? event.related : [],
      git: {
        branch: event.git?.branch || null,
        head_sha: event.git?.head_sha || null,
        event: event.git?.event || null,
        remote: event.git?.remote || null,
        after_sha: event.git?.after_sha || null,
      },
    };
  }
  return {
    ...base,
    evidence: Array.isArray(event.evidence) ? event.evidence : [],
    related: Array.isArray(event.related) ? event.related : [],
    git: event.git || null,
    run: event.run || null,
    raw: event,
  };
}

function businessImpactForTrace(event) {
  const action = String(event.action || event.type || "");
  if (event.type === "decision" || action.includes("approve")) {
    return "decision";
  }
  if (event.type === "test" || action.includes("validation")) {
    return "validation";
  }
  if (event.type === "release") {
    return "release";
  }
  if (event.type === "risk") {
    return "risk";
  }
  if (event.type === "handoff") {
    return "handoff";
  }
  if (event.type === "implementation") {
    return "implementation";
  }
  return "activity";
}

function summarizeActivityEvents(events) {
  const byType = {};
  const byAction = {};
  const byStory = {};
  const byActor = {};
  for (const event of events) {
    incrementCounter(byType, event.type || "unknown");
    incrementCounter(byAction, event.action || event.type || "unknown");
    incrementCounter(byStory, event.story_id || "project");
    incrementCounter(byActor, traceActorKey(event.actor));
  }
  return {
    event_count: events.length,
    story_count: Object.keys(byStory).filter((storyId) => storyId !== "project").length,
    by_type: byType,
    by_action: byAction,
    by_story: byStory,
    by_actor: byActor,
    first_event_at: events[0]?.created_at || null,
    last_event_at: events.at(-1)?.created_at || null,
  };
}

function incrementCounter(target, key) {
  target[key] = (target[key] || 0) + 1;
}

function traceActorKey(actor) {
  if (typeof actor === "string") {
    return actor || "unknown";
  }
  return actor?.id || actor?.name || actor?.type || "unknown";
}

function parseDateBoundary(value, label, options = {}) {
  const raw = String(value || "").trim();
  if (raw === "now") {
    return options.defaultNow || !options.relativeTo ? new Date() : new Date(options.relativeTo);
  }
  const relative = raw.match(/^(\d+)([dhm])$/i);
  if (relative) {
    const amount = Number(relative[1]);
    const unit = relative[2].toLowerCase();
    const millis = unit === "d" ? amount * 86400000 : unit === "h" ? amount * 3600000 : amount * 60000;
    const base = options.relativeTo ? new Date(options.relativeTo) : new Date();
    return new Date(base.getTime() - millis);
  }
  const timestamp = Date.parse(raw);
  if (!Number.isFinite(timestamp)) {
    fail(`Invalid --${label} '${value}'. Use ISO date/time, now, or a relative duration like 3d, 12h, 30m.`);
  }
  return new Date(timestamp);
}

function writeActivityReport(context, report, options) {
  const reportPath = resolveProjectFilePath(context, options.out, { mustExist: false });
  assertNotDerivedArtifact(context, reportPath, "Activity report");
  if (path.extname(reportPath).toLowerCase() === ".md") {
    writeTextFile(reportPath, renderActivityReportMarkdown(report), { force: Boolean(options.force) });
    return;
  }
  writeJsonFile(reportPath, report, { force: Boolean(options.force) });
}

function renderActivityReportMarkdown(report) {
  return [
    "# SDLC Activity Report",
    "",
    `- View: ${report.view}`,
    `- Window: ${report.window.since} -> ${report.window.until}`,
    `- Events: ${report.summary.event_count}`,
    `- Stories: ${report.summary.story_count}`,
    "",
    "## Summary",
    ...Object.entries(report.summary.by_type).map(([type, count]) => `- ${type}: ${count}`),
    "",
    "## Activity",
    ...(report.items.length
      ? report.items.map((item) => {
          const source = item.sources?.[0] ? ` (${item.sources[0].path}:${item.sources[0].line})` : "";
          return `- ${item.created_at || "unknown"} ${item.story_id || "project"} ${item.action}: ${item.summary}${source}`;
        })
      : ["- No canonical trace events in this window"]),
    "",
    "## Sources",
    ...(report.source_paths.length ? report.source_paths.map((sourcePath) => `- ${sourcePath}`) : ["- None"]),
    "",
  ].join("\n");
}

function rebuildManifests(context, options) {
  ensureInitialized(context);
  const manifest = buildKnowledgeManifest(context, options);
  const manifestPath = path.join(context.sdlcRoot, "manifests", "kb-manifest.json");
  writeJsonFile(manifestPath, manifest, { force: true });
  output(
    options,
    { status: "rebuilt", manifest_path: manifestPath, manifest },
    [
      `Rebuilt KB manifest: ${toProjectPath(context, manifestPath)}`,
      `Stories: ${manifest.summary.stories}`,
      `Trace events: ${manifest.summary.trace_events}`,
      `Approvals: ${manifest.summary.approvals}`,
    ],
  );
}

function buildKnowledgeManifest(context, options = {}) {
  const generatedAt = now();
  const session = openProjectQuerySession(context);
  const sourceFiles = collectManifestSourceFiles(context, session);
  const sourcePaths = sourceFiles.map((filePath) => toProjectPath(context, filePath)).sort();
  const stories = readAllStories(context, session);
  const registry = readOutputRegistry(context, { missingOk: true });
  const registryIndex = createOutputRegistryQueryIndex(registry);
  const traceEvents = readAllTraceEvents(context, { session }).filter((event) => event.type !== "invalid");
  const lastTraceByStory = new Map();
  for (const event of traceEvents) {
    if (event.story_id) lastTraceByStory.set(event.story_id, event);
  }
  const approvals = collectApprovalManifestEntries(context, session);
  const contracts = collectJsonFiles(context, path.join(context.sdlcRoot, "contracts"), session).map((contract) => ({
    id: contract.id || path.basename(contract.__path, ".json"),
    phase: contract.phase || null,
    story_id: contract.story_id || null,
    status: contract.status || null,
    path: contract.__relative_path,
  }));
  return {
    kind: "kb_manifest",
    schema_version: context.config.schema_version,
    story_projection_schema_version: "effective-story-lifecycle:v1",
    generated_at: generatedAt,
    canonical_root: SDLC_DIR,
    summary: {
      stories: stories.length,
      contracts: contracts.length,
      output_templates: registry?.templates?.length || 0,
      output_links: registry?.links?.length || 0,
      trace_events: traceEvents.length,
      approvals: approvals.length,
      source_files: sourcePaths.length,
    },
    stories: stories.map((story) => {
      const claimPath = path.join(context.sdlcRoot, "stories", story.id, "claim.json");
      const claim = fs.existsSync(claimPath) ? readProjectJson(context, claimPath) : null;
      const lifecycle = effectiveStoryLifecycleProjection(context, story);
      return {
        id: story.id,
        title: story.title,
        status: story.status,
        phase: story.phase,
        record_status: story.status,
        record_phase: story.phase,
        effective_status: lifecycle.status,
        effective_phase: lifecycle.phase,
        lifecycle_terminal: lifecycle.terminal,
        lifecycle_blocked: lifecycle.blocked,
        lifecycle_source: lifecycle.source,
        workflow_instance_id: lifecycle.workflow_instance_id,
        contract_id: story.contract_id || null,
        requirements: Array.isArray(story.links?.requirements) ? story.links.requirements : [],
        active_claim: claim?.status === "active" ? { agent: claim.agent, branch: claim.branch, expires_at: claim.expires_at || null } : null,
        completed_steps: readStoryStepRecords(context, story.id, session).map((record) => ({
          step: record.step,
          completed_at: record.completed_at,
          output_types: record.output_types || [],
        })),
        output_links: (registryIndex.links_by_story.get(story.id) || [])
          .map((link) => ({
            id: link.id,
            artifact_type: link.artifact_type,
            artifact_path: link.artifact_path,
            mode: link.mode,
            template_id: link.template_id,
          })),
        last_trace: lastTraceByStory.get(story.id) || null,
      };
    }),
    contracts,
    output_contracts: {
      templates: (registry?.templates || []).map((template) => ({
        id: template.id,
        type: template.type,
        status: template.status,
        path: template.path,
        approved_at: template.approved_at || null,
      })),
      links: (registry?.links || []).map((link) => ({
        id: link.id,
        story_id: link.story_id,
        artifact_type: link.artifact_type,
        artifact_path: link.artifact_path,
        template_id: link.template_id,
        mode: link.mode,
        requirements: link.requirements || [],
      })),
    },
    activity: summarizeActivityEvents(traceEvents),
    approvals,
    source_paths: sourcePaths,
    source_hashes: buildSourceHashMap(context, sourcePaths, session),
    audit: {
      generated_by: buildAttribution(context, options, "manifest.rebuild").actor,
      git: buildGitMetadata(context.root),
      run: buildRunMetadata(options),
    },
  };
}

function collectManifestSourceFiles(context, session = null) {
  return collectKnowledgeSourceFiles(context, session).filter((filePath) => {
    const relative = path.relative(context.sdlcRoot, filePath);
    return !relative.startsWith(`manifests${path.sep}`);
  });
}

function collectJsonFiles(context, root, session = null) {
  if (session) {
    return session.jsonRecords({ under: toProjectPath(context, root) }).map((record) => ({
      ...record.value,
      __path: path.join(context.root, ...record.path.split("/")),
      __relative_path: record.path,
    }));
  }
  return walkFiles(root)
    .filter((filePath) => filePath.endsWith(".json"))
    .map((filePath) => {
      const data = readProjectJson(context, filePath);
      data.__path = filePath;
      data.__relative_path = toProjectPath(context, filePath);
      return data;
    });
}

function collectApprovalManifestEntries(context, session = null) {
  const entries = [];
  for (const filePath of collectManifestSourceFiles(context, session).filter((candidate) => candidate.endsWith(".json"))) {
    let data;
    try {
      data = session ? session.readJson(toProjectPath(context, filePath)) : readProjectJson(context, filePath);
    } catch {
      continue;
    }
    const relativePath = toProjectPath(context, filePath);
    for (const approval of data.approvals || []) {
      entries.push({
        subject_id: data.id || data.project_id || path.basename(filePath, ".json"),
        subject_path: relativePath,
        approval_id: approval.id || null,
        status: approval.status || null,
        approval_source: approval.approval_source || null,
        actor: approval.approved_by || approval.actor || null,
        created_at: approval.created_at || approval.approved_at || null,
      });
    }
    if (data.approval_source || data.approved_by || data.approved_at) {
      entries.push({
        subject_id: data.id || path.basename(filePath, ".json"),
        subject_path: relativePath,
        approval_id: data.id || null,
        status: data.status || null,
        approval_source: data.approval_source || null,
        actor: data.approved_by || data.audit?.decided_by || null,
        created_at: data.approved_at || data.created_at || null,
      });
    }
  }
  return entries.sort((a, b) => String(a.created_at || "").localeCompare(String(b.created_at || "")));
}

function compactTraces(context, options) {
  ensureInitialized(context);
  const storyId = options.story ? normalizeId(options.story) : null;
  const beforeDate = options.before ? parseDateBoundary(options.before, "before") : null;
  const events = readAllTraceEvents(context, { story: storyId })
    .filter((event) => event.type !== "invalid")
    .filter((event) => !beforeDate || Date.parse(String(event.created_at || "")) < beforeDate.getTime())
    .sort((a, b) => String(a.created_at || "").localeCompare(String(b.created_at || "")));
  const sourcePaths = Array.from(new Set(events.map((event) => event.source?.path).filter(Boolean))).sort();
  const id = normalizeId(`CMP-${storyId || "project"}-${uniqueRecordSuffix()}`);
  const compaction = {
    id,
    kind: "trace_compaction",
    schema_version: context.config.schema_version,
    story_id: storyId,
    generated_at: now(),
    cutoff_before: beforeDate ? beforeDate.toISOString() : null,
    canonical_source_retained: true,
    event_count: events.length,
    summary: summarizeActivityEvents(events),
    timeline: events.slice(-100).map((event) => ({
      id: event.id || null,
      created_at: event.created_at || null,
      story_id: event.story_id || null,
      type: event.type || null,
      action: event.action || null,
      summary: event.summary || null,
      actor: event.actor || null,
      sources: [event.source].filter(Boolean),
    })),
    source_paths: sourcePaths,
    source_hashes: buildSourceHashMap(context, sourcePaths),
    audit: {
      generated_by: buildAttribution(context, options, "trace.compact").actor,
      git: buildGitMetadata(context.root),
      run: buildRunMetadata(options),
    },
  };
  const outputPath = options.out
    ? resolveProjectFilePath(context, options.out, { mustExist: false })
    : path.join(context.sdlcRoot, "traces", "compactions", `${id}.json`);
  assertNotDerivedArtifact(context, outputPath, "Trace compaction");
  writeJsonFile(outputPath, compaction, { force: Boolean(options.force) });
  appendTraceEvent(context, storyId, {
    type: "decision",
    summary: `Compacted ${events.length} trace events into ${toProjectPath(context, outputPath)}`,
    action: "trace.compact",
    actor: compaction.audit.generated_by,
    evidence: [toProjectPath(context, outputPath)],
    related: [id, storyId].filter(Boolean),
    git: compaction.audit.git,
    run: compaction.audit.run,
  });
  output(
    options,
    { status: "compacted", compaction_path: outputPath, compaction },
    [`Compacted ${events.length} trace events into ${toProjectPath(context, outputPath)}`],
  );
}

function archiveClosedArtifacts(context, options) {
  ensureInitialized(context);
  const beforeDate = parseDateBoundary(options.before || "90d", "before");
  const candidates = collectArchiveCandidates(context, beforeDate);
  const planId = normalizeId(`ARCH-${uniqueRecordSuffix()}`);
  const plan = {
    id: planId,
    kind: "archive_plan",
    schema_version: context.config.schema_version,
    generated_at: now(),
    cutoff_before: beforeDate.toISOString(),
    apply_requested: Boolean(options.apply),
    applied: false,
    candidates,
    source_paths: candidates.map((candidate) => candidate.source_path),
    source_hashes: buildSourceHashMap(context, candidates.map((candidate) => candidate.source_path)),
    policy: "Only closed reports and trace compactions are eligible; live story, contract, trace JSONL, and approval files are not moved.",
    audit: {
      generated_by: buildAttribution(context, options, "archive.closed").actor,
      git: buildGitMetadata(context.root),
      run: buildRunMetadata(options),
    },
  };
  const planPath = options.out
    ? resolveProjectFilePath(context, options.out, { mustExist: false })
    : path.join(context.sdlcRoot, "archive", `${planId}.json`);
  assertNotDerivedArtifact(context, planPath, "Archive plan");
  if (fs.existsSync(planPath) && !options.force) {
    fail(`Archive plan already exists: ${toProjectPath(context, planPath)}. Use --force to overwrite it.`);
  }
  const reservedPaths = new Set(
    candidates.flatMap((candidate) => [candidate.source_path, candidate.target_path]).map((entry) =>
      resolveProjectFilePath(context, entry, { mustExist: false }),
    ),
  );
  if (reservedPaths.has(planPath)) {
    fail("Archive plan path must be separate from every archive source and target.");
  }
  if (options.apply) {
    plan.applied = true;
    applyArchiveCandidates(context, candidates, { force: Boolean(options.force) }, () => {
      writeJsonFile(planPath, plan, { force: Boolean(options.force) });
    });
  } else {
    writeJsonFile(planPath, plan, { force: Boolean(options.force) });
  }
  output(
    options,
    { status: plan.applied ? "archived" : "planned", plan_path: planPath, plan },
    [
      `${plan.applied ? "Archived" : "Planned archive for"} ${candidates.length} closed artifacts`,
      `Archive plan: ${toProjectPath(context, planPath)}`,
    ],
  );
}

function applyArchiveCandidates(context, candidates, options = {}, commit = () => {}) {
  const releaseLock = acquireFileLock(path.join(context.sdlcRoot, "archive", "archive.lock"));
  const operations = [];
  const completed = [];
  const backups = [];
  try {
    for (const candidate of candidates) {
      const sourcePath = resolveProjectFilePath(context, candidate.source_path, { mustExist: true, fileOnly: true });
      const targetPath = resolveProjectFilePath(context, candidate.target_path, { mustExist: false });
      assertNoSymlinkPathSegments(sourcePath, context.root);
      assertNoSymlinkPathSegments(targetPath, context.root);
      if (hashFile(sourcePath) !== candidate.sha256) {
        fail(`Archive source changed after planning: ${candidate.source_path}`);
      }
      if (fs.existsSync(targetPath)) {
        if (!options.force) {
          fail(`Archive target already exists: ${candidate.target_path}. Use --force to overwrite after review.`);
        }
        if (!fs.lstatSync(targetPath).isFile()) {
          fail(`Archive target is not a regular file: ${candidate.target_path}`);
        }
      }
      operations.push({ candidate, sourcePath, targetPath });
    }

    for (const operation of operations) {
      ensureDir(path.dirname(operation.targetPath));
      if (fs.existsSync(operation.targetPath)) {
        const backupPath = `${operation.targetPath}.backup-${process.pid}-${crypto.randomBytes(4).toString("hex")}`;
        renamePathGoverned(operation.targetPath, backupPath);
        backups.push({ targetPath: operation.targetPath, backupPath });
      }
      renamePathGoverned(operation.sourcePath, operation.targetPath);
      completed.push(operation);
    }
    for (const operation of completed) {
      operation.candidate.applied = true;
    }
    commit();
    for (const backup of backups) {
      try {
        removePathGoverned(backup.backupPath, { force: true });
      } catch {
        // The archive is committed; an orphaned backup is safer than rolling it back incompletely.
      }
    }
  } catch (error) {
    for (const operation of completed) {
      operation.candidate.applied = false;
    }
    for (const operation of [...completed].reverse()) {
      try {
        if (fs.existsSync(operation.targetPath) && !fs.existsSync(operation.sourcePath)) {
          ensureDir(path.dirname(operation.sourcePath));
          renamePathGoverned(operation.targetPath, operation.sourcePath);
        }
      } catch {
        // Continue restoring the remaining files; the final error reports the failed transaction.
      }
    }
    for (const backup of [...backups].reverse()) {
      try {
        if (fs.existsSync(backup.backupPath)) {
          renamePathGoverned(backup.backupPath, backup.targetPath);
        }
      } catch {
        // Best effort rollback for a filesystem-level failure.
      }
    }
    if (error instanceof UserError) {
      throw error;
    }
    fail(`Archive transaction failed and was rolled back: ${error.message}`);
  } finally {
    releaseLock();
  }
}

function collectArchiveCandidates(context, beforeDate) {
  const eligibleRoots = [
    { root: path.join(context.sdlcRoot, "reports"), reason: "closed-report" },
    { root: path.join(context.sdlcRoot, "traces", "compactions"), reason: "trace-compaction" },
  ];
  const candidates = [];
  for (const entry of eligibleRoots) {
    for (const filePath of walkFiles(entry.root)) {
      if (!shouldIndexFile(context, filePath)) {
        continue;
      }
      const stat = fs.statSync(filePath);
      if (stat.mtime.getTime() >= beforeDate.getTime()) {
        continue;
      }
      const relativeSource = toProjectPath(context, filePath);
      const archiveRelative = path.posix.join(
        SDLC_DIR,
        "archive",
        String(stat.mtime.getUTCFullYear()),
        String(stat.mtime.getUTCMonth() + 1).padStart(2, "0"),
        path.relative(context.sdlcRoot, filePath).split(path.sep).join("/"),
      );
      candidates.push({
        source_path: relativeSource,
        target_path: archiveRelative,
        reason: entry.reason,
        size_bytes: stat.size,
        mtime: stat.mtime.toISOString(),
        sha256: hashFile(filePath),
        applied: false,
      });
    }
  }
  return candidates.sort((a, b) => a.source_path.localeCompare(b.source_path));
}

function logicalArchiveRoot(context) {
  return configuredSdlcDirectory(
    context,
    context.config.release_evidence_policy?.archive_directory,
    "archive",
    "release_evidence_policy.archive_directory",
  );
}

function releaseManifestEvidenceEntries(context, manifest, manifestPath = null) {
  const entries = [];
  const addReference = (reference, artifactType) => {
    if (!reference?.path) {
      return;
    }
    entries.push({
      id: reference.id || null,
      artifact_type: artifactType,
      path: reference.path,
    });
  };

  if (manifestPath) {
    entries.push({
      id: manifest.id || null,
      artifact_type: "release-manifest",
      path: manifestPath,
    });
  }
  for (const reference of manifest.requirements || []) {
    addReference(reference, "requirement");
  }
  for (const reference of manifest.stories || []) {
    addReference(reference, "story");
  }
  for (const reference of manifest.contracts || []) {
    addReference(reference, "contract");
  }
  for (const reference of manifest.proposals || []) {
    addReference(reference, "assessment-proposal");
  }
  addReference(manifest.workflow, "assessment-workflow");
  for (const artifact of manifest.artifacts || []) {
    addReference(artifact, artifact.artifact_type || "release-artifact");
    addReference(artifact.verification_receipt_ref, "verification-receipt");
  }
  for (const reference of manifest.authorization_usage_receipts || []) {
    addReference(reference, "authorization-usage-receipt");
  }
  for (const reference of manifest.execution_usage_receipts || []) {
    addReference(reference, "execution-usage-receipt");
  }
  for (const reference of manifest.context_optimization_observations || []) {
    addReference(reference, "context-optimization-observation");
  }
  addReference(manifest.budget_decision?.budget_ref, "execution-budget");
  for (const reference of manifest.gate_receipts || []) {
    addReference(reference, "release-gate-receipt");
  }
  for (const reference of manifest.proposals || []) {
    const proposalId = reference.id;
    const proposal = readAssessmentProposal(context, proposalId);
    addReference(proposal.baseline_ref, "approved-baseline");
    if (proposal.deliverable?.template_path) {
      addReference({ id: proposal.deliverable.template_id, path: proposal.deliverable.template_path }, "output-template");
    }
    const approvalFile = assessmentApprovalPath(context, proposalId);
    if (fs.existsSync(approvalFile)) {
      const approval = readAssessmentApproval(context, proposalId);
      addReference({ id: approval.id, path: toProjectPath(context, approvalFile) }, "assessment-approval");
      if (approval.host_receipt_ref) {
        addReference({ id: null, path: approval.host_receipt_ref }, "host-approval-receipt");
      }
    }
    const applicationFile = assessmentApplicationPath(context, proposalId);
    if (fs.existsSync(applicationFile)) {
      const application = readAssessmentApplication(context, proposalId);
      addReference({ id: application.id, path: toProjectPath(context, applicationFile) }, "assessment-application");
      for (const amendment of application.budget_amendments || []) {
        addReference(amendment, "budget-amendment");
      }
      if (application.authorization_ref) {
        const authorizationFile = authorizationPath(context, application.authorization_ref);
        addReference({ id: application.authorization_ref, path: toProjectPath(context, authorizationFile) }, "content-authorization");
        const lifecycleFile = authorizationLifecyclePath(context, application.authorization_ref);
        if (fs.existsSync(lifecycleFile)) {
          addReference({ id: application.authorization_ref, path: toProjectPath(context, lifecycleFile) }, "authorization-lifecycle");
        }
      }
    }
    const taskStartFile = path.join(context.sdlcRoot, "stories", proposal.story_reservation.id, "task-start.json");
    if (fs.existsSync(taskStartFile)) {
      addReference({ id: `START-${proposal.story_reservation.id}`, path: toProjectPath(context, taskStartFile) }, "task-start-receipt");
    }
  }
  return entries;
}

function validateActiveManifestRecordSchemas(context, manifest) {
  const typedReferences = [
    ...(manifest.requirements || []).map((reference) => [reference, "requirement.schema.json", "requirement"]),
    ...(manifest.stories || []).map((reference) => [reference, "story.schema.json", "story"]),
    ...(manifest.contracts || []).map((reference) => [reference, "contract.schema.json", "contract"]),
    ...(manifest.proposals || []).map((reference) => [reference, "assessment-proposal.schema.json", "assessment proposal"]),
    ...[manifest.workflow].filter(Boolean).map((reference) => [reference, "assessment-workflow.schema.json", "assessment workflow"]),
    ...(manifest.authorization_usage_receipts || []).map((reference) => [reference, "authorization-usage-receipt.schema.json", "authorization usage receipt"]),
    ...(manifest.execution_usage_receipts || []).map((reference) => [reference, "execution-usage-receipt.schema.json", "execution usage receipt"]),
    ...(manifest.context_optimization_observations || []).map((reference) => [reference, "context-optimization-observation.schema.json", "context optimization observation"]),
    ...(manifest.gate_receipts || []).map((reference) => [reference, "release-gate-receipt.schema.json", "release gate receipt"]),
    ...[manifest.budget_decision?.budget_ref].filter(Boolean).map((reference) => [reference, "execution-budget.schema.json", "execution budget"]),
    ...(manifest.artifacts || []).map((artifact) => [artifact.verification_receipt_ref, "verification-receipt.schema.json", "verification receipt"]),
  ];
  for (const [reference, schemaName, label] of typedReferences) {
    const filePath = resolveProjectFilePath(context, reference.path, { mustExist: true, fileOnly: true });
    assertRecordSchema(readProjectJson(context, filePath), schemaName, `${label} ${reference.id}`);
  }
  return typedReferences.length;
}

function collectHistoricalReleaseArtifacts(context, activeManifest, activeManifestFile) {
  const manifestRoot = path.dirname(releaseManifestPath(context, "MANIFEST-ROOT-CHECK"));
  const activeEntries = releaseManifestEvidenceEntries(
    context,
    activeManifest,
    toProjectPath(context, activeManifestFile),
  );
  const activePaths = new Set(activeEntries.map((entry) => {
    const evidencePath = resolveProjectFilePath(context, entry.path, { mustExist: true, fileOnly: true });
    assertNoSymlinkPathSegments(evidencePath, context.root);
    return fs.realpathSync.native(evidencePath);
  }));
  const candidates = new Map();
  let historicalReleaseCount = 0;
  const quarantinedReleases = [];

  for (const name of safeReadDir(manifestRoot).filter((entry) => entry.endsWith(".json")).sort()) {
    const filePath = path.join(manifestRoot, name);
    if (path.resolve(filePath) === path.resolve(activeManifestFile)) {
      continue;
    }
    let historicalManifest;
    try {
      historicalManifest = readProjectJson(context, filePath);
    } catch (error) {
      quarantinedReleases.push({ path: toProjectPath(context, filePath), reason: error.message });
      continue;
    }
    if (historicalManifest.kind !== "release_manifest" || historicalManifest.status !== "released") {
      continue;
    }
    try {
      assertReleaseManifestIntegrity(context, historicalManifest);
    } catch (error) {
      quarantinedReleases.push({ id: historicalManifest.id || null, path: toProjectPath(context, filePath), reason: error.message });
      continue;
    }
    historicalReleaseCount += 1;
    let historicalEntries;
    try {
      historicalEntries = releaseManifestEvidenceEntries(context, historicalManifest, toProjectPath(context, filePath));
    } catch (error) {
      quarantinedReleases.push({ id: historicalManifest.id || null, path: toProjectPath(context, filePath), reason: error.message });
      historicalReleaseCount -= 1;
      continue;
    }
    const releaseCandidates = [];
    try {
      for (const entry of historicalEntries) {
        const evidencePath = resolveProjectFilePath(context, entry.path, { mustExist: true, fileOnly: true });
        assertNoSymlinkPathSegments(evidencePath, context.root);
        const canonicalKey = fs.realpathSync.native(evidencePath);
        if (activePaths.has(canonicalKey) || candidates.has(canonicalKey)) {
          continue;
        }
        releaseCandidates.push([canonicalKey, {
          id: entry.id,
          artifact_type: entry.artifact_type,
          path: toProjectPath(context, evidencePath),
          sha256: hashFile(evidencePath),
          classification: "legacy_history",
          excluded_from_release: true,
          retention: "retain-in-place",
          archive_plan_ref: null,
        }]);
      }
    } catch (error) {
      quarantinedReleases.push({ id: historicalManifest.id || null, path: toProjectPath(context, filePath), reason: error.message });
      historicalReleaseCount -= 1;
      continue;
    }
    for (const [canonicalKey, candidate] of releaseCandidates) {
      candidates.set(canonicalKey, candidate);
    }
  }

  return {
    historical_release_count: historicalReleaseCount,
    active_paths: activeEntries.map((entry) => entry.path).sort(),
    artifacts: Array.from(candidates.values()).sort((left, right) => left.path.localeCompare(right.path)),
    quarantined_releases: quarantinedReleases,
  };
}

function readLogicalArchiveRecords(context, releaseManifestId) {
  const root = logicalArchiveRoot(context);
  return safeReadDir(root)
    .filter((name) => name.endsWith(".json"))
    .map((name) => {
      const filePath = path.join(root, name);
      let record;
      try {
        record = readProjectJson(context, filePath);
      } catch {
        return null;
      }
      if (record.kind !== "archive_record" || record.release_manifest_ref?.id !== releaseManifestId) {
        return null;
      }
      assertRecordSchema(record, "archive-record.schema.json", `Logical archive record ${record.id}`);
      const { record_hash: actualHash, hash_algorithm: _algorithm, ...hashSubject } = record;
      if (actualHash !== shortHashFull(stableJson(hashSubject))) {
        fail(`Logical archive record ${record.id} failed integrity validation.`);
      }
      if (path.resolve(filePath) !== path.resolve(path.join(root, `${normalizeId(record.id)}.json`))) {
        fail(`Logical archive record ${record.id} is not stored at its canonical id-bound path.`);
      }
      const artifactPaths = (record.artifacts || []).map((artifact) => artifact.path).sort();
      const sourcePaths = [...(record.source_paths || [])].sort();
      const hashedPaths = Object.keys(record.source_hashes || {}).sort();
      if (stableJson(artifactPaths) !== stableJson(sourcePaths) || stableJson(sourcePaths) !== stableJson(hashedPaths)) {
        fail(`Logical archive record ${record.id} has an incomplete artifact/source path inventory.`);
      }
      for (const artifact of record.artifacts || []) {
        if (record.source_hashes?.[artifact.path] !== artifact.sha256) {
          fail(`Logical archive record ${record.id} has inconsistent hashes for ${artifact.path}.`);
        }
      }
      return { record, filePath };
    })
    .filter(Boolean)
    .sort((left, right) => String(left.record.generated_at).localeCompare(String(right.record.generated_at)));
}

function prepareLogicalArchiveRecord(context, manifest, manifestFile, historical, attribution, reason, options = {}) {
  if (historical.artifacts.length === 0) {
    return { record: null, filePath: null, idempotent: true };
  }
  const prior = readLogicalArchiveRecords(context, manifest.id)
    .filter((entry) => entry.record.status === "active")
    .at(-1) || null;
  const sourcePaths = historical.artifacts.map((artifact) => artifact.path);
  const sourceHashes = Object.fromEntries(historical.artifacts.map((artifact) => [artifact.path, artifact.sha256]));
  if (
    prior &&
    prior.record.status === "active" &&
    prior.record.release_manifest_ref?.id === manifest.id &&
    prior.record.release_manifest_ref?.path === toProjectPath(context, manifestFile) &&
    prior.record.release_manifest_ref?.hash === manifest.manifest_hash &&
    (options.reason_explicit !== true || prior.record.reason === reason) &&
    stableJson(prior.record.artifacts) === stableJson(historical.artifacts) &&
    stableJson(prior.record.source_paths) === stableJson(sourcePaths) &&
    stableJson(prior.record.source_hashes) === stableJson(sourceHashes)
  ) {
    return { record: prior.record, filePath: prior.filePath, idempotent: true };
  }
  const id = normalizeId(`ARCH-${manifest.id}-${uniqueRecordSuffix()}`);
  const record = {
    id,
    kind: "archive_record",
    schema_version: "archive-record:v1",
    status: "active",
    release_manifest_ref: {
      id: manifest.id,
      path: toProjectPath(context, manifestFile),
      hash: manifest.manifest_hash,
    },
    legacy_history_policy: "logically_archived_out_of_release_scope",
    reason,
    artifacts: historical.artifacts,
    source_paths: sourcePaths,
    source_hashes: sourceHashes,
    supersedes_ref: prior
      ? { id: prior.record.id, path: toProjectPath(context, prior.filePath), hash: prior.record.record_hash }
      : null,
    generated_at: now(),
    audit: {
      generated_by: attribution.actor,
      git: attribution.git,
      run: attribution.run,
    },
  };
  record.record_hash = shortHashFull(stableJson(record));
  record.hash_algorithm = "sha256:stable-json:v1";
  assertRecordSchema(record, "archive-record.schema.json", `Logical archive record ${id}`);
  return { record, filePath: path.join(logicalArchiveRoot(context), `${id}.json`), idempotent: false };
}

function assertLatestReleasedManifestSelected(context, manifest, manifestFile) {
  const manifestRoot = path.dirname(releaseManifestPath(context, "MANIFEST-ROOT-CHECK"));
  const maxFutureSkewMs = Number(context.config.release_evidence_policy?.max_future_skew_seconds ?? 300) * 1000;
  const candidates = [];
  const quarantined = [];
  for (const name of safeReadDir(manifestRoot).filter((entry) => entry.endsWith(".json")).sort()) {
    const filePath = path.join(manifestRoot, name);
    let candidate;
    try {
      candidate = readProjectJson(context, filePath);
    } catch (error) {
      quarantined.push({ path: toProjectPath(context, filePath), reason: error.message });
      continue;
    }
    if (
      candidate.kind !== "release_manifest" ||
      candidate.status !== "released" ||
      candidate.project?.id !== manifest.project?.id
    ) continue;
    const envelopeErrors = [];
    const schema = validateRecordSchema(candidate, "release-manifest.schema.json");
    envelopeErrors.push(...schema.errors.map((error) => `${error.instance_path}: ${error.message}`));
    const { manifest_hash: storedHash, hash_algorithm: algorithm, ...hashSubject } = candidate;
    if (algorithm !== "sha256:stable-json:v1" || storedHash !== shortHashFull(stableJson(hashSubject))) {
      envelopeErrors.push("manifest hash is invalid");
    }
    if (!candidate.id || path.resolve(filePath) !== path.resolve(releaseManifestPath(context, candidate.id))) {
      envelopeErrors.push("manifest path is not canonically bound to its id");
    }
    const candidateAt = Date.parse(candidate.released_at || "");
    if (!Number.isFinite(candidateAt)) {
      envelopeErrors.push("released_at is invalid");
    } else if (candidateAt > Date.now() + maxFutureSkewMs) {
      envelopeErrors.push(`released_at is more than ${maxFutureSkewMs / 1000} seconds in the future`);
    }
    if (!Array.isArray(candidate.gate_receipts) || candidate.gate_receipts.length !== 1) {
      envelopeErrors.push("manifest must contain exactly one release gate receipt");
    } else {
      try {
        const gateReference = candidate.gate_receipts[0];
        const gatePath = resolveProjectFilePath(context, gateReference.path, { mustExist: true, fileOnly: true });
        if (path.resolve(gatePath) !== path.resolve(releaseGateReceiptPath(context, gateReference.id))) {
          envelopeErrors.push("release gate receipt path is not canonical");
        } else {
          const gate = readProjectJson(context, gatePath);
          const gateSchema = validateRecordSchema(gate, "release-gate-receipt.schema.json");
          envelopeErrors.push(...gateSchema.errors.map((error) => `gate ${error.instance_path}: ${error.message}`));
          const { receipt_hash: gateHash, hash_algorithm: gateAlgorithm, ...gateSubject } = gate;
          if (
            gateAlgorithm !== "sha256:stable-json:v1" ||
            gateHash !== shortHashFull(stableJson(gateSubject)) ||
            gateHash !== gateReference.hash ||
            gate.status !== "passed" ||
            gate.scope?.manifest_id !== candidate.id
          ) {
            envelopeErrors.push("release gate receipt does not attest this manifest envelope");
          }
        }
      } catch (error) {
        envelopeErrors.push(`release gate receipt cannot be verified: ${error.message}`);
      }
    }
    if (envelopeErrors.length > 0) {
      const entry = { id: candidate.id || null, path: toProjectPath(context, filePath), reason: envelopeErrors.join("; ") };
      if (path.resolve(filePath) === path.resolve(manifestFile)) {
        fail(`Selected release manifest ${manifest.id} is not eligible as the active release: ${entry.reason}`);
      }
      quarantined.push(entry);
      continue;
    }
    candidates.push({ candidate, filePath, candidateAt });
  }
  const ordered = candidates.sort((left, right) =>
    left.candidateAt - right.candidateAt ||
    String(left.candidate.id).localeCompare(String(right.candidate.id)) ||
    String(left.candidate.manifest_hash).localeCompare(String(right.candidate.manifest_hash))
  );
  const latest = ordered.at(-1);
  if (!latest || path.resolve(latest.filePath) !== path.resolve(manifestFile)) {
    const latestId = latest?.candidate?.id || "unknown";
    fail([
      `Release ${manifest.id} is not the newest released manifest; deterministic ordering selects ${latestId}.`,
      "What I need: select the newest released manifest, or run an explicit rollback workflow that creates a new release manifest.",
      "Why: migration active classifies every other release as history; selecting an older release would silently archive newer evidence. Equal timestamps are ordered by manifest ID and hash.",
      `Example: agentic-sdlc migration active --release-manifest ${latestId} --apply`,
      "Effect: only evidence older than the selected current release is classified as historical.",
    ].join("\n"));
  }
  return { quarantined_releases: quarantined };
}

function prepareActiveReleaseMigration(context, options, manifestInput) {
  const { filePath: manifestFile, manifest } = readReleaseManifest(context, manifestInput);
  assertReleaseManifestIntegrity(context, manifest);
  const selection = assertLatestReleasedManifestSelected(context, manifest, manifestFile);
  const activeRecordCount = validateActiveManifestRecordSchemas(context, manifest);
  const historical = collectHistoricalReleaseArtifacts(context, manifest, manifestFile);
  historical.quarantined_releases = Array.from(new Map([
    ...(selection.quarantined_releases || []),
    ...(historical.quarantined_releases || []),
  ].map((entry) => [`${entry.id || ""}:${entry.path}`, entry])).values());
  const configPath = path.join(context.sdlcRoot, PROJECT_CONFIG_FILE_NAME);
  const rawConfig = readProjectJson(context, configPath);
  const migratedConfig = rawConfig;
  const configUpdateRequired = context.configState.status !== "locked";
  const attribution = buildAttribution(context, options, "migration.active");
  const explicitReason = getOptionString(options, "reason");
  const reason = explicitReason || `Retain evidence from releases older than ${manifest.id} while excluding it from the exact active release scope.`;
  const preparedArchive = prepareLogicalArchiveRecord(
    context,
    manifest,
    manifestFile,
    historical,
    attribution,
    reason,
    { reason_explicit: Boolean(explicitReason) },
  );
  return {
    manifestFile,
    manifest,
    activeRecordCount,
    historical,
    configPath,
    rawConfig,
    migratedConfig,
    configUpdateRequired,
    attribution,
    preparedArchive,
  };
}

function migrateActiveReleaseScope(context, options) {
  ensureInitialized(context);
  const manifestInput = getOptionString(options, "release-manifest");
  if (!manifestInput) {
    fail([
      "Active-only migration needs --release-manifest <id-or-path>.",
      "What I need: the exact released scope that must remain active and be validated against current schemas.",
      "Why: without a manifest, completed history cannot be distinguished safely from other work that is still active.",
      "Example: agentic-sdlc migration active --release-manifest RELEASE-ASSESSMENT-20260714 --apply",
      "Effect: only configuration defaults are upgraded; immutable active records are validated, never silently rewritten; older released evidence is retained in place and listed in an archive-record:v1.",
    ].join("\n"));
  }
  let plan;
  let archiveWritten = false;
  let traceWarning = null;

  if (options.apply) {
    const releaseLock = acquireFileLock(path.join(context.sdlcRoot, "releases", "migration-active.lock"));
    let configWritten = false;
    try {
      plan = prepareActiveReleaseMigration(context, options, manifestInput);
      if (plan.configUpdateRequired) {
        fail([
          "The release migration was not applied because the project configuration is not pinned.",
          "Impact: no release, archive, or configuration files were changed.",
          "Next: run `agentic-sdlc config migrate`, review and apply its exact plan hash, then retry this release migration.",
        ].join("\n"));
      }
      if (plan.preparedArchive.record && !plan.preparedArchive.idempotent) {
        writeJsonFile(plan.preparedArchive.filePath, plan.preparedArchive.record);
        archiveWritten = true;
      }
      try {
        appendTraceEvent(context, null, {
          type: "decision",
          outcome: "passed",
          summary: `Applied active-only schema migration for release ${plan.manifest.id}`,
          action: "migration.active",
          actor: plan.attribution.actor,
          evidence: [
            toProjectPath(context, plan.manifestFile),
            plan.preparedArchive.filePath ? toProjectPath(context, plan.preparedArchive.filePath) : null,
          ].filter(Boolean),
          related: [plan.manifest.id, plan.preparedArchive.record?.id].filter(Boolean),
          git: plan.attribution.git,
          run: plan.attribution.run,
        });
      } catch (error) {
        traceWarning = `Migration committed, but its non-canonical trace could not be appended: ${error.message}`;
      }
    } catch (error) {
      if (archiveWritten && plan?.preparedArchive.filePath && fs.existsSync(plan.preparedArchive.filePath)) {
        removePathGoverned(plan.preparedArchive.filePath, { force: true });
      }
      if (configWritten) {
        writeJsonFile(plan.configPath, plan.rawConfig, { force: true });
      }
      throw error;
    } finally {
      releaseLock();
    }
    context.config = plan.migratedConfig;
  } else {
    plan = prepareActiveReleaseMigration(context, options, manifestInput);
  }

  const {
    manifestFile,
    manifest,
    activeRecordCount,
    historical,
    configUpdateRequired,
    preparedArchive,
  } = plan;

  const payload = {
    status: options.apply ? "applied" : "planned",
    mode: "active-only",
    release_manifest: { id: manifest.id, path: toProjectPath(context, manifestFile), hash: manifest.manifest_hash },
    active_records_validated: activeRecordCount,
    immutable_active_records_rewritten: 0,
    config_update_required: configUpdateRequired,
    config_updated: Boolean(options.apply && configUpdateRequired),
    historical_releases: historical.historical_release_count,
    historical_artifacts: historical.artifacts.length,
    quarantined_historical_releases: historical.quarantined_releases,
    trace_warning: traceWarning,
    logical_archive: preparedArchive.record
      ? {
          id: preparedArchive.record.id,
          path: toProjectPath(context, preparedArchive.filePath),
          hash: preparedArchive.record.record_hash,
          idempotent: preparedArchive.idempotent,
          written: archiveWritten,
        }
      : null,
    physical_files_moved: 0,
  };
  output(options, payload, [
    `${options.apply ? "Applied" : "Planned"} active-only migration for ${manifest.id}.`,
    `Active immutable records validated: ${activeRecordCount}; rewritten: 0.`,
    configUpdateRequired
      ? "Configuration must be reviewed and pinned separately before this migration can be applied."
      : "Configuration is already pinned; this migration will not modify it.",
    historical.artifacts.length > 0
      ? `${historical.artifacts.length} artifacts from ${historical.historical_release_count} older release(s) ${options.apply ? "are" : "will be"} logically archived; every file stays in place.`
      : "No older released evidence needs a logical archive record.",
    ...(historical.quarantined_releases.length > 0
      ? [`Warning: ${historical.quarantined_releases.length} corrupt/incomplete historical release(s) were quarantined from the archive inventory instead of blocking the active scope.`]
      : []),
    ...(traceWarning ? [`Warning: ${traceWarning}`] : []),
    options.apply
      ? "Effect: current release lineage remains canonical; historical evidence remains readable but is excluded from this release gate."
      : configUpdateRequired
        ? "Next: run `agentic-sdlc config migrate`, review its plan, and apply that exact hash first."
        : `Example to apply exactly this plan: agentic-sdlc migration active --release-manifest ${manifest.id} --apply`,
  ]);
}

function migrateIdentity(context, options) {
  if (options.recover) {
    if (
      options.apply
      || getOptionString(options, "identity-map-json")
      || getOptionString(options, "identity-map-file")
      || getOptionString(options, "from-email")
      || getOptionString(options, "to-email")
      || getOptionString(options, "to-name")
      || getOptionString(options, "reason")
    ) {
      fail("Identity migration --recover cannot be combined with mapping, apply, or reason options.");
    }
    const recoveryNonce = getOptionString(options, "recovery-nonce");
    const recoveryPlanHash = getOptionString(options, "plan-hash");
    if (!recoveryNonce || !recoveryPlanHash) {
      fail("Identity migration --recover requires both --recovery-nonce and --plan-hash from the verified lock.");
    }
    try {
      const recoveryPreparation = prepareIdentityMigrationRecovery({
        projectRoot: context.root,
        recoveryNonce,
        planHash: recoveryPlanHash,
      });
      if (recoveryPreparation.status === "no_recovery_needed") {
        output(options, { status: "no_recovery_needed", recovered: false }, [
          "No interrupted identity migration requires recovery.",
        ]);
        return;
      }
      const grant = createBootstrapMutationGrant({
        root: context.root,
        canonical_action: "migration.identity",
        recover: true,
        nonce: recoveryNonce,
        expected_nonce: recoveryNonce,
        plan_hash: recoveryPlanHash,
        expected_plan_hash: recoveryPlanHash,
        exact_mutations: recoveryPreparation.exact_mutations,
      });
      const result = consumeBootstrapMutationGrant(grant, () => recoverIdentityMigration({
        projectRoot: context.root,
        recoveryNonce,
        planHash: recoveryPlanHash,
        recoveryPreparation,
        mutationGateway: executeIdentityMutation,
      }));
      output(options, result, [
        result.status === "rolled_back"
          ? `Recovered interrupted identity migration ${result.migration_id} by restoring the complete pre-migration tree.`
          : result.status === "committed"
            ? `Finalized already-validated identity migration ${result.migration_id} after interrupted cleanup.`
            : result.status === "cleared_before_swap"
              ? `Cleared interrupted identity migration ${result.migration_id}; the live tree was never swapped.`
              : "No interrupted identity migration requires recovery.",
      ]);
      return;
    } catch (error) {
      if (error instanceof IdentityMigrationError) fail(error.message);
      throw error;
    }
  }
  ensureInitialized(context);
  const inlineMapping = getOptionString(options, "identity-map-json");
  const fileMapping = getOptionString(options, "identity-map-file");
  const directSource = getOptionString(options, "from-email");
  const directTarget = getOptionString(options, "to-email");
  const directName = getOptionString(options, "to-name");
  const expectedPlanHash = getOptionString(options, "plan-hash");
  if ((inlineMapping || fileMapping) && (directSource || directTarget || directName)) {
    fail("Use either --identity-map-json/--identity-map-file or direct --from-email/--to-email options, not both.");
  }
  let mapping;
  if (inlineMapping || fileMapping) {
    mapping = loadOptionalJsonInput(
      context,
      options,
      "identity-map-json",
      "identity-map-file",
      "identity migration mapping",
    );
  } else {
    if (!directSource || !directTarget) {
      fail("Identity migration requires --from-email and --to-email, or a declarative --identity-map-json/--identity-map-file mapping.");
    }
    mapping = {
      source: { email: directSource },
      target: { email: directTarget, ...(directName ? { name: directName } : {}) },
    };
  }

  try {
    const governancePolicy = context.config?.governance_policy;
    if (
      options.apply
      && governancePolicy?.kind !== "governance_policy"
      && governancePolicy?.mode === "enforce"
    ) {
      fail(
        "This identity change was not started because its approval records could not be kept safely while the project data is replaced. "
        + "No files were changed. For now, use a reviewed policy embedded in the project configuration, or run the external policy in audit mode.",
      );
    }
    const plan = planIdentityMigration({
      projectRoot: context.root,
      mapping,
      reason: getOptionString(options, "reason"),
    });
    if (options.apply && plan.status === "ready") {
      if (!expectedPlanHash) {
        fail(`Identity migration apply requires --plan-hash ${plan.plan_hash} from the reviewed dry run.`);
      }
      if (expectedPlanHash !== plan.plan_hash) {
        fail(`Identity migration plan changed after preview; expected ${expectedPlanHash}, current ${plan.plan_hash}. Run a new dry run.`);
      }
    }
    const result = options.apply
      ? applyIdentityMigration(plan, {
          mutationGateway: governancePolicy?.kind === "governance_policy"
            ? executePreparedIdentityMutation
            : executeIdentityMutation,
          rebuildDerived: ({
            projectRoot,
            sdlcRoot,
            logicalProjectRoot,
            execution_descriptor: executionDescriptor,
          }) => {
            const stagedContext = { ...context, root: projectRoot, sdlcRoot };
            const cache = buildCache(stagedContext);
            const index = buildIndex(stagedContext);
            cache.root = context.root;
            index.root = context.root;
            const cachePath = path.join(sdlcRoot, "cache", CACHE_FILE_NAME);
            const indexPath = path.join(sdlcRoot, "indexes", "kb-index.json");
            writeJsonFile(cachePath, cache, {
              force: true,
              preparedTempPath: preparedIdentityWritePath(logicalProjectRoot, executionDescriptor, cachePath),
              preauthorizedMutation: governancePolicy?.kind === "governance_policy",
            });
            writeJsonFile(indexPath, index, {
              force: true,
              preparedTempPath: preparedIdentityWritePath(logicalProjectRoot, executionDescriptor, indexPath),
              preauthorizedMutation: governancePolicy?.kind === "governance_policy",
            });
          },
          validateAfter: ({ projectRoot, sdlcRoot }) => {
            const stagedContext = { ...context, root: projectRoot, sdlcRoot };
            const receiptPath = path.join(projectRoot, plan.receipt_path);
            const receipt = readProjectJson(stagedContext, receiptPath);
            const receiptValidation = validateIdentityMigrationReceipt(receipt);
            if (!receiptValidation.valid) {
              throw new IdentityMigrationError(`Migration receipt failed validation: ${receiptValidation.errors.join("; ")}`);
            }
            assertRecordSchema(receipt, "identity-migration-receipt.schema.json", `Identity migration ${receipt.id}`);
            const cacheStatus = getCacheStatus(stagedContext);
            const indexStatus = getIndexStatus(stagedContext);
            if (!cacheStatus.valid || !indexStatus.valid) {
              throw new IdentityMigrationError("Derived cache or index is stale after the migration rebuild.");
            }
          },
        })
      : publicIdentityMigrationPlan(plan);
    output(options, result, [
      result.status === "applied"
        ? `Applied identity migration ${result.id}.`
        : result.status === "ready"
          ? `Planned identity migration ${result.id}; no files were written.`
          : result.status === "already_applied"
            ? `Identity migration ${result.id} was already applied.`
            : "No matching canonical identity values require migration.",
      `Canonical source occurrences: ${result.source_occurrences_before} -> ${result.source_occurrences_after}.`,
      `Changed canonical files: ${result.changed_files.length}; integrity hash rewrites: ${result.hash_rewrites.length}.`,
      `Plan hash: ${result.plan_hash}.`,
      result.receipt_path ? `Lineage receipt: ${result.receipt_path}.` : "No lineage receipt was required.",
      result.status === "ready"
        ? `Re-run the same command with --apply --plan-hash ${result.plan_hash} to apply this reviewed canonical snapshot.`
        : null,
    ].filter(Boolean));
  } catch (error) {
    if (error instanceof IdentityMigrationError) fail(error.message);
    throw error;
  }
}

function buildOutputTemplateContent(context, options, artifactType, id) {
  const from = getOptionString(options, "from");
  const body = getOptionString(options, "body");
  const preset = getOptionString(options, "preset");
  const contentSources = [from, body, preset].filter(Boolean);
  if (contentSources.length > 1) {
    fail("Use only one of --from, --body, or --preset when proposing an output template.");
  }
  if (from) {
    const sourcePath = resolveProjectFilePath(context, from, { mustExist: true, fileOnly: true });
    assertNotDerivedArtifact(context, sourcePath, "Template source");
    return {
      text: fs.readFileSync(sourcePath, "utf8"),
      source_paths: [toProjectPath(context, sourcePath)],
      preset: null,
    };
  }

  if (body) {
    return {
      text: `${body.trim()}\n`,
      source_paths: [],
      preset: null,
    };
  }

  if (preset) {
    const normalizedPreset = String(preset).trim().toLowerCase();
    if (normalizedPreset !== "technical-assessment") {
      fail(`Unknown output template preset '${preset}'. Valid presets: technical-assessment`);
    }
    return {
      text: readTemplateFile(context, "technical-assessment.md"),
      source_paths: [],
      preset: normalizedPreset,
    };
  }

  const summary = getOptionString(options, "summary") || `Project-approved structure for ${artifactType} outputs.`;
  return {
    text: [
      `# ${id}`,
      "",
      "## Purpose",
      summary,
      "",
      "## Context",
      "- Linked story",
      "- Linked requirement or source artifact",
      "- Reused base artifact when this output is a delta",
      "",
      "## Output",
      "- Canonical content agreed with the user",
      "- Explicit delta from the base artifact when applicable",
      "",
      "## Validation",
      "- Acceptance criteria or gate evidence",
      "- Open questions and follow-up decisions",
      "",
    ].join("\n"),
    source_paths: [],
    preset: null,
  };
}

function buildOutputResolution(context, storyId, artifactType, options = {}) {
  const story = options.story || readStory(context, storyId);
  if (!story) {
    fail(`Story ${storyId} does not exist`);
  }
  const registry = options.registry || readOutputRegistry(context, { missingOk: true });
  const registryIndex = options.registry_index || null;
  const storyRequirements = Array.isArray(story.links?.requirements) ? story.links.requirements : [];
  const requirements = options.requirements?.length > 0 ? options.requirements : storyRequirements;
  const templates = registryIndex
    ? registryIndex.templates_by_type.get(artifactType) || []
    : registry ? registry.templates.filter((template) => template.type === artifactType) : [];
  const approvedTemplates = templates.filter((template) => template.status === "approved");
  const existingLinks = registryIndex
    ? registryIndex.links_by_story_and_type.get(outputRegistryPairKey(storyId, artifactType)) || []
    : registry
      ? registry.links.filter((link) => link.story_id === storyId && link.artifact_type === artifactType)
      : [];
  const relatedLinks = registryIndex
    ? relatedOutputLinksFromIndex(registryIndex, storyId, artifactType, requirements)
    : registry
      ? registry.links.filter(
          (link) =>
            link.story_id !== storyId &&
            link.artifact_type === artifactType &&
            overlaps(link.requirements || [], requirements),
        )
      : [];
  const preferredRelated = relatedLinks[0] || null;
  const preferredTemplate = approvedTemplates.find((template) => template.id === preferredRelated?.template_id) || approvedTemplates[0] || null;
  const delivery = preferredTemplate ? effectiveOutputDelivery(preferredTemplate) : null;
  let recommendation = "template_required";
  let nextAction = `Propose and approve a template: agentic-sdlc output template propose --type ${artifactType}`;
  let baseArtifact = null;

  if (existingLinks.length > 0) {
    recommendation = "linked";
    nextAction = "No new artifact is required unless the user agrees on a delta or structure change.";
    baseArtifact = existingLinks[0].base_artifact || existingLinks[0].artifact_path || null;
  } else if (preferredRelated) {
    recommendation = "reuse_delta";
    baseArtifact = preferredRelated.artifact_path;
    nextAction = [
      `Reuse ${preferredRelated.artifact_path} and create only a delta if needed.`,
      `Link it with: agentic-sdlc output link --story ${storyId} --type ${artifactType}`,
      `--artifact <delta-path> --template ${preferredRelated.template_id} --mode delta --base-artifact ${preferredRelated.artifact_path}`,
    ].join(" ");
  } else if (preferredTemplate) {
    recommendation = "new";
    nextAction = [
      "No related approved artifact was found.",
      `Create the ${delivery.label} artifact (${delivery.extension}) with template ${preferredTemplate.id}${delivery.generator ? ` using ${delivery.generator}` : ""}, then link it with mode new.`,
    ].join(" ");
  }

  return {
    story_id: storyId,
    artifact_type: artifactType,
    requirements,
    recommendation,
    template_id: preferredTemplate?.id || existingLinks[0]?.template_id || null,
    delivery,
    approved_templates: approvedTemplates.map((template) => template.id),
    existing_links: existingLinks,
    related_links: relatedLinks,
    base_artifact: baseArtifact,
    cache_used: Boolean(options.cache_used),
    next_action: nextAction,
  };
}

function createOutputRegistryQueryIndex(registry) {
  const templatesByType = new Map();
  const linksByStory = new Map();
  const linksByStoryAndType = new Map();
  const linksByRequirementAndType = new Map();
  const linkOrder = new Map();

  for (const template of registry?.templates || []) {
    const templates = templatesByType.get(template.type) || [];
    templates.push(template);
    templatesByType.set(template.type, templates);
  }
  for (let index = 0; index < (registry?.links || []).length; index += 1) {
    const link = registry.links[index];
    linkOrder.set(link, index);
    const linksForStory = linksByStory.get(link.story_id) || [];
    linksForStory.push(link);
    linksByStory.set(link.story_id, linksForStory);
    const storyKey = outputRegistryPairKey(link.story_id, link.artifact_type);
    const storyLinks = linksByStoryAndType.get(storyKey) || [];
    storyLinks.push(link);
    linksByStoryAndType.set(storyKey, storyLinks);
    for (const requirement of new Set(link.requirements || [])) {
      const requirementKey = outputRegistryPairKey(requirement, link.artifact_type);
      const requirementLinks = linksByRequirementAndType.get(requirementKey) || [];
      requirementLinks.push(link);
      linksByRequirementAndType.set(requirementKey, requirementLinks);
    }
  }

  return {
    templates_by_type: templatesByType,
    links_by_story: linksByStory,
    links_by_story_and_type: linksByStoryAndType,
    links_by_requirement_and_type: linksByRequirementAndType,
    link_order: linkOrder,
  };
}

function relatedOutputLinksFromIndex(index, storyId, artifactType, requirements) {
  const related = new Set();
  for (const requirement of new Set(requirements || [])) {
    const key = outputRegistryPairKey(requirement, artifactType);
    for (const link of index.links_by_requirement_and_type.get(key) || []) {
      if (link.story_id !== storyId) related.add(link);
    }
  }
  return [...related].sort((left, right) => index.link_order.get(left) - index.link_order.get(right));
}

function outputRegistryPairKey(left, right) {
  return `${left ?? ""}\u0000${right ?? ""}`;
}

function buildCache(context) {
  const generatedAt = now();
  const session = openProjectQuerySession(context);
  const sourceSnapshot = collectKnowledgeSourceSnapshot(context, session);
  const sourceFiles = sourceSnapshot.source_paths
    .map((relativePath) => path.join(context.root, ...relativePath.split("/")));
  const sourceHashes = { ...sourceSnapshot.source_hashes };
  const fullTextIndex = [];
  for (const filePath of sourceFiles) {
    const relativePath = toProjectPath(context, filePath);
    const sourceHash = sourceHashes[relativePath];
    const raw = session.readTextAtHash(relativePath, sourceHash);
    fullTextIndex.push({
      path: relativePath,
      title: inferTitle(filePath, raw),
      extension: path.extname(filePath),
      size_bytes: Buffer.byteLength(raw),
      snippet: normalizeText(raw).slice(0, 240),
      search_text: normalizeText(raw),
      source_paths: [relativePath],
      source_hashes: {
        [relativePath]: sourceHash,
      },
      generated_at: generatedAt,
      schema_version: context.config.schema_version,
    });
  }

  const registry = readOutputRegistry(context, { missingOk: true });
  const stories = readAllStories(context, session);
  const registryIndex = createOutputRegistryQueryIndex(registry);
  const templateResolution = buildTemplateResolution(registry);
  const storyRequirementGraph = buildStoryRequirementGraph(stories);
  const dependencyGraph = {
    approved: readDependencyGraph(context, { missingOk: true }),
    derived_story_links: buildStoryDependencyGraph(stories),
  };
  const artifactFingerprints = buildArtifactFingerprints(context, registry);
  const outputResolutions = {};
  const artifactTypes = collectOutputArtifactTypes(context, registry);
  for (const story of stories) {
    for (const artifactType of artifactTypes) {
      outputResolutions[outputResolutionKey(story.id, artifactType)] = buildOutputResolution(context, story.id, artifactType, {
        registry,
        registry_index: registryIndex,
        story,
        cache_used: false,
      });
    }
  }

  return {
    schema_version: context.config.schema_version,
    generated_at: generatedAt,
    root: context.root,
    source_paths: Object.keys(sourceHashes).sort(),
    source_hashes: sourceHashes,
    full_text_index: fullTextIndex,
    story_requirement_graph: storyRequirementGraph,
    artifact_fingerprints: artifactFingerprints,
    template_resolution: templateResolution,
    kb_summaries: fullTextIndex.map((entry) => ({
      path: entry.path,
      title: entry.title,
      snippet: entry.snippet,
      source_paths: entry.source_paths,
      source_hashes: entry.source_hashes,
      generated_at: entry.generated_at,
      schema_version: entry.schema_version,
    })),
    dependency_graph: dependencyGraph,
    output_resolutions: outputResolutions,
  };
}

function getCacheStatus(context) {
  const cachePath = path.join(context.sdlcRoot, "cache", CACHE_FILE_NAME);
  const exists = fs.existsSync(cachePath);
  if (!exists) {
    return {
      exists: false,
      valid: false,
      stale: true,
      cache_path: cachePath,
      changed: [],
      missing: [],
      added: [],
      schema_mismatch: false,
      cache: null,
    };
  }

  let cache;
  try {
    cache = JSON.parse(fs.readFileSync(cachePath, "utf8"));
  } catch (error) {
    return {
      exists: true,
      valid: false,
      stale: true,
      cache_path: cachePath,
      changed: [],
      missing: [],
      added: [],
      schema_mismatch: false,
      parse_error: error.message,
      generated_at: null,
      cache: null,
    };
  }
  const currentHashes = collectKnowledgeSourceSnapshot(
    context,
    openProjectQuerySession(context),
  ).source_hashes;
  const cachedHashes = cache.source_hashes || {};
  const currentPaths = new Set(Object.keys(currentHashes));
  const cachedPaths = new Set(Object.keys(cachedHashes));
  const changed = [];
  const missing = [];
  const added = [];

  for (const cachedPath of cachedPaths) {
    if (!currentPaths.has(cachedPath)) {
      missing.push(cachedPath);
    } else if (cachedHashes[cachedPath] !== currentHashes[cachedPath]) {
      changed.push(cachedPath);
    }
  }
  for (const currentPath of currentPaths) {
    if (!cachedPaths.has(currentPath)) {
      added.push(currentPath);
    }
  }
  const schemaMismatch = cache.schema_version !== context.config.schema_version;
  const structureErrors = validateCacheMetadata(context, cache);
  const valid = changed.length === 0 && missing.length === 0 && added.length === 0 && !schemaMismatch && structureErrors.length === 0;
  return {
    exists: true,
    valid,
    stale: !valid,
    cache_path: cachePath,
    changed,
    missing,
    added,
    schema_mismatch: schemaMismatch,
    structure_errors: structureErrors,
    generated_at: cache.generated_at || null,
    cache,
  };
}

function validateCacheMetadata(context, cache) {
  const errors = [];
  const required = context.config.cache_policy?.required_entry_metadata || [
    "source_paths",
    "source_hashes",
    "generated_at",
    "schema_version",
  ];
  for (const [collectionName, entries] of Object.entries({
    full_text_index: cache.full_text_index,
    kb_summaries: cache.kb_summaries,
  })) {
    if (!Array.isArray(entries)) {
      errors.push(`${collectionName} must be an array`);
      continue;
    }
    entries.forEach((entry, index) => {
      for (const field of required) {
        if (entry[field] === undefined || entry[field] === null) {
          errors.push(`${collectionName}[${index}] is missing ${field}`);
        }
      }
      for (const sourcePath of entry.source_paths || []) {
        const resolved = resolveProjectFilePath(context, sourcePath, { mustExist: false });
        if (isDerivedArtifactPath(context, resolved)) {
          errors.push(`${collectionName}[${index}] uses derived source ${sourcePath}`);
        }
      }
    });
  }
  return errors;
}

function outputContractsRoot(context) {
  return path.join(context.sdlcRoot, "output-contracts");
}

function configuredSdlcDirectory(context, configuredValue, fallback, label) {
  const raw = String(configuredValue || fallback).trim().replaceAll("\\", "/");
  const relative = raw.startsWith(`${SDLC_DIR}/`) ? raw.slice(`${SDLC_DIR}/`.length) : raw;
  assertSafeSdlcRelativeDirectory(relative, label);
  return path.join(context.sdlcRoot, relative);
}

function verificationReceiptsRoot(context) {
  return configuredSdlcDirectory(
    context,
    context.config.verification_policy?.receipt_directory,
    "receipts/verification",
    "verification_policy.receipt_directory",
  );
}

function verificationReceiptPath(context, id) {
  return path.join(verificationReceiptsRoot(context), `${normalizeId(id)}.json`);
}

function outputRegistryPath(context) {
  return path.join(outputContractsRoot(context), "registry.json");
}

function readOutputRegistry(context, options = {}) {
  const registryPath = outputRegistryPath(context);
  if (!fs.existsSync(registryPath)) {
    if (options.create) {
      return initializeOutputContracts(context, {
        force: false,
        attribution: buildAttribution(context, options.options || {}, options.action || "output.registry.init"),
      });
    }
    if (options.missingOk) {
      return null;
    }
    fail("Output registry does not exist. Run 'agentic-sdlc init' or create it with output template propose.");
  }
  const registry = readProjectJson(context, registryPath);
  registry.templates = Array.isArray(registry.templates) ? registry.templates : [];
  registry.links = Array.isArray(registry.links) ? registry.links : [];
  registry.decisions = Array.isArray(registry.decisions) ? registry.decisions : [];
  return registry;
}

function writeOutputRegistry(context, registry) {
  writeJsonFile(outputRegistryPath(context), registry, { force: true });
}

function withOutputRegistryLock(context, callback) {
  const releaseLock = acquireFileLock(path.join(outputContractsRoot(context), "registry.lock"));
  try {
    return callback();
  } finally {
    releaseLock();
  }
}

function findOutputTemplate(registry, id) {
  return (registry.templates || []).find((template) => template.id === id) || null;
}

function normalizeArtifactType(value) {
  const normalized = String(value || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "-");
  if (!/^[a-z0-9][a-z0-9._-]*$/.test(normalized)) {
    fail(`Invalid artifact type '${value}'. Use lowercase letters, numbers, dots, underscores, and hyphens.`);
  }
  return normalized;
}

function normalizeOutputMode(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (!OUTPUT_LINK_MODES.has(normalized)) {
    fail(`Invalid output mode '${value}'. Valid modes: ${Array.from(OUTPUT_LINK_MODES).join(", ")}`);
  }
  return normalized;
}

function buildOutputDelivery(options = {}, fallback = null) {
  const requestedFormat = getOptionString(options, "format");
  const formatAlias = String(requestedFormat || fallback?.format || "markdown").trim().toLowerCase();
  const format = OUTPUT_FORMAT_ALIASES[formatAlias];
  if (!format || !OUTPUT_FORMATS[format]) {
    fail(`Invalid output format '${requestedFormat || formatAlias}'. Valid formats: ${Object.keys(OUTPUT_FORMATS).join(", ")}`);
  }

  const descriptor = OUTPUT_FORMATS[format];
  const requestedMode = getOptionString(options, "delivery") || fallback?.mode || "artifact-plus-chat-summary";
  const mode = String(requestedMode).trim().toLowerCase();
  if (!OUTPUT_DELIVERY_MODES.has(mode)) {
    fail(`Invalid delivery mode '${requestedMode}'. Valid modes: ${Array.from(OUTPUT_DELIVERY_MODES).join(", ")}`);
  }

  const requestedExtension = normalizeOutputExtension(getOptionString(options, "extension") || fallback?.extension || descriptor.extension);
  const requestedMediaType = getOptionString(options, "media-type") || fallback?.media_type || descriptor.media_type;
  const requestedGenerator = getOptionString(options, "generator") || fallback?.generator || descriptor.generator;

  if (format !== "custom") {
    if (getOptionString(options, "extension") && requestedExtension !== descriptor.extension) {
      fail(`Output format ${format} requires extension ${descriptor.extension}; received ${requestedExtension}.`);
    }
    if (getOptionString(options, "media-type") && requestedMediaType !== descriptor.media_type) {
      fail(`Output format ${format} requires media type ${descriptor.media_type}; received ${requestedMediaType}.`);
    }
    if (getOptionString(options, "generator") && requestedGenerator !== descriptor.generator) {
      fail(`Output format ${format} uses generator ${descriptor.generator || "none"}; received ${requestedGenerator}.`);
    }
  } else if (!requestedExtension) {
    fail("Custom output format requires --extension (for example --extension .drawio). ");
  }

  return {
    format,
    label: descriptor.label,
    extension: format === "custom" ? requestedExtension : descriptor.extension,
    media_type: format === "custom" ? requestedMediaType : descriptor.media_type,
    generator: format === "custom" ? requestedGenerator : descriptor.generator,
    mode,
  };
}

function normalizeOutputExtension(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }
  const extension = String(value).trim().toLowerCase();
  if (!/^\.[a-z0-9][a-z0-9._-]*$/.test(extension)) {
    fail(`Invalid output extension '${value}'. Use a value such as .md, .xlsx, or .drawio.`);
  }
  return extension;
}

function effectiveOutputDelivery(template = {}) {
  return buildOutputDelivery({}, template.delivery || null);
}

function outputDeliveryIsFresh(template = {}) {
  if (!template.delivery) {
    return true;
  }
  return Boolean(
    template.approved_delivery_hash &&
    template.approved_delivery_hash === hashApprovalSubject(effectiveOutputDelivery(template)),
  );
}

function formatOutputDeliveryForHuman(delivery) {
  return [
    `${delivery.label} (${delivery.extension})`,
    delivery.generator ? `created with the ${delivery.generator} artifact capability` : "created directly",
    delivery.mode === "artifact-plus-chat-summary" ? "plus a concise chat summary" : "as the canonical file",
  ].join(", ");
}

function validateArtifactDeliveryPath(artifactPath, delivery, label = "Output") {
  if (!delivery.extension) {
    return;
  }
  if (!String(artifactPath).toLowerCase().endsWith(delivery.extension.toLowerCase())) {
    fail(`${label} requires a ${delivery.extension} canonical artifact, but received ${path.basename(artifactPath)}.`);
  }
}

function verificationArtifactSha256(receipt = {}) {
  return receipt.artifact?.sha256 || receipt.artifact_sha256 || null;
}

function verificationArtifactFormat(receipt = {}) {
  return receipt.artifact?.format || receipt.format || null;
}

function verificationDimensionStatus(receipt = {}, dimension) {
  const value = receipt[dimension]?.status;
  if (value === "passed") {
    return "verified";
  }
  if (value === "not_required") {
    return "not-required";
  }
  return value || null;
}

function verificationReceiptSatisfies(receipt, { visual = false } = {}) {
  if (!receipt || receipt.status !== "passed") {
    return false;
  }
  return (
    verificationDimensionStatus(receipt, "container_verified") === "verified" &&
    verificationDimensionStatus(receipt, "content_verified") === "verified" &&
    verificationDimensionStatus(receipt, "render_verified") === (visual ? "verified" : "not-required")
  );
}

function verifyOutputArtifact(context, artifactPath, delivery, options = {}) {
  const stat = fs.statSync(artifactPath);
  if (!stat.isFile() || stat.size === 0) {
    fail(`Output artifact ${path.basename(artifactPath)} is empty or is not a file.`);
  }
  const containerChecks = [`non-empty file (${stat.size} bytes)`, `extension ${delivery.extension}`];
  const contentChecks = [];
  let verifier = "file-structure-v1";

  if (["docx", "xlsx", "pptx"].includes(delivery.format)) {
    verifier = "ooxml-content-v2";
    const requiredEntries = {
      docx: ["[Content_Types].xml", "word/document.xml"],
      xlsx: ["[Content_Types].xml", "xl/workbook.xml"],
      pptx: ["[Content_Types].xml", "ppt/presentation.xml"],
    }[delivery.format];
    const entries = inspectZipContainer(artifactPath, requiredEntries);
    containerChecks.push(`valid OOXML ZIP container with ${entries.size} entries`);
    containerChecks.push(...requiredEntries.map((entry) => `contains ${entry}`));
    const rootEntry = requiredEntries[1];
    const xml = readZipEntry(artifactPath, entries.get(rootEntry)).toString("utf8");
    const rootPatterns = {
      docx: /<(?:\w+:)?document\b/i,
      xlsx: /<(?:\w+:)?workbook\b/i,
      pptx: /<(?:\w+:)?presentation\b/i,
    };
    if (!rootPatterns[delivery.format].test(xml)) {
      fail(`${delivery.label} artifact has ${rootEntry}, but it does not contain the expected XML root.`);
    }
    containerChecks.push(`valid ${rootEntry} root`);
    contentChecks.push(...verifyOoxmlSemanticContent(artifactPath, entries, delivery.format, xml));
  } else if (delivery.format === "pdf") {
    verifier = "pdf-content-v2";
    const bytes = fs.readFileSync(artifactPath);
    const pdfText = bytes.toString("latin1");
    if (!bytes.subarray(0, 8).toString("latin1").startsWith("%PDF-")) {
      fail("PDF artifact is missing a valid %PDF header.");
    }
    if (!bytes.subarray(Math.max(0, bytes.length - 2048)).toString("latin1").includes("%%EOF")) {
      fail("PDF artifact is missing its %%EOF marker.");
    }
    if (!/startxref\s+\d+\s+%%EOF\s*$/s.test(pdfText.slice(-4096))) {
      fail("PDF artifact is missing a valid startxref/EOF trailer.");
    }
    if (!/\/Type\s*\/Pages?\b/.test(pdfText)) {
      fail("PDF artifact has no page tree or page object, so it cannot be content-verified.");
    }
    containerChecks.push("valid PDF header, page objects, startxref, and EOF marker");
    contentChecks.push("contains at least one PDF page object");
  } else if (delivery.format === "json") {
    verifier = "json-parse-v1";
    try {
      const parsed = JSON.parse(fs.readFileSync(artifactPath, "utf8"));
      if (parsed === null || (Array.isArray(parsed) && parsed.length === 0) || (!Array.isArray(parsed) && typeof parsed === "object" && Object.keys(parsed).length === 0)) {
        fail("JSON output is structurally valid but contains no content.");
      }
    } catch (error) {
      if (error instanceof UserError) {
        throw error;
      }
      fail(`JSON output is not valid: ${error.message}`);
    }
    containerChecks.push("valid JSON syntax");
    contentChecks.push("non-empty JSON value");
  } else if (delivery.format === "html") {
    verifier = "html-structure-v1";
    const html = fs.readFileSync(artifactPath, "utf8");
    if (!/<(?:!doctype\s+html|html|body|main)\b/i.test(html)) {
      fail("HTML output does not contain an HTML document structure.");
    }
    const visibleText = html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ").replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
    if (visibleText.length < 20) {
      fail("HTML output has document markup but no meaningful visible content.");
    }
    containerChecks.push("recognizable HTML document structure");
    contentChecks.push("meaningful visible HTML text");
  } else if (delivery.format === "csv") {
    verifier = "csv-structure-v1";
    const csv = fs.readFileSync(artifactPath, "utf8");
    const rows = csv.split(/\r?\n/).filter((row) => row.trim());
    if (csv.includes("\u0000") || !/[;,\t]/.test(rows[0] || "")) {
      fail("CSV output does not contain a valid text header with a delimiter.");
    }
    if (rows.length < 2) {
      fail("CSV output has a header but no content row.");
    }
    containerChecks.push("text CSV header with delimiter");
    contentChecks.push(`${rows.length - 1} data row(s)`);
  } else if (["markdown", "custom"].includes(delivery.format)) {
    const bytes = fs.readFileSync(artifactPath);
    if (bytes.includes(0)) {
      fail(`${delivery.label} output contains binary NUL bytes.`);
    }
    const text = bytes.toString("utf8").trim();
    if (text.length < 20) {
      fail(`${delivery.label} output is structurally readable but has too little content to verify.`);
    }
    containerChecks.push("non-binary text content");
    contentChecks.push("non-empty meaningful text content");
  }

  const evidence = normalizeListValue(options.evidence, []).map((rawPath) => {
    const evidencePath = resolveProjectFilePath(context, rawPath, { mustExist: true, fileOnly: true });
    assertNotDerivedArtifact(context, evidencePath, "Output verification evidence");
    if (fs.realpathSync.native(evidencePath) === fs.realpathSync.native(artifactPath)) {
      fail("Render verification evidence must be a separate render or visual-inspection record, not the output artifact itself.");
    }
    const extension = path.extname(evidencePath).toLowerCase();
    const visualExtensions = new Set([".png", ".jpg", ".jpeg", ".webp", ".pdf"]);
    let evidenceKind = "render";
    if (extension === ".json") {
      const record = readProjectJson(context, evidencePath);
      assertRecordSchema(
        record,
        "render-verification-receipt.schema.json",
        `Render verification receipt ${toProjectPath(context, evidencePath)}`,
      );
      const { receipt_hash: receiptHash, hash_algorithm: algorithm, ...hashSubject } = record;
      if (algorithm !== "sha256:stable-json:v1" || receiptHash !== shortHashFull(stableJson(hashSubject))) {
        fail(`Render verification receipt ${toProjectPath(context, evidencePath)} failed immutable content validation.`);
      }
      if (
        record.kind !== "render_verification_receipt" ||
        record.status !== "passed" ||
        record.artifact_sha256 !== hashFile(artifactPath) ||
        record.artifact_path !== toProjectPath(context, artifactPath)
      ) {
        fail(`Render verification receipt ${toProjectPath(context, evidencePath)} must be passed and bound to the current artifact path and hash.`);
      }
      if (record.render_ref) {
        const renderPath = resolveProjectFilePath(context, record.render_ref.path, { mustExist: true, fileOnly: true });
        assertNotDerivedArtifact(context, renderPath, "Rendered verification evidence");
        if (hashFile(renderPath) !== record.render_ref.sha256) {
          fail(`Render verification receipt ${toProjectPath(context, evidencePath)} references stale render evidence.`);
        }
        const renderExtension = path.extname(renderPath).toLowerCase();
        if (!visualExtensions.has(renderExtension)) {
          fail(`Render verification receipt ${toProjectPath(context, evidencePath)} references a non-visual render file.`);
        }
        verifyVisualEvidenceFile(renderPath, renderExtension);
      }
      evidenceKind = "typed_render_receipt";
    } else if (!visualExtensions.has(extension)) {
      fail(`Render verification evidence ${toProjectPath(context, evidencePath)} is not a render. Use --render-evidence with a PNG/JPEG/WebP/PDF render or a typed render-verification-receipt:v1 JSON file; a functional test result or text assertion is not sufficient.`);
    } else {
      verifyVisualEvidenceFile(evidencePath, extension);
    }
    return {
      path: toProjectPath(context, evidencePath),
      sha256: hashFile(evidencePath),
      kind: evidenceKind,
    };
  });
  if (options.requireVisualEvidence && OUTPUT_VISUAL_FORMATS.has(delivery.format) && evidence.length === 0) {
    fail(
      `${delivery.label} output requires --render-evidence <render-or-visual-check-file> before it can be linked as canonical. `
      + "This flag is only for render or visual verification; record functional and test evidence with story complete-step or trace append. "
      + "The legacy --evidence name remains accepted for compatibility.",
    );
  }
  const generatorReceipt = delivery.generator
    ? readArtifactGeneratorReceipt(context, options.receiptFile, artifactPath, delivery)
    : null;

  const verifiedAt = now();
  const visual = OUTPUT_VISUAL_FORMATS.has(delivery.format);
  const artifactSha256 = hashFile(artifactPath);
  const receiptId = normalizeId(
    options.id || `VERIFY-${shortHash(`${toProjectPath(context, artifactPath)}:${artifactSha256}`)}`,
  );
  const dimension = (status, checks, dimensionEvidence = [], dimensionVerifier = verifier, reason = null) => ({
    status,
    verifier: dimensionVerifier,
    checks,
    evidence: dimensionEvidence,
    verified_at: status === "verified" ? verifiedAt : null,
    reason,
  });
  const receipt = buildVerificationReceipt({
    id: receiptId,
    subject_ref: options.subjectRef || {
      kind: "output_artifact",
      id: `ARTIFACT-${shortHash(toProjectPath(context, artifactPath))}`,
      path: toProjectPath(context, artifactPath),
      hash: artifactSha256,
    },
    artifact: {
      path: toProjectPath(context, artifactPath),
      sha256: artifactSha256,
      format: delivery.format,
      media_type: delivery.media_type,
    },
    generator_receipt: generatorReceipt,
    required_level: visual ? "rendered" : "semantic",
    dimensions: {
      existence: dimension("verified", [`non-empty file (${stat.size} bytes)`], [], "file-existence-v1"),
      container: dimension("verified", containerChecks),
      content: dimension("verified", contentChecks.length ? contentChecks : ["non-empty content"]),
      render: visual
        ? dimension("verified", [`${evidence.length} typed or visual render evidence file(s)`], evidence, "render-evidence-v1")
        : dimension("not-required", [], [], "render-evidence-v1", "Approved format does not require rendered verification."),
      independent: dimension(
        "not-required",
        [],
        [],
        null,
        "Independent verification is outside the approved verification level.",
      ),
    },
    evidence,
    limitations: visual ? [] : ["Rendered and independent verification were not required by this output contract."],
    verified_at: verifiedAt,
    verifier,
    extensions: {
      delivery_label: delivery.label,
      delivery_mode: delivery.mode,
      size_bytes: stat.size,
    },
  });
  const integrity = validateVerificationReceiptIntegrity(receipt);
  if (!integrity.valid) {
    fail(`Generated verification receipt is invalid: ${integrity.errors.join("; ")}`);
  }
  return receipt;
}

function verifyOoxmlSemanticContent(filePath, entries, format, rootXml) {
  if (format === "docx") {
    const text = Array.from(rootXml.matchAll(/<(?:\w+:)?t(?:\s[^>]*)?>([\s\S]*?)<\/(?:\w+:)?t>/gi))
      .map((match) => match[1].replace(/<[^>]+>/g, " ").trim())
      .filter(Boolean)
      .join(" ");
    if (text.length < 20) {
      fail(`${path.basename(filePath)} has a Word document container but no meaningful document text.`);
    }
    return [`Word document contains ${text.length} visible text character(s)`];
  }
  if (format === "xlsx") {
    const sheetDeclarations = Array.from(rootXml.matchAll(/<(?:\w+:)?sheet\b/gi)).length;
    const worksheetEntries = Array.from(entries.keys()).filter((name) => /^xl\/worksheets\/sheet\d+\.xml$/i.test(name));
    if (sheetDeclarations === 0 || worksheetEntries.length === 0) {
      fail(`${path.basename(filePath)} has a workbook container but no declared worksheet.`);
    }
    const populated = worksheetEntries.filter((name) => {
      const xml = readZipEntry(filePath, entries.get(name)).toString("utf8");
      return /<(?:\w+:)?c\b|<(?:\w+:)?v\b|<(?:\w+:)?is\b/i.test(xml);
    });
    if (populated.length === 0) {
      fail(`${path.basename(filePath)} declares worksheet(s), but none contains cells or values.`);
    }
    return [`workbook declares ${sheetDeclarations} sheet(s)`, `${populated.length} worksheet(s) contain cells or values`];
  }
  const slideDeclarations = Array.from(rootXml.matchAll(/<(?:\w+:)?sldId\b/gi)).length;
  const slideEntries = Array.from(entries.keys()).filter((name) => /^ppt\/slides\/slide\d+\.xml$/i.test(name));
  if (slideDeclarations === 0 || slideEntries.length === 0) {
    fail(`${path.basename(filePath)} has a presentation container but no slide.`);
  }
  const visibleText = slideEntries.flatMap((name) => {
    const xml = readZipEntry(filePath, entries.get(name)).toString("utf8");
    return Array.from(xml.matchAll(/<(?:\w+:)?t(?:\s[^>]*)?>([\s\S]*?)<\/(?:\w+:)?t>/gi)).map((match) => match[1].trim());
  }).filter(Boolean).join(" ");
  if (visibleText.length < 20) {
    fail(`${path.basename(filePath)} contains slide containers but no meaningful slide text.`);
  }
  return [`presentation declares ${slideDeclarations} slide(s)`, `slides contain ${visibleText.length} visible text character(s)`];
}

function verifyVisualEvidenceFile(filePath, extension) {
  const bytes = fs.readFileSync(filePath);
  if (bytes.length < 32) {
    fail(`Visual evidence ${path.basename(filePath)} is empty or truncated.`);
  }
  try {
    if (extension === ".png") {
      inspectPngEvidence(bytes);
    } else if ([".jpg", ".jpeg"].includes(extension)) {
      inspectJpegEvidence(bytes);
    } else if (extension === ".webp") {
      inspectWebpEvidence(bytes);
    } else if (extension === ".pdf") {
      inspectPdfEvidence(bytes);
    } else {
      fail(`Unsupported visual evidence extension ${extension}.`);
    }
  } catch (error) {
    if (error instanceof UserError) {
      throw error;
    }
    fail(`Visual evidence ${path.basename(filePath)} is not a structurally valid ${extension} render: ${error.message}`);
  }
}

function readArtifactGeneratorReceipt(context, receiptFile, artifactPath, delivery) {
  const required = context.config.verification_policy?.require_generator_receipt !== false;
  if (!receiptFile) {
    if (required) {
      fail(`${delivery.label} requires --receipt-file <artifact-generator-receipt.json> proving which capability generated this exact artifact.`);
    }
    return null;
  }
  const filePath = resolveProjectFilePath(context, receiptFile, { mustExist: true, fileOnly: true });
  assertNotDerivedArtifact(context, filePath, "Artifact generator receipt");
  const receipt = readProjectJson(context, filePath);
  assertRecordSchema(receipt, "artifact-generator-receipt.schema.json", `Generator receipt ${toProjectPath(context, filePath)}`);
  const { receipt_hash: receiptHash, hash_algorithm: _algorithm, ...hashSubject } = receipt;
  if (receiptHash !== shortHashFull(stableJson(hashSubject))) {
    fail(`Generator receipt ${toProjectPath(context, filePath)} failed its immutable content hash check.`);
  }
  const generatorName = typeof receipt.generator === "string" ? receipt.generator : receipt.generator?.name;
  if (generatorName !== delivery.generator) {
    fail(`Generator receipt names '${generatorName || "unknown"}', but approved delivery requires '${delivery.generator}'.`);
  }
  if (receipt.artifact_sha256 !== hashFile(artifactPath)) {
    fail(`Generator receipt is not bound to the current ${path.basename(artifactPath)} hash.`);
  }
  if (receipt.artifact_path && receipt.artifact_path !== toProjectPath(context, artifactPath)) {
    fail(`Generator receipt artifact_path '${receipt.artifact_path}' does not match '${toProjectPath(context, artifactPath)}'.`);
  }
  return {
    id: receipt.id,
    path: toProjectPath(context, filePath),
    hash: receipt.receipt_hash,
  };
}

function inspectZipContainer(filePath, requiredEntries = []) {
  return withEvidenceFormatFailure(() => inspectZipContainerStructure(filePath, requiredEntries));
}

function readZipEntry(filePath, entry) {
  return withEvidenceFormatFailure(() => readZipEntryBytes(filePath, entry));
}

function withEvidenceFormatFailure(operation) {
  try {
    return operation();
  } catch (error) {
    if (error instanceof EvidenceFormatError) fail(error.message);
    throw error;
  }
}

function resolveProjectFilePath(context, rawPath, options = {}) {
  const value = normalizeProjectPathInput(rawPath);
  if (!value) {
    fail("Path value cannot be empty");
  }
  const resolved = path.isAbsolute(value) ? path.resolve(value) : path.resolve(context.root, value);
  assertPathInsideRoot(context, resolved, value);
  if (options.mustExist && !fs.existsSync(resolved)) {
    fail(`Path does not exist: ${value}`);
  }
  if (fs.existsSync(resolved)) {
    const realRoot = fs.realpathSync.native(context.root);
    const realResolved = fs.realpathSync.native(resolved);
    if (!isInsidePath(realRoot, realResolved)) {
      fail(`Path resolves outside the target project root: ${value}`);
    }
    const stat = fs.statSync(resolved);
    if (options.fileOnly && !stat.isFile()) {
      fail(`Path is not a file: ${value}`);
    }
    if (options.directoryOnly && !stat.isDirectory()) {
      fail(`Path is not a directory: ${value}`);
    }
  } else {
    const nearestParent = nearestExistingParent(resolved);
    const realRoot = fs.realpathSync.native(context.root);
    const realParent = fs.realpathSync.native(nearestParent);
    if (!isInsidePath(realRoot, realParent)) {
      fail(`Path parent resolves outside the target project root: ${value}`);
    }
  }
  return resolved;
}

function normalizeProjectPathInput(rawPath) {
  return String(rawPath || "").trim().replace(/\\/g, "/");
}

function nearestExistingParent(filePath) {
  let current = path.dirname(path.resolve(filePath));
  while (!fs.existsSync(current)) {
    const next = path.dirname(current);
    if (next === current) {
      return current;
    }
    current = next;
  }
  return current;
}

function assertPathInsideRoot(context, resolvedPath, label) {
  if (!isInsidePath(context.root, resolvedPath)) {
    fail(`Path must stay inside the target project root: ${label}`);
  }
}

function toProjectPath(context, filePath) {
  return path.relative(context.root, path.resolve(filePath)).split(path.sep).join("/");
}

function isDerivedArtifactPath(context, filePath) {
  if (!isInsidePath(context.sdlcRoot, filePath)) {
    return false;
  }
  const relative = path.relative(context.sdlcRoot, path.resolve(filePath));
  const first = relative.split(path.sep)[0];
  const derived = new Set(context.config.cache_policy?.derived_directories || ["cache", "indexes"]);
  return derived.has(first);
}

function assertNotDerivedArtifact(context, filePath, label) {
  if (isDerivedArtifactPath(context, filePath)) {
    fail(`${label} cannot be under .sdlc/cache or .sdlc/indexes because those directories are derived artifacts.`);
  }
}

function upsertById(items, item) {
  const index = items.findIndex((candidate) => candidate.id === item.id);
  if (index >= 0) {
    items[index] = item;
  } else {
    items.push(item);
  }
}

function outputStatusTypes(context, registry, options = {}) {
  const explicitTypes = normalizeListOption(options.type).map(normalizeArtifactType);
  if (explicitTypes.length > 0) {
    return explicitTypes;
  }
  const story = options.story || null;
  if (story) {
    const activeTypes = new Set(
      (registry?.links || [])
        .filter((link) => link.story_id === story.id)
        .map((link) => link.artifact_type)
        .filter(Boolean)
        .map(normalizeArtifactType),
    );
    const contract = story.contract_id
      ? readContractById(context, story.contract_id, { missingOk: true })
      : null;
    for (const ref of contract?.output_contract_refs || []) {
      if (ref.artifact_type) activeTypes.add(normalizeArtifactType(ref.artifact_type));
    }
    if (activeTypes.size > 0) {
      return Array.from(activeTypes).sort();
    }
  }
  return collectOutputArtifactTypes(context, registry);
}

function collectOutputArtifactTypes(context, registry) {
  const types = new Set();
  for (const type of context.config.output_consistency_policy?.artifact_types || []) {
    types.add(normalizeArtifactType(type));
  }
  if (registry) {
    for (const template of registry.templates || []) {
      if (template.type) {
        types.add(normalizeArtifactType(template.type));
      }
    }
    for (const link of registry.links || []) {
      if (link.artifact_type) {
        types.add(normalizeArtifactType(link.artifact_type));
      }
    }
  }
  return Array.from(types).sort();
}

function outputResolutionKey(storyId, artifactType) {
  return `${storyId}::${artifactType}`;
}

function openProjectQuerySession(context) {
  return openCanonicalQuerySession({
    root: context.root,
    canonicalRoot: SDLC_DIR,
    derivedDirectories: context.config.cache_policy?.derived_directories,
  });
}

function knowledgeSourceRoots(context) {
  const sourceDirs = context.config.cache_policy?.source_of_truth_dirs || [
    "contracts",
    "requirements",
    "stories",
    "decisions",
    "tests",
    "traces",
    "handoffs",
    "output-contracts",
    "work-items",
    "work-breakdown",
    "dependencies",
    "assumptions",
    "risks",
    "locks",
    "orchestration",
    "releases",
    "manifests",
    "archive",
    "reports",
  ];
  return ["project.json", ...sourceDirs];
}

function collectKnowledgeSourceSnapshot(context, session = openProjectQuerySession(context)) {
  return session.sourceSnapshot({
    under: knowledgeSourceRoots(context),
    extensions: context.config.indexable_extensions,
  });
}

function collectKnowledgeSourceFiles(context, session = null) {
  if (session) {
    return collectKnowledgeSourceSnapshot(context, session).source_paths
      .map((relativePath) => path.join(context.root, ...relativePath.split("/")));
  }
  const sourceDirs = knowledgeSourceRoots(context).filter((directory) => directory !== "project.json");
  const files = [];
  const rootFiles = [path.join(context.sdlcRoot, "project.json")].filter((filePath) => fs.existsSync(filePath));
  files.push(...rootFiles);
  for (const directory of sourceDirs) {
    const dirPath = path.join(context.sdlcRoot, directory);
    if (!fs.existsSync(dirPath)) {
      continue;
    }
    for (const filePath of walkFiles(dirPath)) {
      if (shouldIndexFile(context, filePath)) {
        files.push(filePath);
      }
    }
  }
  return Array.from(new Set(files)).sort((a, b) => a.localeCompare(b));
}

function shouldIndexFile(context, filePath) {
  if (isDerivedArtifactPath(context, filePath)) {
    return false;
  }
  const extension = path.extname(filePath);
  return context.config.indexable_extensions.includes(extension);
}

function readAllStories(context, session = null) {
  if (session) {
    return session.stories()
      .map(normalizeStoryRecord)
      .sort((a, b) => String(a.id).localeCompare(String(b.id)));
  }
  const storiesRoot = path.join(context.sdlcRoot, "stories");
  return safeReadDir(storiesRoot)
    .map((entry) => {
      const storyPath = path.join(storiesRoot, entry, "story.json");
      return fs.existsSync(storyPath) ? readProjectJson(context, storyPath) : null;
    })
    .filter(Boolean)
    .sort((a, b) => String(a.id).localeCompare(String(b.id)));
}

function buildTemplateResolution(registry) {
  const result = {};
  for (const template of registry?.templates || []) {
    const type = template.type || "unknown";
    result[type] = result[type] || {
      approved_template_ids: [],
      draft_template_ids: [],
      default_template_id: null,
    };
    if (template.status === "approved") {
      result[type].approved_template_ids.push(template.id);
      result[type].default_template_id = result[type].default_template_id || template.id;
    } else {
      result[type].draft_template_ids.push(template.id);
    }
  }
  return result;
}

function buildStoryRequirementGraph(stories) {
  return stories.map((story) => ({
    story_id: story.id,
    requirements: Array.isArray(story.links?.requirements) ? story.links.requirements : [],
  }));
}

function buildStoryDependencyGraph(stories) {
  const nodes = stories.map((story) => story.id);
  const storyIndexesByRequirement = new Map();
  for (let storyIndex = 0; storyIndex < stories.length; storyIndex += 1) {
    const requirements = new Set(stories[storyIndex].links?.requirements || []);
    for (const requirement of requirements) {
      const indexes = storyIndexesByRequirement.get(requirement) || [];
      indexes.push(storyIndex);
      storyIndexesByRequirement.set(requirement, indexes);
    }
  }

  // Build only pairs that actually share a requirement. The previous
  // implementation compared every story with every other story even when the
  // graph was sparse, which became the dominant cache-build cost at scale.
  const sharedByPair = new Map();
  for (const [requirement, indexes] of storyIndexesByRequirement) {
    for (let leftOffset = 0; leftOffset < indexes.length; leftOffset += 1) {
      for (let rightOffset = leftOffset + 1; rightOffset < indexes.length; rightOffset += 1) {
        const left = indexes[leftOffset];
        const right = indexes[rightOffset];
        const key = `${left}\u0000${right}`;
        const shared = sharedByPair.get(key) || new Set();
        shared.add(requirement);
        sharedByPair.set(key, shared);
      }
    }
  }

  const edges = [...sharedByPair.entries()]
    .map(([key, shared]) => {
      const [left, right] = key.split("\u0000").map(Number);
      const requirements = [];
      const emitted = new Set();
      for (const requirement of stories[left].links?.requirements || []) {
        if (shared.has(requirement) && !emitted.has(requirement)) {
          requirements.push(requirement);
          emitted.add(requirement);
        }
      }
      return {
        left,
        right,
        edge: {
          from: stories[left].id,
          to: stories[right].id,
          reason: "shared_requirements",
          requirements,
        },
      };
    })
    .sort((first, second) => first.left - second.left || first.right - second.right)
    .map(({ edge }) => edge);
  return { nodes, edges };
}

function buildArtifactFingerprints(context, registry) {
  const paths = new Set();
  for (const template of registry?.templates || []) {
    if (template.path) {
      paths.add(template.path);
    }
  }
  for (const link of registry?.links || []) {
    if (link.artifact_path) {
      paths.add(link.artifact_path);
    }
    if (link.base_artifact) {
      paths.add(link.base_artifact);
    }
  }
  return Array.from(paths)
    .sort()
    .map((relativePath) => {
      const filePath = resolveProjectFilePath(context, relativePath, { mustExist: false });
      return {
        path: relativePath,
        exists: fs.existsSync(filePath),
        sha256: fs.existsSync(filePath) ? hashFile(filePath) : null,
        size_bytes: fs.existsSync(filePath) ? fs.statSync(filePath).size : null,
      };
    });
}

function findRelatedOutputLinks(registry, link) {
  const requirements = link.requirements || [];
  return (registry.links || []).filter((candidate) => {
    if (candidate.id === link.id || candidate.artifact_type !== link.artifact_type) {
      return false;
    }
    if (overlaps(candidate.requirements || [], requirements)) {
      return true;
    }
    if (link.base_artifact && candidate.artifact_path === link.base_artifact) {
      return true;
    }
    return candidate.artifact_path && candidate.artifact_path === link.artifact_path;
  });
}

function overlaps(left, right) {
  if (!Array.isArray(left) || !Array.isArray(right) || left.length === 0 || right.length === 0) {
    return false;
  }
  const rightSet = new Set(right);
  return left.some((item) => rightSet.has(item));
}

function hasApprovedOutputDecision(decisions, decisionId) {
  if (!decisionId) {
    return false;
  }
  return decisions.some(
    (decision) =>
      decision.id === decisionId &&
      decision.status === "approved" &&
      ["output_link_override", "duplicate_output_approved"].includes(decision.type),
  );
}

function findUnlinkedStoryOutputCandidates(context, storyId) {
  const storyDir = path.join(context.sdlcRoot, "stories", storyId);
  const outputsDir = path.join(storyDir, "outputs");
  if (!fs.existsSync(outputsDir)) {
    return [];
  }
  const registry = readOutputRegistry(context, { missingOk: true });
  const linked = new Set((registry?.links || []).filter((link) => link.story_id === storyId).map((link) => link.artifact_path));
  return walkFiles(outputsDir)
    .filter((filePath) => shouldIndexFile(context, filePath))
    .map((filePath) => toProjectPath(context, filePath))
    .filter((relativePath) => !linked.has(relativePath));
}

function shortHash(value) {
  return crypto.createHash("sha256").update(String(value)).digest("hex").slice(0, 8);
}

function shortHashFull(value) {
  return crypto.createHash("sha256").update(String(value)).digest("hex");
}

function hashFile(filePath) {
  return hashBuffer(fs.readFileSync(filePath));
}

function readStableRegularFileBuffer(filePath, boundaryRoot) {
  assertNoSymlinkPathSegments(filePath, boundaryRoot);
  const parentIdentity = captureDirectoryIdentity(path.dirname(filePath));
  let descriptor;
  try {
    descriptor = fs.openSync(filePath, fs.constants.O_RDONLY | NO_FOLLOW_FLAG);
    const before = verifyOpenFileMatchesPath(descriptor, filePath, parentIdentity);
    const content = fs.readFileSync(descriptor);
    const after = fs.fstatSync(descriptor);
    verifyOpenFileMatchesPath(descriptor, filePath, parentIdentity);
    if (
      !sameStableFileIdentity(before, after)
      || before.size !== after.size
      || before.mode !== after.mode
      || before.mtimeMs !== after.mtimeMs
      || before.ctimeMs !== after.ctimeMs
      || content.byteLength !== after.size
    ) {
      fail(`File changed while creating its stable snapshot: ${filePath}`);
    }
    return {
      content,
      file_type: "regular",
      mode: after.mode & 0o7777,
      size_bytes: after.size,
      sha256: hashBuffer(content),
    };
  } finally {
    if (descriptor !== undefined) {
      fs.closeSync(descriptor);
    }
  }
}

function readStableRegularFileDigest(filePath, boundaryRoot, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
    fail("Stable file digest maxBytes must be a non-negative safe integer.");
  }
  assertNoSymlinkPathSegments(filePath, boundaryRoot);
  const parentIdentity = captureDirectoryIdentity(path.dirname(filePath));
  let descriptor;
  try {
    descriptor = fs.openSync(filePath, fs.constants.O_RDONLY | NO_FOLLOW_FLAG);
    const before = verifyOpenFileMatchesPath(descriptor, filePath, parentIdentity);
    if (before.size > maxBytes) {
      fail(`Local release freshness target exceeds 512 MiB: ${filePath}`);
    }
    const digest = crypto.createHash("sha256");
    const buffer = Buffer.allocUnsafe(64 * 1024);
    let total = 0;
    let position = 0;
    while (total < before.size) {
      const bytesRead = fs.readSync(
        descriptor,
        buffer,
        0,
        Math.min(buffer.byteLength, before.size - total),
        position,
      );
      if (bytesRead === 0) break;
      digest.update(buffer.subarray(0, bytesRead));
      total += bytesRead;
      position += bytesRead;
    }
    const after = fs.fstatSync(descriptor);
    verifyOpenFileMatchesPath(descriptor, filePath, parentIdentity);
    if (
      !sameStableFileIdentity(before, after)
      || before.size !== after.size
      || before.mode !== after.mode
      || before.mtimeMs !== after.mtimeMs
      || before.ctimeMs !== after.ctimeMs
      || total !== after.size
    ) {
      fail(`File changed while creating its stable digest: ${filePath}`);
    }
    return {
      file_type: "regular",
      mode: after.mode & 0o7777,
      size_bytes: after.size,
      sha256: digest.digest("hex"),
    };
  } finally {
    if (descriptor !== undefined) {
      fs.closeSync(descriptor);
    }
  }
}

function readStableRegularFilePrefix(filePath, boundaryRoot, maxBytes = 4096) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 1) {
    fail("Stable file prefix maxBytes must be a positive safe integer.");
  }
  assertNoSymlinkPathSegments(filePath, boundaryRoot);
  const parentIdentity = captureDirectoryIdentity(path.dirname(filePath));
  let descriptor;
  try {
    descriptor = fs.openSync(filePath, fs.constants.O_RDONLY | NO_FOLLOW_FLAG);
    const before = verifyOpenFileMatchesPath(descriptor, filePath, parentIdentity);
    const buffer = Buffer.allocUnsafe(Math.min(maxBytes, Math.max(before.size, 1)));
    const bytesRead = before.size > 0
      ? fs.readSync(descriptor, buffer, 0, Math.min(buffer.byteLength, before.size), 0)
      : 0;
    const after = fs.fstatSync(descriptor);
    verifyOpenFileMatchesPath(descriptor, filePath, parentIdentity);
    if (
      !sameStableFileIdentity(before, after)
      || before.size !== after.size
      || before.mode !== after.mode
      || before.mtimeMs !== after.mtimeMs
      || before.ctimeMs !== after.ctimeMs
    ) {
      fail(`File changed while reading its stable prefix: ${filePath}`);
    }
    return buffer.subarray(0, bytesRead);
  } finally {
    if (descriptor !== undefined) {
      fs.closeSync(descriptor);
    }
  }
}

function assertContextSourcePathSafe(context, filePath, label) {
  assertNoSymlinkPathSegments(filePath, context.root);
  const realRoot = fs.realpathSync.native(context.root);
  const realPath = fs.realpathSync.native(filePath);
  if (!isInsidePath(realRoot, realPath)) {
    fail(`Path must stay inside the target project root: ${label}`);
  }
  const lexicalRealPath = path.join(context.root, path.relative(realRoot, realPath));
  assertNotDerivedArtifact(context, filePath, label);
  assertNotDerivedArtifact(context, lexicalRealPath, label);
  return realPath;
}

function stableContextSourceSnapshot(context, rawPath, label = "Context source") {
  const filePath = resolveProjectFilePath(context, rawPath, { mustExist: true, fileOnly: true });
  assertContextSourcePathSafe(context, filePath, label);
  return {
    filePath,
    projectPath: toProjectPath(context, filePath),
    ...readStableRegularFileBuffer(filePath, context.root),
  };
}

function hashJsonFileValue(value) {
  return hashBuffer(Buffer.from(`${JSON.stringify(value, null, 2)}\n`, "utf8"));
}

function hashBuffer(buffer) {
  return crypto.createHash("sha256").update(buffer).digest("hex");
}

function sealGovernedTraceEvent(context, tracePath, event) {
  const preparedEvent = prepareGovernedTraceEvent(context, event);
  const releaseLegacyTraceLock = acquireFileLock(`${tracePath}.lock`);
  try {
    assertNoPendingWorkflowTraceTransaction(context, tracePath);
    return sealPreparedTraceEventLocked(context, tracePath, preparedEvent);
  } finally {
    releaseLegacyTraceLock();
  }
}

function prepareGovernedTraceEvent(context, event) {
  const redactionPolicy = buildTraceRedactionPolicy(context);
  const evidenceRefs = buildTraceEvidenceRefs(context, event, redactionPolicy);
  const redacted = redactValue({
    ...event,
    evidence_refs: evidenceRefs,
  }, redactionPolicy);
  if (!redacted || typeof redacted !== "object" || Array.isArray(redacted)) {
    fail("Trace redaction reached its safety limit; no event was persisted.");
  }
  return redacted;
}

function sealPreparedTraceEventLocked(context, tracePath, preparedEvent) {
  try {
    return sealTraceEvent({
      ...traceIntegrityOptions(context, tracePath),
      event: preparedEvent,
      hooks: workflowTraceSealTestHooks(preparedEvent),
    }).event;
  } catch (error) {
    failTraceIntegrityWrite(error);
  }
}

function traceIntegrityOptions(context, tracePath) {
  return {
    boundaryRoot: context.sdlcRoot,
    tracePath,
    dependencies: traceIntegrityGovernanceDependencies(tracePath),
  };
}

function traceIntegrityGovernanceDependencies(tracePath) {
  const canonicalTracePath = fs.existsSync(tracePath)
    ? fs.realpathSync.native(tracePath)
    : path.join(fs.realpathSync.native(path.dirname(tracePath)), path.basename(tracePath));
  const checkpointPath = traceIntegrityCheckpointPath(canonicalTracePath);
  const lockPath = `${checkpointPath}.lock`;
  const descriptorMutations = new Map();

  const logicalPath = (candidate) => {
    const resolved = path.resolve(candidate);
    const checkpointDirectory = path.dirname(checkpointPath);
    const name = path.basename(resolved);
    const temporaryPrefix = `.${path.basename(checkpointPath)}.`;
    if (
      path.dirname(resolved) === checkpointDirectory
      && name.startsWith(temporaryPrefix)
      && name.endsWith(".tmp")
    ) {
      // Same-directory random temp names implement one exact checkpoint write;
      // they never widen the policy path beyond the canonical checkpoint.
      return checkpointPath;
    }
    return resolved;
  };
  const requestForOpen = (filePath, flags) => {
    const resolved = path.resolve(filePath);
    const mapped = logicalPath(resolved);
    if (resolved === lockPath) return { operation: "lock.acquire", path: lockPath };
    const append = typeof flags === "number" && (flags & fs.constants.O_APPEND) !== 0;
    if (append) return { operation: "file.append", path: mapped };
    if (mapped === canonicalTracePath) return { operation: "file.truncate", path: mapped };
    return { operation: "file.write", path: mapped };
  };
  const mutatingOpen = (flags) => {
    if (typeof flags === "string") return /[+awx]/u.test(flags);
    return (flags & (
      fs.constants.O_WRONLY
      | fs.constants.O_RDWR
      | fs.constants.O_APPEND
      | fs.constants.O_CREAT
      | fs.constants.O_EXCL
      | fs.constants.O_TRUNC
    )) !== 0;
  };
  const guardedDescriptorMutation = (descriptor, callback) => {
    const request = descriptorMutations.get(descriptor);
    if (!request) {
      throw new MutationGovernanceError(
        "A trace writer tried to use a descriptor without an exact file authorization",
        "MUTATION_GOVERNANCE_DESCRIPTOR_UNBOUND",
      );
    }
    return withGovernedMutation(request, () => {
      assertMutationExecutionAuthorized(request);
      return callback();
    });
  };

  return {
    openSync(filePath, flags, mode) {
      if (!mutatingOpen(flags)) return fs.openSync(filePath, flags, mode);
      const request = requestForOpen(filePath, flags);
      return withGovernedMutation(request, () => {
        assertMutationExecutionAuthorized(request);
        const descriptor = fs.openSync(filePath, flags, mode);
        descriptorMutations.set(descriptor, request);
        return descriptor;
      });
    },
    closeSync(descriptor) {
      try {
        return fs.closeSync(descriptor);
      } finally {
        descriptorMutations.delete(descriptor);
      }
    },
    writeSync(descriptor, buffer, offset, length, position) {
      return guardedDescriptorMutation(
        descriptor,
        () => fs.writeSync(descriptor, buffer, offset, length, position),
      );
    },
    appendWriteSync(descriptor, buffer, offset, length, position) {
      return guardedDescriptorMutation(
        descriptor,
        () => fs.writeSync(descriptor, buffer, offset, length, position),
      );
    },
    ftruncateSync(descriptor, length) {
      return guardedDescriptorMutation(descriptor, () => fs.ftruncateSync(descriptor, length));
    },
    mkdirSync(directoryPath, options) {
      return withGovernedMutation({ operation: "directory.create", path: directoryPath }, () => {
        assertMutationExecutionAuthorized({ operation: "directory.create", path: directoryPath });
        return fs.mkdirSync(directoryPath, options);
      });
    },
    chmodSync(filePath, mode) {
      return withGovernedMutation({ operation: "path.chmod", path: filePath }, () => {
        assertMutationExecutionAuthorized({ operation: "path.chmod", path: filePath });
        return fs.chmodSync(filePath, mode);
      });
    },
    renameSync(sourcePath, targetPath) {
      const source = logicalPath(sourcePath);
      const target = logicalPath(targetPath);
      return withGovernedMutation({ operation: "path.rename.source", path: source }, () =>
        withGovernedMutation({ operation: "path.rename.target", path: target }, () => {
          assertMutationExecutionAuthorized({ operation: "path.rename.source", path: source });
          assertMutationExecutionAuthorized({ operation: "path.rename.target", path: target });
          return fs.renameSync(sourcePath, targetPath);
        }));
    },
    unlinkSync(filePath) {
      const target = logicalPath(filePath);
      const operation = path.resolve(filePath) === lockPath ? "lock.remove" : "file.remove";
      return withGovernedMutation({ operation, path: target }, () => {
        assertMutationExecutionAuthorized({ operation, path: target });
        return fs.unlinkSync(filePath);
      });
    },
  };
}

function workflowTraceSealTestHooks(event) {
  if (
    process.env.NODE_ENV !== "test"
    || event?.action !== "workflow.instance.start"
    || process.env.AGENTIC_SDLC_TEST_WORKFLOW_START_TRACE_FAILURE !== "after-append-before-sync"
  ) {
    return {};
  }
  return {
    after_append_write() {
      fail("Simulated workflow start trace interruption after append.");
    },
  };
}

function failTraceIntegrityWrite(error) {
  if (error instanceof MutationGovernanceError) throw error;
  const code = /^[a-z][a-z0-9_.-]{0,63}$/u.test(String(error?.code || ""))
    ? error.code
    : "trace_integrity_failed";
  fail(`Trace integrity blocked the write (${code}). Run the integrity check before retrying.`);
}

function assertNoPendingWorkflowTraceTransaction(context, tracePath) {
  const projectTracePath = path.join(context.sdlcRoot, "traces", "project.jsonl");
  if (path.resolve(tracePath) !== path.resolve(projectTracePath)) return;
  const pending = [];
  const startsRoot = workflowInstanceStartTransactionsRoot(context);
  for (const entry of safeReadDir(startsRoot)) {
    if (entry.endsWith(".json") && fs.existsSync(path.join(startsRoot, entry))) {
      pending.push(`start:${entry.slice(0, -5)}`);
    }
  }
  const instancesRoot = workflowInstancesRoot(context);
  for (const entry of safeReadDir(instancesRoot)) {
    if (entry.startsWith(".")) continue;
    const pendingPath = path.join(instancesRoot, entry, "pending-transition.json");
    if (fs.existsSync(pendingPath)) pending.push(`transition:${entry}`);
  }
  if (pending.length > 0) {
    fail(`Project trace has a pending workflow transaction (${pending.sort().join(", ")}); recover it before appending another audit event.`);
  }
}

function buildTraceRedactionPolicy(context) {
  return createTraceRedactionPolicy(context, createOperationalRedactionPolicy);
}

function buildLegacyEvidenceV1RedactionPolicy(context) {
  return createTraceRedactionPolicy(context, createLegacyEvidenceV1RedactionPolicy);
}

function buildHistoricalOperationalEvidenceV1RedactionPolicy(context) {
  return createTraceRedactionPolicy(context, createHistoricalOperationalEvidenceV1RedactionPolicy);
}

function traceEvidencePolicySourceRef(context, policy) {
  let source;
  try {
    source = describeRedactionPolicy(policy);
    assertTraceEvidencePolicySourceSafety(source);
  } catch {
    fail("The trace evidence redaction policy cannot be represented safely.");
  }
  const bytes = `${JSON.stringify(source, null, 2)}\n`;
  const sha256 = hashBuffer(Buffer.from(bytes, "utf8"));
  const projectPath = `${TRACE_EVIDENCE_POLICY_SOURCE_ROOT}/${sha256}.json`;
  const filePath = resolveProjectFilePath(context, projectPath, { mustExist: false });
  const releaseLock = acquireFileLock(`${filePath}.lock`);
  try {
    writeTextFile(filePath, bytes, {
      atomicCreate: true,
      durable: true,
      maxExistingBytes: Buffer.byteLength(bytes, "utf8"),
    });
  } finally {
    releaseLock();
  }
  return {
    schema_version: TRACE_EVIDENCE_POLICY_REF_SCHEMA,
    path: projectPath,
    sha256,
  };
}

function loadTraceEvidencePolicySource(context, ref, options = {}) {
  if (
    !ref
    || typeof ref !== "object"
    || Array.isArray(ref)
    || Object.keys(ref).sort().join("\u0000") !== ["path", "schema_version", "sha256"].sort().join("\u0000")
    || ref.schema_version !== TRACE_EVIDENCE_POLICY_REF_SCHEMA
    || !/^[a-f0-9]{64}$/u.test(String(ref.sha256 || ""))
    || ref.path !== `${TRACE_EVIDENCE_POLICY_SOURCE_ROOT}/${ref.sha256}.json`
  ) {
    fail("Trace evidence policy source reference is malformed.");
  }
  const filePath = resolveProjectFilePath(context, ref.path, { mustExist: true, fileOnly: true });
  assertNoSymlinkPathSegments(filePath, context.root);
  const parentIdentity = captureDirectoryIdentity(path.dirname(filePath));
  const bytes = readFileFromStableParent(filePath, parentIdentity, {
    maxBytes: 256 * 1024,
    tooLargeMessage: "Trace evidence policy source exceeds the 256 KiB limit.",
  });
  if (hashBuffer(Buffer.from(bytes, "utf8")) !== ref.sha256) {
    fail("Trace evidence policy source hash does not match its content address.");
  }
  let source;
  try {
    source = JSON.parse(bytes);
  } catch {
    fail("Trace evidence policy source is not valid JSON.");
  }
  try {
    assertTraceEvidencePolicySourceSafety(source, options.allowedAlgorithms);
    return createRedactionPolicyFromSource(source);
  } catch {
    fail("Trace evidence policy source is unsupported or non-canonical.");
  }
}

function assertTraceEvidencePolicySourceSafety(source, allowedAlgorithms) {
  const permitted = new Set(allowedAlgorithms ?? [
    "legacy_evidence_v1",
    "operational_evidence_v1",
    "operational_v2",
  ]);
  if (!source || typeof source !== "object" || Array.isArray(source) || !permitted.has(source.algorithm)) {
    throw new TypeError("unsupported trace evidence redaction algorithm");
  }
  const baselinePolicy = source.algorithm === "legacy_evidence_v1"
    ? createLegacyEvidenceV1RedactionPolicy()
    : source.algorithm === "operational_evidence_v1"
      ? createHistoricalOperationalEvidenceV1RedactionPolicy()
      : createOperationalRedactionPolicy();
  const baseline = describeRedactionPolicy(baselinePolicy);
  if (
    stableJson(source.limits) !== stableJson(baseline.limits)
    || source.replacement !== baseline.replacement
    || stableJson(source.credential_assignment_detector)
      !== stableJson(baseline.credential_assignment_detector)
  ) {
    throw new TypeError("trace evidence redaction safety boundary changed");
  }
  if (
    !Array.isArray(source.sensitive_keys)
    || source.sensitive_keys.length > 256
    || source.sensitive_keys.some((key) => typeof key !== "string" || key.length === 0 || key.length > 128)
    || !Array.isArray(source.detectors)
    || !Array.isArray(source.identifier_allow_patterns)
    || source.detectors.length + source.identifier_allow_patterns.length > baseline.limits.maxPatterns
  ) {
    throw new TypeError("trace evidence redaction policy exceeds its immutable safety limits");
  }
  const hasCanonicalEntry = (entries, required) => {
    const serialized = new Set(entries.map((entry) => stableJson(entry)));
    return required.every((entry) => serialized.has(stableJson(entry)));
  };
  if (
    !baseline.sensitive_keys.every((key) => source.sensitive_keys.includes(key))
    || !hasCanonicalEntry(source.detectors, baseline.detectors)
    || !hasCanonicalEntry(source.identifier_allow_patterns, baseline.identifier_allow_patterns)
  ) {
    throw new TypeError("trace evidence redaction policy omits a mandatory privacy detector");
  }
}

function createTraceRedactionPolicy(context, factory) {
  const configured = context.config.observability?.redaction;
  const secretPatterns = normalizeTraceDetectorPatterns(configured?.secret_patterns, "secret_patterns", "configured_secret");
  const piiPatterns = normalizeTraceDetectorPatterns(configured?.pii_patterns, "pii_patterns", "configured_pii");
  const identifierAllowPatterns = normalizeTraceDetectorPatterns(
    configured?.identifier_allow_patterns,
    "identifier_allow_patterns",
    "configured_identifier",
  );
  const sensitiveKeys = configured?.sensitive_keys;
  if (sensitiveKeys !== undefined && (
    !Array.isArray(sensitiveKeys)
    || sensitiveKeys.some((value) => typeof value !== "string" || value.trim() === "")
  )) {
    fail("observability.redaction.sensitive_keys must be an array of non-empty strings");
  }
  try {
    return factory({
      secretPatterns,
      piiPatterns,
      identifierAllowPatterns,
      ...(sensitiveKeys === undefined ? {} : { sensitiveKeys }),
    });
  } catch {
    fail("The configured observability redaction policy is invalid.");
  }
}

function normalizeTraceDetectorPatterns(value, fieldName, prefix) {
  if (value === undefined) return [];
  if (!Array.isArray(value)) fail(`observability.redaction.${fieldName} must be an array`);
  return value.map((entry, index) => {
    if (typeof entry === "string") return { name: `${prefix}_${index + 1}`, pattern: entry };
    if (entry && typeof entry === "object" && !Array.isArray(entry)) return entry;
    fail(`Observability redaction pattern ${prefix}_${index + 1} must be a string or object`);
  });
}

function buildTraceEvidenceRefs(context, event, policy) {
  const refs = [];
  let policySourceRef;
  const evidence = Array.isArray(event.evidence) ? event.evidence : [];
  for (const projectPath of evidence) {
    let filePath;
    try {
      filePath = resolveProjectFilePath(context, projectPath, { mustExist: true, fileOnly: true });
    } catch {
      continue;
    }
    const representation = redactedEvidenceRepresentation(context, filePath, policy);
    policySourceRef ||= traceEvidencePolicySourceRef(context, policy);
    refs.push({
      path: projectPath,
      size_bytes: Buffer.byteLength(representation, "utf8"),
      sha256: hashBuffer(Buffer.from(representation, "utf8")),
      representation: "redacted_utf8_v2",
      policy_source_ref: policySourceRef,
      verification: shouldVerifyTraceEvidence(event, projectPath)
        ? "current_content"
        : "snapshot_only",
    });
  }
  return refs;
}

function redactedEvidenceRepresentation(context, filePath, policy) {
  const maximumBytes = 16 * 1024 * 1024;
  assertNoSymlinkPathSegments(filePath, context.root);
  const parentIdentity = captureDirectoryIdentity(path.dirname(filePath));
  const source = readFileFromStableParent(filePath, parentIdentity, {
    maxBytes: maximumBytes,
    tooLargeMessage: "Trace evidence exceeds the 16 MiB integrity snapshot limit.",
  });
  const extension = path.extname(filePath).toLowerCase();
  try {
    if (extension === ".json") {
      const parsed = JSON.parse(source);
      if (
        parsed?.kind === "trace_evidence_manifest"
        || parsed?.schema_version === "trace-evidence-manifest:v1"
      ) {
        assertRecordSchema(
          parsed,
          "trace-evidence-manifest.schema.json",
          "Trace evidence manifest",
        );
      }
      const presented = redactValueWithMetadata(parsed, policy);
      if (presented.limited) fail("Trace evidence redaction reached its safety limit.");
      return `${JSON.stringify(presented.value)}\n`;
    }
    if (extension === ".jsonl") {
      const lines = source.split(/\r?\n/u);
      return lines.map((line) => {
        if (!line.trim()) return "";
        const presented = redactValueWithMetadata(JSON.parse(line), policy);
        if (presented.limited) fail("Trace evidence redaction reached its safety limit.");
        return JSON.stringify(presented.value);
      }).join("\n");
    }
  } catch (error) {
    if (error instanceof UserError) throw error;
    // Malformed text remains bounded and is redacted as text without persisting raw bytes.
  }
  const presented = redactValueWithMetadata(source, policy);
  if (presented.limited) fail("Trace evidence redaction reached its safety limit.");
  return presented.value;
}

function shouldVerifyTraceEvidence(event, projectPath) {
  if (["test", "release"].includes(event.type)) return true;
  if ([
    "data.migrate",
    "data.rollback",
    "git.commit",
    "git.push",
    "pull_request.merge",
    "release.local",
    "rollback.verify",
  ].includes(event.action)) {
    return String(projectPath).replace(/\\/gu, "/").startsWith(`${SDLC_DIR}/autonomy/actions/`)
      || String(projectPath).replace(/\\/gu, "/").includes("/evidence/");
  }
  return false;
}

function buildGovernedTraceEvent(context, storyId, event) {
  const normalizedStoryId = storyId ? normalizeId(String(storyId)) : null;
  return {
    id: event.id || `TR-${compactTimestamp()}-${crypto.randomBytes(3).toString("hex")}`,
    story_id: normalizedStoryId,
    type: event.type,
    summary: event.summary,
    outcome: event.outcome || null,
    actor: event.actor,
    requested_by: event.requested_by || null,
    authorized_by: event.authorized_by || null,
    request: event.request || null,
    authorization_ref: event.authorization_ref || null,
    action: event.action || event.type,
    evidence: event.evidence || [],
    related: event.related || [],
    ...(event.narrative ? { narrative: event.narrative } : {}),
    ...(event.story_step_ref ? { story_step_ref: event.story_step_ref } : {}),
    git: event.git || buildGitMetadata(context.root),
    run: event.run || buildRunMetadata({}),
    correlation_id: event.correlation_id || CLI_OPERATION_CONTEXT.correlation_id,
    created_at: event.created_at || now(),
  };
}

function prepareGovernedTraceMutation(context, storyId, event) {
  const normalizedStoryId = storyId ? normalizeId(String(storyId)) : null;
  const traceFile = normalizedStoryId ? `${normalizedStoryId}.jsonl` : "project.jsonl";
  const tracePath = path.join(context.sdlcRoot, "traces", traceFile);
  const preparedEvent = prepareGovernedTraceEvent(
    context,
    buildGovernedTraceEvent(context, normalizedStoryId, event),
  );
  const releaseLegacyTraceLock = acquireFileLock(`${tracePath}.lock`);
  let released = false;
  let committed = false;
  const release = () => {
    if (released) return;
    released = true;
    releaseLegacyTraceLock();
  };
  try {
    assertNoPendingWorkflowTraceTransaction(context, tracePath);
    const integrityOptions = traceIntegrityOptions(context, tracePath);
    recoverTraceIntegrity(integrityOptions);
    withTraceIntegritySnapshot(integrityOptions, ({ integrity }) => {
      if (!integrity.valid) {
        fail(
          `Trace integrity blocked the governed mutation: `
          + `${(integrity.errors || []).map((item) => item.code || item.message || item).join("; ") || "invalid trace state"}.`,
        );
      }
      return true;
    });
  } catch (error) {
    release();
    if (error instanceof UserError || error instanceof MutationGovernanceError) throw error;
    failTraceIntegrityWrite(error);
  }
  return {
    event_id: preparedEvent.id,
    trace_path: tracePath,
    commit() {
      if (committed) {
        fail(`Trace mutation ${preparedEvent.id} has already been committed.`);
      }
      committed = true;
      return sealPreparedTraceEventLocked(context, tracePath, preparedEvent);
    },
    recoverCommitted() {
      try {
        const integrityOptions = traceIntegrityOptions(context, tracePath);
        recoverTraceIntegrity(integrityOptions);
        return withTraceIntegritySnapshot(integrityOptions, ({ integrity, records }) => {
          if (!integrity.valid) return null;
          return records
            .filter((record) => record.valid === true)
            .map((record) => record.event)
            .find((candidate) => candidate?.id === preparedEvent.id)
            || null;
        });
      } catch {
        return null;
      }
    },
    release,
  };
}

function appendTraceEvent(context, storyId, event) {
  const normalizedStoryId = storyId ? normalizeId(String(storyId)) : null;
  const traceFile = normalizedStoryId ? `${normalizedStoryId}.jsonl` : "project.jsonl";
  const tracePath = path.join(context.sdlcRoot, "traces", traceFile);
  const traceEvent = buildGovernedTraceEvent(context, normalizedStoryId, event);
  return sealGovernedTraceEvent(context, tracePath, traceEvent);
}

function rebuildIndex(context, options) {
  ensureInitialized(context);
  const index = buildIndex(context);
  const indexPath = path.join(context.sdlcRoot, "indexes", "kb-index.json");
  writeJsonFile(indexPath, index, { force: true });
  output(
    options,
    { status: "rebuilt", index_path: indexPath, entries: index.entries.length },
    [`Rebuilt knowledge index with ${index.entries.length} entries`],
  );
}

function searchKnowledgeBase(context, options, rest) {
  ensureInitialized(context);
  const query = String(options.query || rest.join(" ")).trim();
  if (!query) {
    fail("Provide a query with 'kb search <query>' or --query.");
  }
  const limit = boundedPositiveInteger(options.limit, "limit", {
    defaultValue: 10,
    maximum: 100,
  });
  const indexStatus = getIndexStatus(context);
  const index = indexStatus.valid ? indexStatus.index : buildIndex(context);
  const terms = tokenize(query);
  const results = index.entries
    .map((entry) => ({ entry, score: scoreEntry(entry, terms) }))
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);

  const jsonResults = options.full ? results : results.map(({ entry, score }) => ({
    score,
    entry: compactIndexEntry(entry, index.source_hashes?.[entry.path]),
  }));
  const omittedBytes = options.full
    ? 0
    : results.reduce((total, { entry }) => total + Buffer.byteLength(entry.search_text || "", "utf8"), 0);
  output(
    options,
    {
      query,
      index_status: indexStatus.valid ? "valid" : "rebuilt_in_memory",
      limit,
      results: jsonResults,
      ...(options.full ? {} : {
        context_optimization: buildContextOptimizationMetadata({
          profile: "kb-search-compact:v1",
          omittedFields: ["results[].entry.search_text"],
          omittedBytes,
          fullPayloadFlag: "--full",
        }),
      }),
    },
    results.length
      ? results.map(({ entry, score }) => `${score.toFixed(2)} ${entry.path}: ${entry.snippet}`)
      : [`No KB results for '${query}'`],
  );
}

function humanReadableGateBlocker(error, locale = "en") {
  const text = String(error || "");
  const italian = locale === "it";
  const rules = [
    {
      pattern: /lifecycle completion|complete lifecycle|terminal .* delivery/i,
      en: "The final lifecycle is not complete yet: every configured phase and the exact delivery must finish successfully.",
      it: "Il ciclo finale non è ancora completo: tutte le fasi configurate e la consegna esatta devono terminare con successo.",
    },
    {
      pattern: /outside the approved requirement write paths|changed-path scope/i,
      en: "At least one changed file is outside the approved implementation area.",
      it: "Almeno un file modificato si trova fuori dall’area di implementazione approvata.",
    },
    {
      pattern: /output ref .*not (?:linked|satisfied)|has no .*output|missing .*output/i,
      en: "The agreed deliverable or implementation evidence has not been linked to this work item yet.",
      it: "Il risultato concordato o la prova di implementazione non è ancora collegato a questa attività.",
    },
    {
      pattern: /has no contract_id|contract .*missing|contract .*not approved/i,
      en: "This work item does not have a valid approved work brief.",
      it: "Questa attività non ha un incarico di lavoro valido e approvato.",
    },
    {
      pattern: /baseline .*stale|baseline .*missing|source .*stale|source .*missing/i,
      en: "The project context used for this work is missing or no longer current.",
      it: "Il contesto di progetto usato per questa attività manca o non è più aggiornato.",
    },
    {
      pattern: /test trace|test evidence|latest test/i,
      en: "A required passing test result or its evidence is missing.",
      it: "Manca un risultato di test superato richiesto oppure la relativa prova.",
    },
    {
      pattern: /approval|human gate/i,
      en: "A required approval is missing, expired, or no longer matches the exact work.",
      it: "Un’approvazione richiesta manca, è scaduta o non corrisponde più al lavoro esatto.",
    },
  ];
  const matched = rules.find((rule) => rule.pattern.test(text));
  if (matched) return italian ? matched.it : matched.en;
  return italian
    ? "Un record obbligatorio manca, è obsoleto o non è coerente; i dettagli tecnici sono riportati sotto."
    : "A required project record is missing, outdated, or inconsistent; technical details are shown below.";
}

function validateCurrentStrictStory(
  context,
  storyId,
  report,
  {
    includeProject = false,
    workflow = null,
    skipChangedPathScope = false,
  } = {},
) {
  if (includeProject) {
    validateProject(context, report);
  }
  validateAuthorizations(context, report);
  validateBaselines(context, report, storyId);
  validateLocks(context, report);
  validateAutonomyRecords(context, report, storyId);

  let currentWorkflow = workflow;
  const story = readStory(context, storyId);
  validateDependencyProposals(context, report, storyId);
  if (story?.contract_id) {
    validateContracts(
      context,
      report,
      new Set([story.contract_id]),
      { workflow: currentWorkflow },
    );
  }
  validateCapabilityDiscovery(context, report, storyId);
  validateTraces(context, report, storyId);
  validateHandoffs(context, report, storyId);
  validateStory(context, storyId, report, { skipChangedPathScope });
  validateOutputContracts(context, report, storyId);
  if (report.lifecycle_complete === true) {
    validateStoryLifecycleCompletion(context, storyId, report);
  }
  if (
    report.lifecycle_complete !== true
    && !currentWorkflow
    && report.errors.length === 0
  ) {
    currentWorkflow = deriveCurrentStoryWorkflowScope(
      context,
      storyId,
      report,
    );
  }
  return { workflow: currentWorkflow };
}

function gateCheck(context, options) {
  ensureInitialized(context);
  const attribution = buildAttribution(context, options, "gate.check");
  const storyId = options.story ? normalizeId(String(options.story)) : null;
  const releaseManifestInput = getOptionString(options, "release-manifest");
  const scope = String(options.scope || (releaseManifestInput ? "release-manifest" : storyId ? "story" : "all"));
  const report = {
    status: "passed",
    strict: Boolean(options.strict),
    scope,
    lifecycle_complete: Boolean(options["lifecycle-complete"]),
    certification_level: options["lifecycle-complete"]
      ? "lifecycle_complete"
      : options.strict && scope === "story" ? "strict_intermediate" : "standard",
    story_id: storyId,
    release_manifest_id: null,
    checked_at: now(),
    root: ".",
    root_name: path.basename(context.root),
    actor: attribution.actor,
    git: attribution.git,
    run: attribution.run,
    errors: [],
    warnings: [],
    checked: [],
  };
  const strictStoryScope =
    report.strict === true
    && scope === "story"
    && Boolean(storyId);
  let strictStoryWorkflow = null;

  if (!["story", "all", "release-manifest"].includes(scope)) {
    fail("Gate scope must be 'story', 'release-manifest', or 'all'.");
  }
  if (scope === "story" && !storyId) {
    fail("Gate scope 'story' requires --story.");
  }
  if (scope === "release-manifest" && !releaseManifestInput) {
    fail("Gate scope 'release-manifest' requires --release-manifest <manifest-id-or-path>.");
  }
  if (options["lifecycle-complete"] && (!options.strict || scope !== "story")) {
    fail("--lifecycle-complete requires --strict with one exact --story.");
  }
  validateProject(context, report);

  if (scope === "release-manifest") {
    const { filePath, manifest } = readReleaseManifest(context, releaseManifestInput);
    report.release_manifest_id = manifest.id || null;
    for (const error of validateReleaseManifestIntegrity(context, manifest)) {
      report.errors.push(`release manifest ${manifest.id || "unknown"}: ${error}`);
    }
    report.checked.push(`release manifest ${manifest.id || toProjectPath(context, filePath)}`);
    for (const reference of manifest.requirements || []) {
      const requirementFile = resolveProjectFilePath(context, reference.path, { mustExist: false });
      if (fs.existsSync(requirementFile)) {
        appendRecordSchemaIssues(report, readProjectJson(context, requirementFile), "requirement.schema.json", `requirement ${reference.id}`);
        report.checked.push(`requirement ${reference.id}`);
      }
    }
    for (const reference of manifest.proposals || []) {
      const proposalFile = resolveProjectFilePath(context, reference.path, { mustExist: false });
      if (fs.existsSync(proposalFile)) {
        appendRecordSchemaIssues(report, readProjectJson(context, proposalFile), "assessment-proposal.schema.json", `proposal ${reference.id}`);
      }
    }
    if (manifest.workflow?.path) {
      const workflowFile = resolveProjectFilePath(context, manifest.workflow.path, { mustExist: false });
      if (fs.existsSync(workflowFile)) {
        appendRecordSchemaIssues(report, readProjectJson(context, workflowFile), "assessment-workflow.schema.json", `workflow ${manifest.workflow.id}`);
      }
    }
    for (const reference of manifest.authorization_usage_receipts || []) {
      const receiptFile = resolveProjectFilePath(context, reference.path, { mustExist: false });
      if (fs.existsSync(receiptFile)) {
        appendRecordSchemaIssues(report, readProjectJson(context, receiptFile), "authorization-usage-receipt.schema.json", `authorization usage receipt ${reference.id}`);
      }
    }
    for (const reference of manifest.execution_usage_receipts || []) {
      const receiptFile = resolveProjectFilePath(context, reference.path, { mustExist: false });
      if (fs.existsSync(receiptFile)) {
        appendRecordSchemaIssues(report, readProjectJson(context, receiptFile), "execution-usage-receipt.schema.json", `execution usage receipt ${reference.id}`);
      }
    }
    for (const reference of manifest.context_optimization_observations || []) {
      const observationFile = resolveProjectFilePath(context, reference.path, { mustExist: false });
      if (fs.existsSync(observationFile)) {
        appendRecordSchemaIssues(report, readProjectJson(context, observationFile), "context-optimization-observation.schema.json", `context optimization observation ${reference.id}`);
      }
    }
    for (const reference of manifest.gate_receipts || []) {
      const receiptFile = resolveProjectFilePath(context, reference.path, { mustExist: false });
      if (fs.existsSync(receiptFile)) {
        appendRecordSchemaIssues(report, readProjectJson(context, receiptFile), "release-gate-receipt.schema.json", `release gate receipt ${reference.id}`);
      }
    }
    for (const reference of manifest.contracts || []) report.checked.push(`contract ${reference.id}`);
    for (const reference of manifest.stories || []) {
      report.checked.push(`story ${reference.id}`);
      validateTraces(context, report, reference.id, {
        required: storyTraceIsExpected(context, reference.id),
      });
    }
    validateTraces(context, report, null, { projectOnly: true });
    for (const artifact of manifest.artifacts || []) report.checked.push(`artifact ${artifact.id}`);
    report.warnings.push("Historical records outside this release manifest are logically archived out of the active release scope and were not used to decide this gate.");
  } else if (!strictStoryScope) {
    validateAuthorizations(context, report);
    validateBaselines(context, report, storyId && scope === "story" ? storyId : null);
    validateLocks(context, report);
    validateAutonomyRecords(context, report, storyId && scope === "story" ? storyId : null);
  }

  if (storyId && scope === "story") {
    if (strictStoryScope) {
      ({ workflow: strictStoryWorkflow } = validateCurrentStrictStory(
        context,
        storyId,
        report,
      ));
    } else {
      const story = readStory(context, storyId);
      validateDependencyProposals(context, report, storyId);
      if (story?.contract_id) {
        validateContracts(context, report, new Set([story.contract_id]));
      }
      validateCapabilityDiscovery(context, report, storyId);
      validateTraces(context, report, storyId);
      validateHandoffs(context, report, storyId);
      validateStory(context, storyId, report);
      validateOutputContracts(context, report, storyId);
    }
    appendOperationsPhaseGateChecks(context, report, storyId, readStory(context, storyId));
  } else if (scope === "all") {
    validateDependencyProposals(context, report);
    validateContracts(context, report);
    validateCapabilityDiscovery(context, report);
    validateTraces(context, report);
    validateHandoffs(context, report);
    const storiesRoot = path.join(context.sdlcRoot, "stories");
    for (const entry of safeReadDir(storiesRoot)) {
      const storyJson = path.join(storiesRoot, entry, "story.json");
      if (fs.existsSync(storyJson)) {
        validateStory(context, entry, report);
        appendOperationsPhaseGateChecks(context, report, entry, readProjectJson(context, storyJson));
      }
    }
    validateOutputContracts(context, report);
  }

  report.approval_requests = collectApprovalRequests(context, {
    storyId: scope === "story" ? storyId : null,
  });
  if (scope === "release-manifest") {
    report.approval_requests = [];
  }
  report.assistant_message = renderApprovalRequestsAssistantMessage(report.approval_requests);
  attachAssistantMessagePresentation(report);

  if (
    report.errors.length === 0
    && report.strict === true
    && scope === "story"
    && options["lifecycle-complete"] !== true
  ) {
    const workflow = strictStoryWorkflow;
    if (
      workflow
      && workflowCanonicalEvidenceSchema(workflow.effective_definition)
        === WORKFLOW_CANONICAL_EVIDENCE_SCHEMA
    ) {
      report.workflow_scope = workflow.scope;
      report.checked.push(
        `workflow scope ${workflow.scope.instance_id}@${workflow.scope.current_phase}`,
      );
    } else if (workflow) {
      report.checked.push(
        `legacy workflow evidence ${workflow.scope.instance_id}@${workflow.scope.current_phase}`,
      );
    }
  }

  if (report.errors.length > 0) {
    report.status = "failed";
    process.exitCode = 1;
  }
  const locale = humanGuidanceLocale(options);
  const plainBlockers = Array.from(new Set(report.errors.map((item) => humanReadableGateBlocker(item, locale))));
  const guidance = gateGuidance({ ...report, human_blockers: plainBlockers }, { locale });
  report.human_guidance = guidance;
  if (
    report.status === "passed"
    && report.strict === true
    && scope === "story"
  ) {
    if (options["lifecycle-complete"] === true) {
      const finalReceipt = persistWorkflowFinalGateReceipt(context, report);
      Object.assign(report, finalReceipt);
    } else {
      const strictReceipt = sealWorkflowStrictGateReceipt(context, report);
      const strictReceiptPath = workflowStrictGateReceiptPath(context, storyId);
      writeWorkflowJsonDurably(strictReceiptPath, strictReceipt, { force: true });
      Object.assign(report, strictReceipt);
    }
  }
  if (options.out) {
    writeGateReport(context, report, options);
  }

  const blockerSummary = plainBlockers.length > 0
    ? [
        locale === "it" ? "Cosa bisogna sistemare:" : "What needs fixing:",
        ...plainBlockers.map((item) => `- ${item}`),
      ]
    : [];
  const followUpSummary = report.approval_requests.length > 0
    ? [
        "",
        locale === "it" ? "Altre verifiche registrate:" : "Other recorded follow-ups:",
        ...report.approval_requests.slice(0, 5).map((request) => {
          const title = plainApprovalRequestCopy(request).title;
          if (request.status === "needs_internal_refresh") {
            return locale === "it"
              ? `- Aggiornare i riferimenti interni per ${title}; questo non approva né amplia l’ambito.`
              : `- Refresh internal references for ${title}; this neither approves nor expands the scope.`;
          }
          return locale === "it"
            ? `- Serve ancora una decisione per ${title}.`
            : `- A decision is still needed for ${title}.`;
        }),
      ]
    : [];
  output(
    options,
    report,
    [
      ...humanGuidanceLines(guidance, [
        `Scope checked: ${scope}${storyId ? `; story ${storyId}` : ""}`,
        `Certification level: ${report.certification_level}`,
        `Items checked: ${report.checked.length}`,
        `Blocking issues: ${report.errors.length}`,
        `Warnings: ${report.warnings.length}`,
        `Recorded follow-ups: ${report.approval_requests.length}`,
        ...report.errors.map((item) => `Blocker: ${item}`),
        ...report.warnings.map((item) => `Warning: ${item}`),
        ...(report.final_receipt_path
          ? [`Final lifecycle receipt: ${report.final_receipt_path}`]
          : []),
      ], options, blockerSummary),
      ...followUpSummary,
    ],
  );
}

function readStory(context, storyId) {
  const id = normalizeId(storyId);
  const storyPath = path.join(context.sdlcRoot, "stories", id, "story.json");
  return fs.existsSync(storyPath) ? normalizeStoryRecord(readProjectJson(context, storyPath)) : null;
}

function normalizeStoryRecord(story) {
  if (!story || typeof story !== "object") {
    return story;
  }
  const acceptanceCriteria = storyAcceptanceCriteria(story);
  return {
    ...story,
    acceptance: Array.isArray(story.acceptance) ? story.acceptance : acceptanceCriteria,
    acceptance_criteria: acceptanceCriteria,
  };
}

function storyAcceptanceCriteria(story) {
  const canonical = Array.isArray(story?.acceptance_criteria) ? story.acceptance_criteria : [];
  if (canonical.length > 0) {
    return canonical;
  }
  return normalizeListValue(story?.acceptance, []);
}

function writeGateReport(context, report, options) {
  assertRecordSchema(report, "gate-report.schema.json", `Gate report ${report.story_id || "project"}`);
  const reportPath = resolveProjectFilePath(context, options.out, { mustExist: false });
  assertNotDerivedArtifact(context, reportPath, "Gate report");
  const extension = path.extname(reportPath).toLowerCase();
  if (extension === ".md") {
    writeTextFile(reportPath, renderGateReportMarkdown(report), { force: Boolean(options.force) });
    return;
  }
  writeJsonFile(reportPath, report, { force: Boolean(options.force) });
}

function renderGateReportMarkdown(report) {
  return [
    `# SDLC Gate Report`,
    "",
    `- Status: ${report.status}`,
    `- Strict: ${report.strict}`,
    `- Scope: ${report.scope}`,
    `- Story: ${report.story_id || "all"}`,
    `- Checked at: ${report.checked_at}`,
    `- Checked items: ${report.checked.length}`,
    "",
    "## Errors",
    ...(report.errors.length ? report.errors.map((item) => `- ${item}`) : ["- None"]),
    "",
    "## Warnings",
    ...(report.warnings.length ? report.warnings.map((item) => `- ${item}`) : ["- None"]),
    "",
    "## Human Input Requests",
    ...(report.approval_requests?.length
      ? report.approval_requests.flatMap((item, index) => formatMarkdownApprovalRequest(item, index + 1))
      : ["- None"]),
    "",
    "## Checked",
    ...(report.checked.length ? report.checked.map((item) => `- ${item}`) : ["- None"]),
    "",
  ].join("\n");
}

function formatMarkdownApprovalRequest(request, index = null) {
  const prefix = index === null ? "-" : `${index}.`;
  const lines = [
    `${prefix} ${request.title || request.summary}`,
    request.why_needed ? `   - Why: ${request.why_needed}` : null,
    request.review_items?.length ? "   - What to review:" : null,
    ...(request.review_items || []).slice(0, 6).map((item) => `     - ${item}`),
    request.delivery_format_options?.length ? "   - Delivery / presentation options:" : null,
    ...(request.delivery_format_options || []).slice(0, 10).map((option) => `     - ${formatDeliveryFormatOption(option)}`),
    request.recommended_delivery_format ? `   - Recommended delivery: ${request.recommended_delivery_format}` : null,
    request.delivery_question ? `   - Delivery question: ${request.delivery_question}` : null,
    request.approval_meaning ? `   - What approval means: ${request.approval_meaning}` : null,
    request.user_prompt ? `   - Question: ${request.user_prompt}` : null,
    request.suggested_command ? `   - Command: \`${request.suggested_command}\`` : null,
  ];
  return lines.filter(Boolean);
}

function showStatus(context, options) {
  ensureInitialized(context);
  const counts = {};
  for (const directory of context.config.kb_directories) {
    const dirPath = path.join(context.sdlcRoot, directory);
    counts[directory] = directory === "contracts"
      ? collectJsonFiles(context, dirPath).filter((contract) => !isIntactBootstrapPhaseContract(context, contract)).length
      : countCanonicalRecords(directory, dirPath);
  }
  const project = readProjectJson(context, path.join(context.sdlcRoot, "project.json"));
  const orchestration = buildOrchestrationSnapshot(context);
  const approvalRequests = collectApprovalRequests(context);
  const pendingDecisions = approvalRequests.filter((request) =>
    request.status !== "needs_internal_refresh"
    && request.status !== "needs_refresh"
    && !String(request.type || "").endsWith("_refresh_required"));
  const internalRefreshes = approvalRequests.length - pendingDecisions.length;
  const summary = {
    pending_decisions: pendingDecisions.length,
    internal_refreshes: internalRefreshes,
    available_work: orchestration.summary.available,
    active_work: orchestration.summary.claimed,
    blocked_work: orchestration.summary.blocked,
    stale_claims: orchestration.summary.stale,
    completed_work: orchestration.summary.terminal,
  };
  const nextAction = buildStatusNextAction(context, summary, orchestration, counts, project);
  const italian = humanGuidanceLocale(options) === "it";
  const guidance = statusHumanGuidance(nextAction, summary, { italian });
  const payload = {
    schema_version: "cli-status:v1",
    project,
    counts,
    summary,
    next_action: nextAction,
    ...(options.full ? {
      pending_decision_items: pendingDecisions,
      internal_refresh_items: approvalRequests.filter((request) => !pendingDecisions.includes(request)),
      orchestration,
    } : {}),
  };
  output(
    options,
    payload,
    humanGuidanceLines(guidance, [
      `${italian ? "Progetto" : "Project"}: ${project.project_name} (${project.project_id})`,
      `${italian ? "Tipo di prossimo passo" : "Next-action kind"}: ${nextAction.kind}`,
      `${italian ? "Motivo tecnico" : "Technical reason"}: ${nextAction.reason}`,
      `${italian ? "Comando suggerito" : "Suggested command"}: ${nextAction.command || (italian ? "nessuno" : "none")}`,
      ...Object.entries(summary).map(([key, value]) => `${key}: ${value}`),
      ...(options.full ? Object.entries(counts).map(([key, value]) => `${key}: ${value}`) : []),
    ], options),
  );
}

function statusCliCommand(...args) {
  const cliPath = path.join(PLUGIN_ROOT, "bin", "agentic-sdlc.mjs");
  return [
    "node",
    JSON.stringify(cliPath),
    ...args.map((value) => (
      /^[A-Za-z0-9._:@/=-]+$/u.test(String(value))
        ? String(value)
        : JSON.stringify(String(value))
    )),
  ].join(" ");
}

function matchingApprovedStoryWorkflowDefinition(context) {
  return listVersionedWorkflowRecords(context, workflowDefinitionsRoot(context))
    .map(({ record }) => record)
    .filter((definition) =>
      definition.status === "approved"
      && definition.metadata?.governance_binding === "story"
      && workflowPhaseOrderDifference(context, definition).exact)
    .sort((left, right) =>
      String(left.id).localeCompare(String(right.id), "en")
      || String(left.version).localeCompare(String(right.version), "en"))
    .at(-1) || null;
}

function currentCertifiedLifecycleEvidenceMatches(
  context,
  storyId,
  proof,
  checkedAt,
  { workflow = null } = {},
) {
  const checkedAtMs = Date.parse(String(checkedAt || ""));
  if (!Number.isFinite(checkedAtMs)) return false;
  try {
    const lifecycleEvents = readTraceEvents(context, storyId)
      .filter((event) => ["test", "release"].includes(event.type));
    if (lifecycleEvents.some((event) => {
      const createdAt = Date.parse(String(event.created_at || ""));
      return !Number.isFinite(createdAt) || createdAt > checkedAtMs;
    })) {
      return false;
    }
    const freshness = {
      status: "passed",
      strict: true,
      scope: "story",
      lifecycle_complete: true,
      story_id: storyId,
      errors: [],
      warnings: [],
      checked: [],
    };
    validateCurrentStrictStory(
      context,
      storyId,
      freshness,
      {
        includeProject: true,
        workflow,
        skipChangedPathScope: true,
      },
    );
    return (
      freshness.errors.length === 0
      && stableJson(freshness.lifecycle_workflow) === stableJson(proof)
    );
  } catch {
    return false;
  }
}

function validCurrentWorkflowFinalReceipt(context, storyId, instance) {
  const receiptPath = workflowFinalGateReceiptPath(context, storyId);
  if (!fs.existsSync(receiptPath)) return { exists: false, valid: false };
  try {
    const receipt = readProjectJson(context, receiptPath);
    assertRecordSchema(
      receipt,
      "workflow-final-gate-receipt.schema.json",
      `Final workflow gate receipt ${storyId}`,
    );
    const { effectiveDefinition } = loadEffectiveDefinitionForInstance(context, instance);
    const eventsPath = workflowEventsPath(context, instance.id);
    const releaseLock = acquireFileLock(`${eventsPath}.lock`);
    let events;
    let integrity;
    try {
      events = readWorkflowEvents(context, instance.id);
      integrity = inspectWorkflowRuntimeIntegrity(
        context,
        instance.id,
        instance,
        effectiveDefinition,
        events,
      );
    } finally {
      releaseLock();
    }
    const currentPhase = integrity.valid
      ? workflowCurrentState(integrity.replay, instance, effectiveDefinition)
      : null;
    const terminalState = (effectiveDefinition.states || [])
      .find((state) => state.id === currentPhase);
    const terminalEvent = events.at(-1) || null;
    const proof = receipt.lifecycle_workflow || {};
    const checkpoint = integrity.checkpoint || {};
    const taskStartBinding = inspectModernWorkflowTaskStartBinding(
      context,
      storyId,
      instance,
    );
    const taskStart = taskStartBinding.task_start;
    const currentFreshnessProof = buildWorkflowFinalFreshnessProof(
      context,
      storyId,
      instance.id,
      receipt.freshness_proof,
    );
    return {
      exists: true,
      valid:
        hasValidWorkflowReceiptHash(receipt)
        && receipt.freshness_proof?.schema_version
          === WORKFLOW_FINAL_FRESHNESS_PROOF_SCHEMA
        && receipt.freshness_proof?.story_id === storyId
        && receipt.freshness_proof?.workflow_instance_id === instance.id
        && receipt.freshness_proof?.proof_hash
          === computeStableHash((({ proof_hash: ignored, ...subject }) => subject)(
            receipt.freshness_proof,
          ))
        && workflowFinalFreshnessProofMatches(
          context,
          receipt.freshness_proof,
          currentFreshnessProof,
        )
        && integrity.valid
        && receipt.story_id === storyId
        && receipt.lifecycle_workflow?.instance_id === instance.id
        && receipt.lifecycle_workflow?.instance_hash === instance.instance_hash
        && proof.story_id === storyId
        && terminalState?.terminal === true
        && currentPhase === configuredPhaseOrder(context).at(-1)
        && proof.effective_hash === effectiveDefinition.effective_hash
        && proof.terminal_state === currentPhase
        && proof.event_count === events.length
        && proof.checkpoint_ref?.path
          === toProjectPath(context, workflowCheckpointPath(context, instance.id))
        && proof.checkpoint_ref?.checkpoint_hash === checkpoint.checkpoint_hash
        && proof.checkpoint_ref?.sequence === checkpoint.sequence
        && proof.checkpoint_ref?.last_event_hash === checkpoint.last_event_hash
        && proof.checkpoint_ref?.trace_chain_hash === checkpoint.trace_chain_hash
        && proof.terminal_event_ref?.event_hash === terminalEvent?.event_hash
        && proof.terminal_event_ref?.sequence === terminalEvent?.sequence
        && proof.terminal_event_ref?.timestamp === terminalEvent?.timestamp
        && taskStartBinding.valid
        && proof.task_start_ref?.id === taskStart?.id
        && proof.task_start_ref?.path === toProjectPath(context, taskStartBinding.path)
        && proof.task_start_ref?.hash === taskStartBinding.hash
        && proof.task_start_ref?.confirmed_at === taskStart?.confirmed_at
        && currentCertifiedLifecycleEvidenceMatches(
          context,
          storyId,
          proof,
          receipt.checked_at,
          {
            workflow: {
              instance,
              effective_definition: effectiveDefinition,
              integrity,
              scope: workflowScopeFromRuntime(
                instance,
                effectiveDefinition,
                integrity,
                currentPhase,
              ),
            },
          },
        ),
      current_phase: currentPhase,
      workflow_instance_id: instance.id,
    };
  } catch {
    return { exists: true, valid: false };
  }
}

/**
 * The phase whose completion closes a delivery. It is "release" whenever the
 * project's phase order has one, even when a later phase such as operations
 * follows it; a custom phase order without "release" keeps its last phase, as
 * before operations existed.
 */
function releasePhaseName(context) {
  const phaseOrder = configuredPhaseOrder(context);
  return phaseOrder.includes("release") ? "release" : phaseOrder.at(-1);
}

function storyReleaseReadiness(context, storyId) {
  const missing = [];
  const releaseStep = readStoryStepRecords(context, storyId)
    .find((record) => record.status === "completed" && record.phase === releasePhaseName(context));
  const releaseTrace = latestTraceEvent(readTraceEvents(context, storyId), "release");
  const story = readStory(context, storyId);
  const contract = story?.contract_id
    ? readContractById(context, story.contract_id, { missingOk: true })
    : null;
  const profileId = contract?.delivery_execution_profile_id || null;
  let deliveryReady = false;
  if (profileId) {
    try {
      const profile = readDeliveryAutonomyProfile(context, profileId);
      const state = currentDeliveryExecutionState(context, profile);
      deliveryReady = state.lifecycle_status === "terminal"
        && ["merged", "released"].includes(state.status);
    } catch {
      deliveryReady = false;
    }
  }
  if (!deliveryReady) missing.push("terminal successful delivery");
  if (releaseTrace?.outcome !== "passed") missing.push("passing release trace");
  if (!releaseStep) missing.push("completed release step");
  return {
    ready: missing.length === 0,
    missing,
    profile_id: profileId,
  };
}

function outputLinkAuthorizationId(link) {
  if (link?.authorization_ref) {
    return link.authorization_ref;
  }
  for (const sourcePath of link?.source_paths || []) {
    const match = String(sourcePath)
      .match(/^\.sdlc\/authorization-uses\/([^/]+)\//u);
    if (match?.[1]) return match[1];
  }
  return null;
}

function outputLinkRepairCommand(link) {
  const args = [
    "output", "link",
    "--story", link.story_id,
    "--type", link.artifact_type,
    "--artifact", link.artifact_path,
    "--template", link.template_id,
    "--mode", link.mode,
    "--id", link.id,
  ];
  if (link.base_artifact) {
    args.push("--base-artifact", link.base_artifact);
  }
  for (const requirementId of link.requirements || []) {
    args.push("--requirement", requirementId);
  }
  for (const evidence of link.verification_receipt?.evidence || []) {
    const evidencePath = evidence?.path || evidence;
    if (evidencePath) args.push("--evidence", evidencePath);
  }
  const generatorReceiptPath =
    link.verification_receipt?.generator_receipt?.path;
  if (generatorReceiptPath) {
    args.push("--receipt-file", generatorReceiptPath);
  }
  const authorizationId = outputLinkAuthorizationId(link);
  if (authorizationId) {
    args.push("--authorization", authorizationId);
  }
  if (link.decision_id) {
    args.push("--decision-id", link.decision_id);
  }
  if (link.rationale) {
    args.push("--rationale", link.rationale);
  }
  return statusCliCommand(...args);
}

function strictGateOutputRepair(context, storyId, issues) {
  const registry = readOutputRegistry(context, { missingOk: true });
  if (!registry) return null;
  const templates = Array.isArray(registry.templates)
    ? registry.templates
    : [];
  const links = Array.isArray(registry.links)
    ? registry.links.filter((link) => link.story_id === storyId)
    : [];
  const gateCommand = statusCliCommand(
    "gate", "check", "--strict", "--story", storyId,
  );
  const template = templates.find((candidate) =>
    candidate?.id
    && issues.some((issue) =>
      String(issue).includes(`template ${candidate.id}`)
      && /changed after approval|delivery format changed after approval|structure or delivery approval is stale/iu
        .test(String(issue))));
  if (template) {
    const approvalCommand = statusCliCommand(
      "output", "template", "approve",
      "--id", template.id,
      "--actor-type", "human",
      "--approval-source", "explicit-user",
      "--summary", "<user-approved output format>",
    );
    const affectedLinks = links
      .filter((link) => link.template_id === template.id)
      .sort((left, right) => String(left.id).localeCompare(String(right.id), "en"));
    return {
      kind: "reapprove_output_template",
      reason: "output_template_changed_after_approval",
      label:
        `Review and re-approve output template ${template.id}, then refresh its linked artifact before re-running the strict gate.`,
      command: approvalCommand,
      template_id: template.id,
      affected_output_link_ids: affectedLinks.map((link) => link.id),
      repair_steps: [
        {
          kind: "reapprove_output_template",
          command: approvalCommand,
        },
        ...affectedLinks.map((link) => ({
          kind: "repair_output_link",
          output_link_id: link.id,
          command: outputLinkRepairCommand(link),
        })),
        {
          kind: "seal_strict_gate",
          command: gateCommand,
        },
      ],
    };
  }
  const link = links.find((candidate) =>
    candidate?.id
    && issues.some((issue) =>
      String(issue).includes(`output link ${candidate.id}`)
      && /artifact|verification receipt|fingerprint|changed after the artifact was linked/iu
        .test(String(issue))));
  if (!link) return null;
  const repairCommand = outputLinkRepairCommand(link);
  return {
    kind: "repair_output_link",
    reason: "output_link_evidence_changed",
    label:
      `Refresh output link ${link.id} against the current artifact and approved template before re-running the strict gate.`,
    command: repairCommand,
    output_link_id: link.id,
    artifact_path: link.artifact_path,
    template_id: link.template_id,
    repair_steps: [
      {
        kind: "repair_output_link",
        output_link_id: link.id,
        command: repairCommand,
      },
      {
        kind: "seal_strict_gate",
        command: gateCommand,
      },
    ],
  };
}

function currentStoryStrictGateReadiness(
  context,
  storyId,
  instance,
  effectiveDefinition,
  integrity,
  currentState,
) {
  const strictPath = workflowStrictGateReceiptPath(context, storyId);
  if (!fs.existsSync(strictPath)) {
    return {
      ready: false,
      reason: "missing",
      issues: [`Intermediate strict gate receipt ${toProjectPath(context, strictPath)} is missing.`],
    };
  }
  try {
    return withOutputRegistryLock(context, () => {
    const canonicalEvidenceSchema =
      workflowCanonicalEvidenceSchema(effectiveDefinition)
      || WORKFLOW_LEGACY_CANONICAL_EVIDENCE_SCHEMA;
    const modern =
      canonicalEvidenceSchema === WORKFLOW_CANONICAL_EVIDENCE_SCHEMA;
    const evidence = buildCanonicalEvidenceForWorkflowInstance(
      context,
      instance,
      canonicalEvidenceSchema,
      modern
        ? {
            current_phase: currentState,
            phase_order: effectiveDefinition.phase_order,
            require_all: false,
          }
        : null,
      modern
        ? workflowScopeFromRuntime(
            instance,
            effectiveDefinition,
            integrity,
            currentState,
          )
        : null,
    );
    const check = evidence.checks?.strict_gate_passed;
    const issues = check?.satisfied === true
      ? []
      : Array.isArray(check?.issues) && check.issues.length > 0
        ? check.issues.map((issue) => String(issue))
        : ["The intermediate strict gate receipt is not valid for the current workflow state."];
    const receipt = readProjectJson(context, strictPath);
    const checkedAt = Date.parse(String(receipt.checked_at || ""));
    if (!Number.isFinite(checkedAt)) {
      issues.push("The intermediate strict gate receipt has no valid checked_at timestamp.");
    } else {
      const currentStepCompletedAt = readStoryStepRecords(context, storyId)
        .filter((record) =>
          record.status === "completed"
          && record.phase === currentState
          && Number.isFinite(Date.parse(String(record.completed_at || ""))))
        .map((record) => Date.parse(record.completed_at))
        .sort((left, right) => right - left)[0] || null;
      if (currentStepCompletedAt && currentStepCompletedAt > checkedAt) {
        issues.push(
          `The intermediate strict gate predates completion of the current '${currentState}' step.`,
        );
      }
      const newerLifecycleTrace = readTraceEvents(context, storyId)
        .filter((event) => ["test", "release"].includes(event.type))
        .find((event) => {
          const createdAt = Date.parse(String(event.created_at || ""));
          return !Number.isFinite(createdAt) || createdAt > checkedAt;
        });
      if (newerLifecycleTrace) {
        issues.push(
          `The intermediate strict gate predates current ${newerLifecycleTrace.type} evidence.`,
        );
      }
    }
    const currentValidation = {
      status: "passed",
      strict: true,
      scope: "story",
      lifecycle_complete: false,
      story_id: storyId,
      errors: [],
      warnings: [],
      checked: [],
    };
    validateCurrentStrictStory(
      context,
      storyId,
      currentValidation,
      {
        includeProject: true,
        workflow: {
          instance,
          effective_definition: effectiveDefinition,
          integrity,
          scope: workflowScopeFromRuntime(
            instance,
            effectiveDefinition,
            integrity,
            currentState,
          ),
        },
      },
    );
    issues.push(...currentValidation.errors.map((issue) => String(issue)));
    const uniqueIssues = Array.from(new Set(issues));
    let repair = uniqueIssues.length > 0
      ? strictGateOutputRepair(context, storyId, uniqueIssues)
      : null;
    if (!repair && currentValidation.errors.length > 0) {
      const diagnosticCommand = statusCliCommand(
        "gate", "check", "--strict", "--story", storyId,
      );
      repair = {
        kind: "repair_strict_gate_evidence",
        reason: "current_strict_gate_evidence_invalid",
        label:
          "Inspect the strict-gate blockers, repair the invalid current project evidence, then run the strict gate again.",
        command: diagnosticCommand,
        diagnostic: true,
        repair_steps: [
          {
            kind: "diagnose_strict_gate_blockers",
            command: diagnosticCommand,
          },
        ],
      };
    }
    return {
      ready: uniqueIssues.length === 0,
      reason: uniqueIssues.length === 0 ? "current" : "stale",
      issues: uniqueIssues,
      repair,
    };
    });
  } catch (error) {
    return {
      ready: false,
      reason: "invalid",
      issues: [
        error.message
          || "The intermediate strict gate receipt cannot be verified.",
      ],
      repair: null,
    };
  }
}

function buildStoryWorkflowNextAction(context, story) {
  if (!story?.id) return null;
  const taskStartPath = path.join(context.sdlcRoot, "stories", story.id, "task-start.json");
  const completedSteps = readStoryStepRecords(context, story.id)
    .filter((record) => record.status === "completed");
  const probe = { errors: [] };
  const selected = currentStoryBoundWorkflowInstance(context, story.id, probe);
  if (probe.errors.length > 0) {
    return {
      kind: "inspect_story_workflow",
      reason: "workflow_state_unreadable",
      label: "Inspect the story workflow before continuing.",
      command: statusCliCommand("workflow", "definition", "list"),
      protected: true,
      story_id: story.id,
    };
  }
  if (!selected) {
    if (fs.existsSync(taskStartPath)) {
      const taskStart = readProjectJson(context, taskStartPath);
      if (
        taskStart.kind === "task_start_receipt"
        && taskStart.schema_version === "task-start-receipt:v2"
        && taskStart.story_id === story.id
        && taskStart.proposal_ref?.id
      ) {
        const assessmentId = normalizeId(taskStart.proposal_ref.id);
        let assessmentState = "missing_workflow";
        try {
          const assessmentWorkflow = readAssessmentWorkflow(
            context,
            assessmentId,
            { missingOk: true },
          );
          assessmentState = assessmentWorkflow?.state || "missing_workflow";
        } catch {
          assessmentState = "unreadable";
        }
        return {
          kind: "continue_assessment",
          reason: `assessment_${assessmentState}`,
          label:
            `Continue assessment ${assessmentId}: ${assessmentNextAction(assessmentState, assessmentId)}.`,
          command: statusCliCommand(
            "assessment", "proposal", "status", "--id", assessmentId,
          ),
          protected: true,
          story_id: story.id,
          assessment_id: assessmentId,
          assessment_state: assessmentState,
        };
      }
    }
    if (fs.existsSync(taskStartPath) || completedSteps.length > 0) {
      return {
        kind: "lifecycle_not_certifiable",
        reason: "workflow_missing_before_task_or_step",
        label:
          "This legacy task has no pre-task workflow binding; a post-hoc workflow cannot certify lifecycle completion.",
        command: null,
        protected: true,
        story_id: story.id,
      };
    }
    const configured = configuredPhaseOrder(context);
    const stock = configured.length === SOFTWARE_PROJECT_PHASES.length
      && configured.every((phase, index) => phase === SOFTWARE_PROJECT_PHASES[index]);
    const definition = stock ? null : matchingApprovedStoryWorkflowDefinition(context);
    if (!stock && !definition) {
      return {
        kind: "define_custom_workflow",
        reason: "custom_phase_order_needs_matching_workflow",
        label:
          `Define and approve a story-bound workflow with this exact phase order: ${configured.join(" -> ")}.`,
        command: statusCliCommand("workflow", "definition", "propose", "--help"),
        protected: true,
        story_id: story.id,
        configured_phase_order: configured,
      };
    }
    const definitionId = stock ? "software-project" : definition.id;
    const definitionVersion = stock ? "3" : definition.version;
    return {
      kind: "start_story_workflow",
      reason: "story_workflow_not_started",
      label: "Start the governed story workflow before task start or the first completed step.",
      command: statusCliCommand(
        "workflow", "instance", "start",
        "--id", `DELIVERY-${story.id}`,
        "--definition", definitionId,
        "--definition-version", definitionVersion,
        "--story", story.id,
      ),
      protected: true,
      story_id: story.id,
      definition_id: definitionId,
      definition_version: definitionVersion,
    };
  }

  let instance;
  let effectiveDefinition;
  let events;
  let integrity;
  try {
    ({ instance } = readCompletedWorkflowInstance(context, selected.entry));
    ({ effectiveDefinition } = loadEffectiveDefinitionForInstance(context, instance));
    const eventsPath = workflowEventsPath(context, selected.entry);
    const releaseEventLock = acquireFileLock(`${eventsPath}.lock`);
    try {
      events = readWorkflowEvents(context, selected.entry);
      integrity = inspectWorkflowRuntimeIntegrity(
        context,
        selected.entry,
        instance,
        effectiveDefinition,
        events,
      );
    } finally {
      releaseEventLock();
    }
  } catch {
    return {
      kind: "inspect_story_workflow",
      reason: "workflow_state_unreadable",
      label: "Inspect the bound story workflow before continuing.",
      command: statusCliCommand("workflow", "instance", "status", "--id", selected.entry),
      protected: true,
      story_id: story.id,
      workflow_instance_id: selected.entry,
    };
  }
  if (!integrity.valid) {
    return {
      kind: "inspect_story_workflow",
      reason: "workflow_state_unreadable",
      label: "Inspect the bound story workflow before continuing.",
      command: statusCliCommand("workflow", "instance", "status", "--id", selected.entry),
      protected: true,
      story_id: story.id,
      workflow_instance_id: selected.entry,
    };
  }
  const currentState = workflowCurrentState(
    integrity.replay,
    instance,
    effectiveDefinition,
  );
  if (!fs.existsSync(taskStartPath)) {
    return {
      kind: "start_available_work",
      reason: "workflow_started_before_task",
      label: "The story workflow is bound; provide the governed task intent before starting work.",
      command: statusCliCommand("help", "task", "start"),
      protected: true,
      story_id: story.id,
      workflow_instance_id: selected.entry,
    };
  }
  const terminal = (effectiveDefinition.states || [])
    .find((state) => state.id === currentState)?.terminal === true;
  if (terminal) {
    const finalReceipt = validCurrentWorkflowFinalReceipt(context, story.id, instance);
    if (finalReceipt.valid) return null;
    if (finalReceipt.exists) {
      return {
        kind: "recertify_lifecycle",
        reason: "final_lifecycle_receipt_invalid",
        label:
          "The final lifecycle receipt no longer matches current governed evidence; repair any reported evidence drift and reseal this exact story lifecycle.",
        command: statusCliCommand(
          "gate", "check",
          "--strict",
          "--story", story.id,
          "--lifecycle-complete",
        ),
        protected: true,
        story_id: story.id,
        workflow_instance_id: selected.entry,
      };
    }
  }
  // Release evidence and the active claim must clear once the workflow enters
  // "release", not only once it reaches the terminal phase: a phase configured
  // after release (such as operations) makes "release" itself non-terminal,
  // but delivery still has to close before that later phase is entered.
  if (currentState === "release" || terminal) {
    const releaseReadiness = storyReleaseReadiness(context, story.id);
    if (!releaseReadiness.ready) {
      const command = releaseReadiness.profile_id
        ? statusCliCommand("autonomy", "delivery", "status", "--id", releaseReadiness.profile_id)
        : statusCliCommand("help", "trace", "append");
      return {
        kind: "complete_release_evidence",
        reason: "release_phase_evidence_incomplete",
        label: `Complete release evidence before final certification: ${releaseReadiness.missing.join(", ")}.`,
        command,
        protected: true,
        story_id: story.id,
        workflow_instance_id: selected.entry,
        missing_release_evidence: releaseReadiness.missing,
      };
    }
    const claimPath = path.join(context.sdlcRoot, "stories", story.id, "claim.json");
    if (fs.existsSync(claimPath)) {
      const claim = readProjectJson(context, claimPath);
      if (claim.status === "active") {
        return {
          kind: "release_story_claim",
          reason: "final_certification_requires_released_claim",
          label: "Release the completed story claim before final lifecycle certification.",
          command: statusCliCommand("story", "release", "--id", story.id),
          protected: true,
          story_id: story.id,
          workflow_instance_id: selected.entry,
          claimed_by: claim.agent || null,
        };
      }
    }
  }
  if (terminal) {
    return {
      kind: "certify_lifecycle",
      reason: "workflow_terminal",
      label: "Certify the complete local lifecycle after release evidence and terminal delivery are ready.",
      command: statusCliCommand(
        "gate", "check", "--strict", "--story", story.id, "--lifecycle-complete",
      ),
      protected: true,
      story_id: story.id,
      workflow_instance_id: selected.entry,
    };
  }
  const currentStepCompleted = completedSteps.some((record) => record.phase === currentState);
  const outgoingTransition = (effectiveDefinition.transitions || [])
    .find((transition) => transition.from === currentState) || null;
  const nextState = outgoingTransition?.to || null;
  const nextStateRequiresStrictGate = (outgoingTransition?.guards || [])
    .some((guard) => guard?.id === "strict-gate-passed");
  if (currentStepCompleted && nextStateRequiresStrictGate) {
    const strictGate = currentStoryStrictGateReadiness(
      context,
      story.id,
      instance,
      effectiveDefinition,
      integrity,
      currentState,
    );
    if (!strictGate.ready) {
      if (strictGate.repair) {
        return {
          ...strictGate.repair,
          protected: true,
          story_id: story.id,
          workflow_instance_id: selected.entry,
          strict_gate_issues: strictGate.issues,
        };
      }
      return {
        kind: "seal_strict_gate",
        reason: strictGate.reason === "missing"
          ? "release_transition_needs_strict_gate"
          : "release_transition_strict_gate_stale",
        label: strictGate.reason === "missing"
          ? "Seal the intermediate strict receipt before entering the release phase."
          : "Re-run the intermediate strict gate because its receipt is invalid or older than current evidence.",
        command: statusCliCommand("gate", "check", "--strict", "--story", story.id),
        protected: true,
        story_id: story.id,
        workflow_instance_id: selected.entry,
        strict_gate_issues: strictGate.issues,
      };
    }
  }
  if (currentStepCompleted && nextState) {
    return {
      kind: "advance_story_workflow",
      reason: "current_phase_completed",
      label: `Advance the governed workflow from ${currentState} to ${nextState}.`,
      command: statusCliCommand(
        "workflow", "instance", "transition",
        "--id", selected.entry,
        "--to", nextState,
        "--request-id", `${selected.entry}-${currentState}-to-${nextState}`,
      ),
      protected: true,
      story_id: story.id,
      workflow_instance_id: selected.entry,
      current_phase: currentState,
      next_phase: nextState,
    };
  }
  return {
    kind: "inspect_story_workflow",
    reason: "current_phase_in_progress",
    label: `Complete the governed '${currentState}' step before advancing the workflow.`,
    command: statusCliCommand("workflow", "instance", "status", "--id", selected.entry),
    protected: false,
    story_id: story.id,
    workflow_instance_id: selected.entry,
    current_phase: currentState,
  };
}

function buildStatusNextAction(context, summary, orchestration, counts, project) {
  if (summary.pending_decisions > 0) {
    for (const story of orchestration.stories.filter((item) =>
      ["available", "claimed"].includes(item.orchestration_state))) {
      const workflowNextAction = buildStoryWorkflowNextAction(context, story);
      if ([
        "seal_strict_gate",
        "repair_strict_gate_evidence",
        "repair_output_link",
        "reapprove_output_template",
      ].includes(workflowNextAction?.kind)) {
        return workflowNextAction;
      }
    }
    return {
      kind: "review_decision",
      reason: "pending_human_decision",
      label: "Review the pending project decision.",
      command: statusCliCommand("approval", "requests"),
      protected: true,
    };
  }
  if (summary.blocked_work > 0) {
    const story = orchestration.stories.find((item) => item.orchestration_state === "blocked");
    const workflowNextAction = story
      ? buildStoryWorkflowNextAction(context, story)
      : null;
    if (
      story?.lifecycle_source !== "story_record"
      && workflowNextAction
    ) {
      return workflowNextAction;
    }
    return {
      kind: "resolve_blocker",
      reason: "blocked_story",
      label: "Resolve the first blocked story.",
      command: story
        ? statusCliCommand("story", "deps", "--id", story.id)
        : statusCliCommand("orchestrate", "status"),
      protected: false,
      story_id: story?.id || null,
    };
  }
  if (summary.stale_claims > 0) {
    const story = orchestration.stories.find((item) => item.orchestration_state === "stale");
    return {
      kind: "repair_claim",
      reason: "stale_claim",
      label: "Repair the stale work reservation.",
      command: story
        ? statusCliCommand("story", "release", "--id", story.id)
        : statusCliCommand("orchestrate", "status"),
      protected: true,
      story_id: story?.id || null,
    };
  }
  const operationalStories = orchestration.stories.filter((item) =>
    ["available", "claimed"].includes(item.orchestration_state));
  for (const story of operationalStories) {
    const workflowNextAction = buildStoryWorkflowNextAction(context, story);
    if (workflowNextAction) return workflowNextAction;
  }
  if (summary.completed_work > 0) {
    return {
      kind: "none",
      reason: "completed_work_terminal",
      label:
        `${summary.completed_work} governed work item${summary.completed_work === 1 ? " is" : "s are"} `
        + "terminal; no operational work is waiting.",
      command: null,
      protected: false,
      terminal_work: summary.completed_work,
    };
  }
  const baselines = readBaselines(context);
  if (baselines.length === 0) {
    const hasExistingEvidence =
      discoverExistingProjectDocuments(context).length > 0
      || detectProjectStack(context).length > 0;
    if (hasExistingEvidence) {
      return {
        kind: "onboard_project",
        reason: "project_context_not_onboarded",
        label: "Onboard the existing project context, then review what was inferred.",
        command: statusCliCommand(
          "onboard", "existing-project",
          "--root", context.root,
          "--project-name", project.project_name,
        ),
        protected: true,
      };
    }
  }
  if ((counts.requirements || 0) === 0) {
    return {
      kind: "agree_requirement",
      reason: "requirement_not_described",
      label: "Describe the required outcome, observable success, exclusions, and maximum independence.",
      command: null,
      protected: true,
    };
  }
  return {
    kind: "none",
    reason: "no_operational_work",
    label: "No operational work is waiting.",
    command: null,
    protected: false,
  };
}

